import type { BankQuestion } from "@/lib/bank";

/** Time and Work (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-time-work-1","question":"If A can do a piece of work in 8 days, the fraction of work A does in one day is:","options":["1/4","1/8","1/16","8"],"answer":1,"explanation":"If the whole work takes 8 days, one day's share is 1 ÷ 8 = 1/8. Answering 8 confuses the time taken with the rate of work, and 1/4 or 1/16 halve or double it.","difficulty":"easy","questionHi":"यदि A किसी कार्य को 8 दिन में कर सकता है, तो A एक दिन में कार्य का कितना भाग करता है?","optionsHi":["1/4","1/8","1/16","8"],"explanationHi":"यदि पूरा कार्य 8 दिन में होता है, तो एक दिन का भाग 1 ÷ 8 = 1/8 होगा। 8 उत्तर देना समय और कार्य की दर को मिला देना है, तथा 1/4 या 1/16 में दर आधी या दोगुनी हो जाती है।","subtopic":"combined-work"},
  {"id":"quant-time-work-2","question":"If 6 workers finish a job in 12 days, how many days will 9 workers take at the same rate?","options":["6","8","9","18"],"answer":1,"explanation":"Work = 6 × 12 = 72 worker-days, so 9 workers need 72 ÷ 9 = 8 days. 18 assumes days rise with workers (direct proportion), the classic inverse-variation trap.","difficulty":"moderate","questionHi":"यदि 6 कर्मचारी किसी कार्य को 12 दिन में पूरा करते हैं, तो समान दर से 9 कर्मचारी कितने दिन लेंगे?","optionsHi":["6","8","9","18"],"explanationHi":"कार्य = 6 × 12 = 72 कर्मचारी-दिन, इसलिए 9 कर्मचारियों को 72 ÷ 9 = 8 दिन लगेंगे। 18 मानता है कि कर्मचारी बढ़ने पर दिन भी बढ़ते हैं (समानुपात), जो व्युत्क्रम अनुपात की सामान्य भूल है।","subtopic":"men-women-children"},
  {"id":"quant-time-work-3","question":"A is twice as efficient as B. If together they finish a job in 12 days, A alone would take:","options":["18 days","24 days","36 days","16 days"],"answer":0,"explanation":"Let B’s rate be 1 and A’s 2: together 3 units/day, total work 36 units; A alone = 36 ÷ 2 = 18 days.","difficulty":"very-hard","questionHi":"A, B से दोगुना कुशल है। यदि दोनों मिलकर कार्य को 12 दिन में पूरा करते हैं, तो A अकेला कितना समय लेगा?","optionsHi":["18 दिन","24 दिन","36 दिन","16 दिन"],"explanationHi":"मान लीजिए B की दर 1 और A की दर 2 है: साथ में 3 इकाई/दिन, कुल कार्य 36 इकाई; A अकेला = 36 ÷ 2 = 18 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-4","question":"A can finish a work in 10 days and B in 15 days. Together they finish it in:","options":["5 days","6 days","8 days","12 days"],"answer":1,"explanation":"Add rates: 1/10 + 1/15 = 3/30 + 2/30 = 1/6, so 6 days (or product/sum = 150/25). Together they must beat the faster worker's 10 days, which rules out 12; 5 days simply halves 10.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"A किसी कार्य को 10 दिन में और B 15 दिन में पूरा कर सकता है। दोनों मिलकर उसे कितने समय में पूरा करेंगे?","optionsHi":["5 दिन","6 दिन","8 दिन","12 दिन"],"explanationHi":"दरें जोड़ने पर: 1/10 + 1/15 = 3/30 + 2/30 = 1/6, इसलिए 6 दिन (या गुणनफल/योग = 150/25)। साथ में उन्हें तेज़ कार्यकर्ता के 10 दिन से कम समय लगना चाहिए, इसलिए 12 गलत है; 5 दिन केवल 10 का आधा लेना है।","subtopic":"combined-work"},
  {"id":"quant-time-work-5","question":"A and B together finish a job in 12 days; A alone takes 20 days. B alone takes:","options":["24 days","30 days","32 days","40 days"],"answer":1,"explanation":"B's rate = 1/12 − 1/20 = (5 − 3)/60 = 1/30, so 30 days. 24 doubles the joint time and 40 doubles A's time; check: 1/20 + 1/30 = 1/12.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"A और B मिलकर किसी कार्य को 12 दिन में पूरा करते हैं; A अकेला 20 दिन लेता है। B अकेला कितने दिन लेगा?","optionsHi":["24 दिन","30 दिन","32 दिन","40 दिन"],"explanationHi":"B की दर = 1/12 − 1/20 = (5 − 3)/60 = 1/30, इसलिए 30 दिन। 24 संयुक्त समय का दोगुना है और 40 A के समय का दोगुना है; जाँच: 1/20 + 1/30 = 1/12।","subtopic":"combined-work"},
  {"id":"quant-time-work-6","question":"A can do a work in 12 days. After working 4 days he leaves and B finishes the rest in 16 days. B alone would take:","options":["20 days","24 days","28 days","32 days"],"answer":1,"explanation":"In 4 days A does 4/12 = 1/3, so B does the remaining 2/3 in 16 days and would take 16 × 3/2 = 24 days alone. 32 days doubles 16, treating the remaining work as one half.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"A किसी कार्य को 12 दिन में कर सकता है। 4 दिन कार्य करने के बाद वह चला जाता है और शेष कार्य B 16 दिन में पूरा करता है। B अकेला उसे कितने दिन में करेगा?","optionsHi":["20 दिन","24 दिन","28 दिन","32 दिन"],"explanationHi":"4 दिन में A कार्य का 4/12 = 1/3 भाग करता है, इसलिए B शेष 2/3 भाग 16 दिन में करता है और अकेले उसे 16 × 3/2 = 24 दिन लगेंगे। 32 दिन में 16 को दोगुना कर लिया गया है, यह मानकर कि शेष कार्य आधा था।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-7","question":"12 men complete a work in 18 days. After 6 days, 4 more men join. The remaining work is finished in:","options":["8 days","9 days","10 days","12 days"],"answer":1,"explanation":"Total = 12 × 18 = 216 man-days; after 6 days, 12 × 12 = 144 man-days remain, so 16 men need 144/16 = 9 days. 12 days ignores the extra men, and 8 days divides 144 by 18.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"12 आदमी किसी कार्य को 18 दिन में पूरा करते हैं। 6 दिन बाद 4 और आदमी जुड़ जाते हैं। शेष कार्य कितने दिन में पूरा होगा?","optionsHi":["8 दिन","9 दिन","10 दिन","12 दिन"],"explanationHi":"कुल = 12 × 18 = 216 आदमी-दिन; 6 दिन बाद 12 × 12 = 144 आदमी-दिन शेष हैं, इसलिए 16 आदमियों को 144/16 = 9 दिन लगेंगे। 12 दिन अतिरिक्त आदमियों को अनदेखा करता है, और 8 दिन में 144 को 18 से भाग दिया गया है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-8","question":"A does one-third of a work in 6 days. He will finish the whole work in:","options":["9 days","24 days","12 days","18 days"],"answer":3,"explanation":"One-third in 6 days means the whole in 3 × 6 = 18 days. 12 days is only the time for the remaining two-thirds, not for the whole work.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"A किसी कार्य का एक-तिहाई भाग 6 दिन में करता है। वह पूरा कार्य कितने दिन में समाप्त करेगा?","optionsHi":["9 दिन","24 दिन","12 दिन","18 दिन"],"explanationHi":"एक-तिहाई कार्य 6 दिन में होने का अर्थ है कि पूरा कार्य 3 × 6 = 18 दिन में होगा। 12 दिन केवल शेष दो-तिहाई कार्य का समय है, पूरे कार्य का नहीं।","subtopic":"combined-work"},
  {"id":"quant-time-work-9","question":"One pipe fills a tank in 6 hours and another in 12 hours. Together they fill it in:","options":["4 hours","8 hours","9 hours","3 hours"],"answer":0,"explanation":"Combined rate = 1/6 + 1/12 = 3/12 = 1/4 of the tank per hour, so 4 hours. Averaging 6 and 12 to get 9 is wrong.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"एक पाइप किसी टंकी को 6 घंटे में और दूसरा 12 घंटे में भरता है। दोनों मिलकर उसे कितने समय में भरेंगे?","optionsHi":["4 घंटे","8 घंटे","9 घंटे","3 घंटे"],"explanationHi":"संयुक्त दर = 1/6 + 1/12 = 3/12 = 1/4 टंकी प्रति घंटा, इसलिए 4 घंटे। 6 और 12 का औसत लेकर 9 निकालना गलत है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-10","question":"A and B can do a work in 12 days, B and C in 15 days, and C and A in 20 days. All three together will finish it in:","options":["15 days","20 days","5 days","10 days"],"answer":3,"explanation":"Adding: 2(A + B + C) = 1/12 + 1/15 + 1/20 = (5 + 4 + 3)/60 = 12/60, so A + B + C = 6/60 = 1/10 per day: 10 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A और B किसी कार्य को 12 दिन में, B और C 15 दिन में तथा C और A 20 दिन में कर सकते हैं। तीनों मिलकर उसे कितने दिन में पूरा करेंगे?","optionsHi":["15 दिन","20 दिन","5 दिन","10 दिन"],"explanationHi":"जोड़ने पर: 2(A + B + C) = 1/12 + 1/15 + 1/20 = (5 + 4 + 3)/60 = 12/60, इसलिए A + B + C = 6/60 = 1/10 प्रति दिन: 10 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-11","question":"A can do a work in 20 days and B in 30 days. They begin together, but A leaves 5 days before the work is completed. The work is completed in:","options":["12 days","17 days","15 days","10 days"],"answer":2,"explanation":"Let the work take t days: B works all t days, A works t − 5. (t − 5)/20 + t/30 = 1 → 3(t − 5) + 2t = 60 → 5t = 75 → t = 15 days.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"A किसी कार्य को 20 दिन में और B 30 दिन में कर सकता है। वे साथ मिलकर शुरू करते हैं, परंतु कार्य पूरा होने से 5 दिन पहले A चला जाता है। कार्य कितने दिन में पूरा होता है?","optionsHi":["12 दिन","17 दिन","15 दिन","10 दिन"],"explanationHi":"मान लीजिए कार्य में t दिन लगते हैं: B सभी t दिन काम करता है, A t − 5 दिन। (t − 5)/20 + t/30 = 1 → 3(t − 5) + 2t = 60 → 5t = 75 → t = 15 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-12","question":"10 men or 15 women can do a work in 12 days. In how many days will 8 men and 6 women finish it?","options":["9 days","8 days","12 days","10 days"],"answer":3,"explanation":"1 man = 1.5 women, so 8 men + 6 women = 12 + 6 = 18 women. 15 women take 12 days, so 18 women take 15 × 12/18 = 10 days.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"10 पुरुष या 15 महिलाएँ किसी कार्य को 12 दिन में कर सकते हैं। 8 पुरुष और 6 महिलाएँ उसे कितने दिन में पूरा करेंगे?","optionsHi":["9 दिन","8 दिन","12 दिन","10 दिन"],"explanationHi":"1 पुरुष = 1.5 महिलाएँ, इसलिए 8 पुरुष + 6 महिलाएँ = 12 + 6 = 18 महिलाएँ। 15 महिलाएँ 12 दिन लेती हैं, तो 18 महिलाएँ 15 × 12/18 = 10 दिन लेंगी।","subtopic":"men-women-children"},
  {"id":"quant-time-work-13","question":"A pipe can fill a tank in 8 hours and a drain can empty it in 12 hours. If both are open, the empty tank fills in:","options":["16 hours","20 hours","24 hours","4.8 hours"],"answer":2,"explanation":"Net rate = 1/8 − 1/12 = 1/24 per hour, so 24 hours. 4.8 h is the slip of adding the rates.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक पाइप किसी टंकी को 8 घंटे में भर सकता है और एक निकास पाइप उसे 12 घंटे में खाली कर सकता है। यदि दोनों खुले हों, तो खाली टंकी कितने समय में भरेगी?","optionsHi":["16 घंटे","20 घंटे","24 घंटे","4.8 घंटे"],"explanationHi":"शुद्ध दर = 1/8 − 1/12 = 1/24 प्रति घंटा, इसलिए 24 घंटे। 4.8 घंटे दरों को जोड़ देने की भूल है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-14","question":"A is 50% more efficient than B. If B alone can do a work in 15 days, A and B together will do it in:","options":["6 days","7.5 days","9 days","5 days"],"answer":0,"explanation":"A takes 15/1.5 = 10 days. Together: 1/10 + 1/15 = 1/6, so 6 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A, B से 50% अधिक कुशल है। यदि B अकेला किसी कार्य को 15 दिन में कर सकता है, तो A और B मिलकर उसे कितने दिन में करेंगे?","optionsHi":["6 दिन","7.5 दिन","9 दिन","5 दिन"],"explanationHi":"A को 15/1.5 = 10 दिन लगते हैं। साथ में: 1/10 + 1/15 = 1/6, इसलिए 6 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-15","question":"Two pipes fill a tank in 12 hours and 16 hours. Both are opened together, and after 4 hours the first pipe is closed. The remaining part is filled by the second pipe in:","options":["7 hours","6 hours 40 minutes","6 hours","5 hours 20 minutes"],"answer":1,"explanation":"In 4 hours both fill 4(1/12 + 1/16) = 4 × 7/48 = 7/12. The remaining 5/12 at 1/16 per hour takes 5/12 × 16 = 20/3 hours = 6 h 40 min.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"दो पाइप एक टंकी को 12 घंटे और 16 घंटे में भरते हैं। दोनों को एक साथ खोला जाता है और 4 घंटे बाद पहला पाइप बंद कर दिया जाता है। शेष भाग दूसरा पाइप कितने समय में भरेगा?","optionsHi":["7 घंटे","6 घंटे 40 मिनट","6 घंटे","5 घंटे 20 मिनट"],"explanationHi":"4 घंटे में दोनों मिलकर 4(1/12 + 1/16) = 4 × 7/48 = 7/12 भरते हैं। शेष 5/12 भाग 1/16 प्रति घंटा की दर से भरने में 5/12 × 16 = 20/3 घंटे = 6 घंटे 40 मिनट लगते हैं।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-16","question":"A, B and C can do a work in 24, 30 and 40 days respectively. They start together, but C leaves 4 days and B leaves 6 days before the work is finished. The work is finished in:","options":["11 days","13 days","12 days","15 days"],"answer":1,"explanation":"Take the work as 120 units: rates 5, 4, 3 per day. If it takes T days, 5T + 4(T − 6) + 3(T − 4) = 120 → 12T − 36 = 120 → T = 13 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A, B और C किसी कार्य को क्रमशः 24, 30 और 40 दिन में कर सकते हैं। वे साथ शुरू करते हैं, परंतु कार्य समाप्त होने से 4 दिन पहले C और 6 दिन पहले B चला जाता है। कार्य कितने दिन में पूरा होता है?","optionsHi":["11 दिन","13 दिन","12 दिन","15 दिन"],"explanationHi":"कार्य को 120 इकाई लें: दरें 5, 4, 3 प्रति दिन हैं। यदि कुल T दिन लगें, तो 5T + 4(T − 6) + 3(T − 4) = 120 → 12T − 36 = 120 → T = 13 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-17","question":"A can do a work in 12 days and B in 18 days. They work on alternate days with A starting. The work is completed in:","options":["14½ days","15 days","14⅓ days","14 days"],"answer":2,"explanation":"Work = 36 units: A does 3, B does 2 per day, 5 units per 2-day cycle. 7 cycles (14 days) do 35 units; the last unit is done by A on day 15 in 1/3 day. Total 14⅓ days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य को 12 दिन में और B 18 दिन में कर सकता है। वे एकांतर दिनों में कार्य करते हैं और A शुरुआत करता है। कार्य कितने दिन में पूरा होता है?","optionsHi":["14½ दिन","15 दिन","14⅓ दिन","14 दिन"],"explanationHi":"कार्य = 36 इकाई: A प्रतिदिन 3 और B प्रतिदिन 2 इकाई करता है, यानी 2 दिन के चक्र में 5 इकाई। 7 चक्र (14 दिन) में 35 इकाई होती हैं; अंतिम इकाई A दिन 15 में 1/3 दिन में करता है। कुल 14⅓ दिन।","subtopic":"alternate-days"},
  {"id":"quant-time-work-18","question":"A, B and C can do a work alone in 6, 8 and 12 days respectively. Working together they are paid ₹2,700. B's share is:","options":["₹600","₹900","₹1,000","₹1,200"],"answer":1,"explanation":"Wages are shared in the ratio of work done, i.e. of rates: 1/6 : 1/8 : 1/12 = 4 : 3 : 2. B gets 3/9 × 2,700 = ₹900.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"A, B और C किसी कार्य को अकेले क्रमशः 6, 8 और 12 दिन में कर सकते हैं। साथ मिलकर कार्य करने पर उन्हें ₹2,700 मिलते हैं। B का हिस्सा कितना है?","optionsHi":["₹600","₹900","₹1,000","₹1,200"],"explanationHi":"मजदूरी किए गए कार्य के अनुपात में, यानी दरों के अनुपात में बँटती है: 1/6 : 1/8 : 1/12 = 4 : 3 : 2। B को 3/9 × 2,700 = ₹900 मिलेंगे।","subtopic":"work-wages"},
  {"id":"quant-time-work-19","question":"Pipe A fills a tank in 6 hours and pipe B in 8 hours. They are opened for one hour each alternately, A first. The tank is filled in:","options":["6 hours 45 minutes","6 hours 30 minutes","6 hours 51 minutes","7 hours"],"answer":0,"explanation":"Tank = 24 units: A gives 4 per hour, B gives 3, so 7 units per 2-hour cycle. After 3 cycles (6 h) 21 units are in; A fills the last 3 units in 3/4 hour. Total 6 h 45 min. 6 h 51 min comes from wrongly averaging the rates.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"पाइप A एक टंकी को 6 घंटे में और पाइप B 8 घंटे में भरता है। उन्हें एकांतर रूप से एक-एक घंटे के लिए खोला जाता है, पहले A। टंकी कितने समय में भरती है?","optionsHi":["6 घंटे 45 मिनट","6 घंटे 30 मिनट","6 घंटे 51 मिनट","7 घंटे"],"explanationHi":"टंकी = 24 इकाई: A प्रति घंटा 4 और B 3 इकाई भरता है, यानी 2 घंटे के चक्र में 7 इकाई। 3 चक्र (6 घंटे) बाद 21 इकाई भर चुकी होती हैं; शेष 3 इकाई A 3/4 घंटे में भरता है। कुल 6 घंटे 45 मिनट। 6 घंटे 51 मिनट दरों का गलत औसत लेने से आता है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-20","question":"12 men and 16 boys can do a work in 5 days; 13 men and 24 boys can do it in 4 days. The ratio of the daily work of a man to that of a boy is:","options":["2 : 1","1 : 2","3 : 1","3 : 2"],"answer":0,"explanation":"Total work: 5(12m + 16b) = 4(13m + 24b) → 60m + 80b = 52m + 96b → 8m = 16b → m : b = 2 : 1.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"12 पुरुष और 16 लड़के किसी कार्य को 5 दिन में कर सकते हैं; 13 पुरुष और 24 लड़के उसे 4 दिन में कर सकते हैं। एक पुरुष और एक लड़के के दैनिक कार्य का अनुपात क्या है?","optionsHi":["2 : 1","1 : 2","3 : 1","3 : 2"],"explanationHi":"कुल कार्य: 5(12m + 16b) = 4(13m + 24b) → 60m + 80b = 52m + 96b → 8m = 16b → m : b = 2 : 1।","subtopic":"men-women-children"},
  {"id":"quant-time-work-21","question":"A is twice as efficient as B, and B is thrice as efficient as C. Together they finish a work in 10 days. C alone would take:","options":["30 days","60 days","90 days","100 days"],"answer":3,"explanation":"Rates A : B : C = 6 : 3 : 1, total 10 units a day, so the work = 100 units. C alone at 1 unit a day takes 100 days.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"A, B से दोगुना कुशल है और B, C से तिगुना कुशल है। साथ मिलकर वे कार्य को 10 दिन में पूरा करते हैं। C अकेला कितना समय लेगा?","optionsHi":["30 दिन","60 दिन","90 दिन","100 दिन"],"explanationHi":"दरों का अनुपात A : B : C = 6 : 3 : 1, कुल 10 इकाई प्रतिदिन, इसलिए कार्य = 100 इकाई। C अकेला 1 इकाई प्रतिदिन की दर से 100 दिन लेगा।","subtopic":"efficiency"},
  {"id":"quant-time-work-22","question":"A certain number of workers can finish a job in 30 days. If there were 10 workers fewer, it would take 10 days more. The number of workers is:","options":["50","40","20","30"],"answer":1,"explanation":"Man-days are equal: 30N = 40(N − 10) → 30N = 40N − 400 → N = 40.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"कुछ कर्मचारी किसी कार्य को 30 दिन में पूरा कर सकते हैं। यदि 10 कर्मचारी कम होते, तो उसमें 10 दिन अधिक लगते। कर्मचारियों की संख्या कितनी है?","optionsHi":["50","40","20","30"],"explanationHi":"आदमी-दिन समान रहते हैं: 30N = 40(N − 10) → 30N = 40N − 400 → N = 40।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-23","question":"A contractor undertakes to build a road in 40 days with 50 men. After 20 days he finds that only one-third of the road is built. How many more men must he employ to finish on time?","options":["75","50","100","25"],"answer":1,"explanation":"50 × 20 = 1,000 man-days did one-third, so the whole road needs 3,000 man-days. The remaining 2,000 man-days in 20 days need 100 men, i.e. 50 more.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"एक ठेकेदार 50 आदमियों के साथ 40 दिन में सड़क बनाने का ठेका लेता है। 20 दिन बाद उसे पता चलता है कि सड़क का केवल एक-तिहाई भाग बना है। समय पर कार्य पूरा करने के लिए उसे कितने और आदमी लगाने होंगे?","optionsHi":["75","50","100","25"],"explanationHi":"50 × 20 = 1,000 आदमी-दिन में एक-तिहाई कार्य हुआ, इसलिए पूरी सड़क के लिए 3,000 आदमी-दिन चाहिए। शेष 2,000 आदमी-दिन 20 दिन में पूरे करने के लिए 100 आदमी चाहिए, यानी 50 और।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-24","question":"Two inlet pipes fill a tank in 10 and 15 hours and an outlet empties it in 12 hours. All three are opened on an empty tank; after 4 hours the outlet is closed. The tank is full after a total of:","options":["8 hours","10 hours","6 hours","12 hours"],"answer":0,"explanation":"Tank = 60 units: rates +6, +4, −5, net 5 per hour. In 4 hours 20 units are in. The remaining 40 at 10 per hour take 4 hours. Total 8 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"दो अंतर्वाह पाइप एक टंकी को 10 और 15 घंटे में भरते हैं और एक निकास पाइप उसे 12 घंटे में खाली करता है। खाली टंकी पर तीनों को खोला जाता है; 4 घंटे बाद निकास पाइप बंद कर दिया जाता है। टंकी कुल कितने समय बाद भर जाएगी?","optionsHi":["8 घंटे","10 घंटे","6 घंटे","12 घंटे"],"explanationHi":"टंकी = 60 इकाई: दरें +6, +4, −5, शुद्ध 5 प्रति घंटा। 4 घंटे में 20 इकाई भरती हैं। शेष 40 इकाई 10 प्रति घंटा की दर से 4 घंटे में भरती हैं। कुल 8 घंटे।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-25","question":"How many of the following statements are correct?\n1. If A is twice as efficient as B, A takes half the time B takes.\n2. If 2 men do as much as 3 women, then 4 men and 3 women equal 9 women.\n3. If A does a work in 10 days and B in 15 days, together they take 6 days.\n4. A pipe fills a tank in 4 hours and a drain empties it in 6 hours; with both open the tank fills in 10 hours.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1 is true. 2 is true (4 men = 6 women; 6 + 3 = 9). 3 is true (1/10 + 1/15 = 1/6). 4 is false: 1/4 − 1/6 = 1/12, so 12 hours. Three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. यदि A, B से दोगुना कुशल है, तो A, B का आधा समय लेता है।\n2. यदि 2 पुरुष उतना ही कार्य करते हैं जितना 3 महिलाएँ, तो 4 पुरुष और 3 महिलाएँ 9 महिलाओं के बराबर हैं।\n3. यदि A किसी कार्य को 10 दिन में और B 15 दिन में करता है, तो साथ में वे 6 दिन लेते हैं।\n4. एक पाइप टंकी को 4 घंटे में भरता है और एक निकास पाइप उसे 6 घंटे में खाली करता है; दोनों खुले होने पर टंकी 10 घंटे में भरती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"1 सही है। 2 सही है (4 पुरुष = 6 महिलाएँ; 6 + 3 = 9)। 3 सही है (1/10 + 1/15 = 1/6)। 4 गलत है: 1/4 − 1/6 = 1/12, इसलिए 12 घंटे। तीन कथन सही हैं।","subtopic":"efficiency"},
  {"id":"quant-time-work-26","question":"A and B undertake to do a work for ₹1,200. A alone can do it in 6 days and B alone in 8 days. With the help of C they finish it in 3 days. C's share is:","options":["₹100","₹200","₹180","₹150"],"answer":3,"explanation":"In 3 days A and B do 3(1/6 + 1/8) = 7/8 of the work, so C did 1/8 and gets 1/8 × 1,200 = ₹150.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"A और B ₹1,200 में किसी कार्य को करने का ठेका लेते हैं। A अकेला उसे 6 दिन में और B अकेला 8 दिन में कर सकता है। C की सहायता से वे उसे 3 दिन में पूरा कर लेते हैं। C का हिस्सा कितना है?","optionsHi":["₹100","₹200","₹180","₹150"],"explanationHi":"3 दिन में A और B मिलकर 3(1/6 + 1/8) = 7/8 कार्य करते हैं, इसलिए C ने 1/8 कार्य किया और उसे 1/8 × 1,200 = ₹150 मिलेंगे।","subtopic":"work-wages"},
  {"id":"quant-time-work-27","question":"A and B together can do a work in 12 days, and B and C together in 16 days. A worked for 5 days, B for 7 days and C finished the remaining work in 13 days. C alone can do the work in:","options":["16 days","48 days","24 days","32 days"],"answer":2,"explanation":"Work = 48 units: A + B = 4 per day, B + C = 3 per day. 5A + 7B + 13C = 5(A + B) + 2(B + C) + 11C = 20 + 6 + 11C = 48 → C = 2 units a day → 24 days.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"A और B मिलकर किसी कार्य को 12 दिन में तथा B और C मिलकर 16 दिन में कर सकते हैं। A ने 5 दिन, B ने 7 दिन कार्य किया और शेष कार्य C ने 13 दिन में पूरा किया। C अकेला उस कार्य को कितने दिन में कर सकता है?","optionsHi":["16 दिन","48 दिन","24 दिन","32 दिन"],"explanationHi":"कार्य = 48 इकाई: A + B = 4 प्रति दिन, B + C = 3 प्रति दिन। 5A + 7B + 13C = 5(A + B) + 2(B + C) + 11C = 20 + 6 + 11C = 48 → C = 2 इकाई प्रतिदिन → 24 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-28","question":"A can finish a work in 20 days and B in 30 days. In how many days can they finish it together?","options":["25 days","12 days","10 days","15 days"],"answer":1,"explanation":"One day's work = 1/20 + 1/30 = 5/60 = 1/12, so 12 days. 25 days is the average of the times, a common slip.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"A किसी कार्य को 20 दिन में और B 30 दिन में कर सकता है। दोनों मिलकर उसे कितने दिन में पूरा कर सकते हैं?","optionsHi":["25 दिन","12 दिन","10 दिन","15 दिन"],"explanationHi":"एक दिन का कार्य = 1/20 + 1/30 = 5/60 = 1/12, इसलिए 12 दिन। 25 दिन समयों का औसत लेना है, जो एक सामान्य भूल है।","subtopic":"combined-work"},
  {"id":"quant-time-work-29","question":"15 men working 8 hours a day build a wall in 24 days. How many days will 20 men working 9 hours a day take to build the same wall?","options":["16 days","18 days","20 days","14 days"],"answer":0,"explanation":"Work = 15 × 24 × 8 = 2,880 man-hours = 20 × 9 × d, so d = 16 days.","difficulty":"moderate","source":"SSC CGL","questionHi":"प्रतिदिन 8 घंटे काम करने वाले 15 आदमी एक दीवार 24 दिन में बनाते हैं। प्रतिदिन 9 घंटे काम करने वाले 20 आदमी उसी दीवार को कितने दिन में बनाएँगे?","optionsHi":["16 दिन","18 दिन","20 दिन","14 दिन"],"explanationHi":"कार्य = 15 × 24 × 8 = 2,880 आदमी-घंटे = 20 × 9 × d, इसलिए d = 16 दिन।","subtopic":"men-women-children"},
  {"id":"quant-time-work-30","question":"A pipe fills a tank in 10 hours, but because of a leak it takes 12 hours. In how many hours can the leak empty the full tank?","options":["22 hours","2 hours","120 hours","60 hours"],"answer":3,"explanation":"Leak rate = 1/10 − 1/12 = 1/60 of the tank per hour, so it empties the tank in 60 hours.","difficulty":"moderate","source":"SSC CGL","questionHi":"एक पाइप टंकी को 10 घंटे में भरता है, परंतु रिसाव के कारण उसे 12 घंटे लगते हैं। भरी हुई टंकी को रिसाव कितने घंटे में खाली कर देगा?","optionsHi":["22 घंटे","2 घंटे","120 घंटे","60 घंटे"],"explanationHi":"रिसाव की दर = 1/10 − 1/12 = 1/60 टंकी प्रति घंटा, इसलिए वह टंकी को 60 घंटे में खाली करेगा।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-31","question":"A is three times as efficient as B and finishes a job 40 days sooner than B. In how many days can they finish it together?","options":["20 days","30 days","15 days","10 days"],"answer":2,"explanation":"If A takes t days, B takes 3t, so 3t − t = 40 → t = 20; B takes 60. Together 1/20 + 1/60 = 4/60 → 15 days.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"A, B से तिगुना कुशल है और किसी कार्य को B से 40 दिन पहले पूरा करता है। दोनों मिलकर उसे कितने दिन में पूरा कर सकते हैं?","optionsHi":["20 दिन","30 दिन","15 दिन","10 दिन"],"explanationHi":"यदि A को t दिन लगते हैं, तो B को 3t दिन लगते हैं, इसलिए 3t − t = 40 → t = 20; B को 60 दिन लगते हैं। साथ में 1/20 + 1/60 = 4/60 → 15 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-32","question":"A can do a work in 18 days and B in 24 days. They start together, but A leaves after 6 days. In how many more days will B finish the remaining work?","options":["12 days","10 days","14 days","8 days"],"answer":1,"explanation":"In 6 days together they do 6(1/18 + 1/24) = 6 × 7/72 = 7/12. The remaining 5/12 takes B (5/12) × 24 = 10 days.","difficulty":"hard","source":"SSC CGL","questionHi":"A किसी कार्य को 18 दिन में और B 24 दिन में कर सकता है। वे साथ शुरू करते हैं, परंतु 6 दिन बाद A चला जाता है। शेष कार्य B कितने और दिन में पूरा करेगा?","optionsHi":["12 दिन","10 दिन","14 दिन","8 दिन"],"explanationHi":"साथ में 6 दिन में वे 6(1/18 + 1/24) = 6 × 7/72 = 7/12 कार्य करते हैं। शेष 5/12 कार्य B (5/12) × 24 = 10 दिन में करता है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-33","question":"1 man and 2 women can finish a work in 10 days, while 2 men and 1 woman can finish it in 8 days. In how many days can 1 man alone finish it?","options":["20 days","40 days","30 days","24 days"],"answer":0,"explanation":"10(m + 2w) = 8(2m + w) → 10m + 20w = 16m + 8w → m = 2w. Then 10(2w + 2w) = 1 → w = 1/40, m = 1/20, so 20 days. 40 days is a woman's time.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"1 पुरुष और 2 महिलाएँ किसी कार्य को 10 दिन में पूरा कर सकते हैं, जबकि 2 पुरुष और 1 महिला उसे 8 दिन में पूरा कर सकते हैं। 1 पुरुष अकेला उसे कितने दिन में पूरा कर सकता है?","optionsHi":["20 दिन","40 दिन","30 दिन","24 दिन"],"explanationHi":"10(m + 2w) = 8(2m + w) → 10m + 20w = 16m + 8w → m = 2w। फिर 10(2w + 2w) = 1 → w = 1/40, m = 1/20, इसलिए 20 दिन। 40 दिन एक महिला का समय है।","subtopic":"men-women-children"},
  {"id":"quant-time-work-34","question":"Pipes A and B fill a tank in 20 and 30 minutes, and pipe C empties it in 15 minutes. All three are opened on an empty tank at 10:00 am and C is closed at 10:10 am. When will the tank be full?","options":["10:22 am","10:16 am","10:30 am","10:20 am"],"answer":3,"explanation":"With all three, rate = 1/20 + 1/30 − 1/15 = (3 + 2 − 4)/60 = 1/60 per minute; in 10 min they fill 1/6. The remaining 5/6 at A + B's rate 1/12 per minute takes 10 min. Full at 10:20 am.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"पाइप A और B एक टंकी को 20 और 30 मिनट में भरते हैं और पाइप C उसे 15 मिनट में खाली करता है। तीनों को खाली टंकी पर सुबह 10:00 बजे खोला जाता है और C को सुबह 10:10 बजे बंद कर दिया जाता है। टंकी कब भरेगी?","optionsHi":["10:22 am","10:16 am","10:30 am","10:20 am"],"explanationHi":"तीनों के साथ दर = 1/20 + 1/30 − 1/15 = (3 + 2 − 4)/60 = 1/60 प्रति मिनट; 10 मिनट में वे 1/6 भरते हैं। शेष 5/6 भाग A + B की दर 1/12 प्रति मिनट से 10 मिनट में भरता है। टंकी 10:20 am पर भर जाएगी।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-35","question":"A does 1/4 of a work in 5 days and B does 1/3 of it in 10 days. C is twice as efficient as B. In how many days will A, B and C together finish the work?","options":["7½ days","5 days","6⅔ days","8 days"],"answer":2,"explanation":"A alone: 20 days; B alone: 30 days; C (twice B) 15 days. Together 1/20 + 1/30 + 1/15 = (3 + 2 + 4)/60 = 9/60, so 60/9 = 6⅔ days.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"A किसी कार्य का 1/4 भाग 5 दिन में और B उसका 1/3 भाग 10 दिन में करता है। C, B से दोगुना कुशल है। A, B और C मिलकर कार्य को कितने दिन में पूरा करेंगे?","optionsHi":["7½ दिन","5 दिन","6⅔ दिन","8 दिन"],"explanationHi":"A अकेला: 20 दिन; B अकेला: 30 दिन; C (B का दोगुना) 15 दिन। साथ में 1/20 + 1/30 + 1/15 = (3 + 2 + 4)/60 = 9/60, इसलिए 60/9 = 6⅔ दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-36","question":"A job needs 100 worker-days of work. 20 workers start it, and at the end of each day 2 workers leave. In how many days is the job completed?","options":["5 days","7⅓ days","7 days","8 days"],"answer":1,"explanation":"Work done each day: 20, 18, 16, 14, 12, 10, 8 → total 98 after 7 days. On day 8 only 6 workers remain and 2 worker-days are left, which takes 2/6 = 1/3 day. Total 7⅓ days. 5 days assumes no one leaves.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक कार्य में 100 कर्मचारी-दिन का श्रम लगता है। 20 कर्मचारी उसे शुरू करते हैं और प्रत्येक दिन के अंत में 2 कर्मचारी चले जाते हैं। कार्य कितने दिन में पूरा होता है?","optionsHi":["5 दिन","7⅓ दिन","7 दिन","8 दिन"],"explanationHi":"प्रत्येक दिन का कार्य: 20, 18, 16, 14, 12, 10, 8 → 7 दिन बाद कुल 98। दिन 8 में केवल 6 कर्मचारी बचते हैं और 2 कर्मचारी-दिन कार्य शेष है, जिसमें 2/6 = 1/3 दिन लगता है। कुल 7⅓ दिन। 5 दिन यह मानता है कि कोई नहीं जाता।","subtopic":"alternate-days"},
  {"id":"quant-time-work-37","question":"A is 20% more efficient than B, and B is 25% more efficient than C. Together the three finish a work in 12 days. In how many days can A and C together finish it?","options":["18 days","20 days","15 days","24 days"],"answer":0,"explanation":"Take C's efficiency = 4, then B = 5 and A = 6. Total work = (6 + 5 + 4) × 12 = 180 units. A + C = 10 units/day, so 18 days.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"A, B से 20% अधिक कुशल है और B, C से 25% अधिक कुशल है। तीनों मिलकर कार्य को 12 दिन में पूरा करते हैं। A और C मिलकर उसे कितने दिन में पूरा कर सकते हैं?","optionsHi":["18 दिन","20 दिन","15 दिन","24 दिन"],"explanationHi":"C की कार्यक्षमता = 4 लें, तो B = 5 और A = 6। कुल कार्य = (6 + 5 + 4) × 12 = 180 इकाई। A + C = 10 इकाई/दिन, इसलिए 18 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-38","question":"A pipe fills a tank in 5 hours. What part of the tank does it fill in 2 hours?","options":["1/5","5/2","2/5","3/5"],"answer":2,"explanation":"In 1 hour the pipe fills 1/5, so in 2 hours it fills 2/5. 5/2 inverts time and rate, and 3/5 is the part still empty.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"एक पाइप टंकी को 5 घंटे में भरता है। वह 2 घंटे में टंकी का कितना भाग भरता है?","optionsHi":["1/5","5/2","2/5","3/5"],"explanationHi":"1 घंटे में पाइप 1/5 भरता है, इसलिए 2 घंटे में 2/5 भरेगा। 5/2 में समय और दर उलट दिए गए हैं, और 3/5 वह भाग है जो अब भी खाली है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-39","question":"If 4 men can paint a house in 6 days, in how many days can 3 men paint it at the same rate?","options":["9 days","7 days","8 days","4.5 days"],"answer":2,"explanation":"Work = 4 × 6 = 24 man-days, so 3 men need 24/3 = 8 days. 4.5 days wrongly assumes fewer men work faster.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"यदि 4 आदमी किसी घर को 6 दिन में रंग सकते हैं, तो समान दर से 3 आदमी उसे कितने दिन में रंग सकते हैं?","optionsHi":["9 दिन","7 दिन","8 दिन","4.5 दिन"],"explanationHi":"कार्य = 4 × 6 = 24 आदमी-दिन, इसलिए 3 आदमियों को 24/3 = 8 दिन लगेंगे। 4.5 दिन गलत मान लेता है कि कम आदमी तेज़ काम करते हैं।","subtopic":"men-women-children"},
  {"id":"quant-time-work-40","question":"A can do a piece of work in 15 days. What percent of the work does he complete in 6 days?","options":["45%","40%","36%","60%"],"answer":1,"explanation":"Each day he does 1/15 of the work, so in 6 days he does 6/15 = 2/5 = 40%.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"A किसी कार्य को 15 दिन में कर सकता है। वह 6 दिन में कार्य का कितना प्रतिशत पूरा करता है?","optionsHi":["45%","40%","36%","60%"],"explanationHi":"वह प्रतिदिन कार्य का 1/15 भाग करता है, इसलिए 6 दिन में 6/15 = 2/5 = 40% करता है।","subtopic":"combined-work"},
  {"id":"quant-time-work-41","question":"A and B can do a work in 18 days, B and C in 24 days, and A, B and C together in 12 days. In how many days can B alone do it?","options":["60 days","36 days","48 days","72 days"],"answer":3,"explanation":"C = 1/12 − 1/18 = 1/36 and A = 1/12 − 1/24 = 1/24, so B = 1/18 − 1/24 = 1/72: B takes 72 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A और B किसी कार्य को 18 दिन में, B और C 24 दिन में तथा A, B और C तीनों मिलकर 12 दिन में कर सकते हैं। B अकेला उसे कितने दिन में कर सकता है?","optionsHi":["60 दिन","36 दिन","48 दिन","72 दिन"],"explanationHi":"C = 1/12 − 1/18 = 1/36 और A = 1/12 − 1/24 = 1/24, इसलिए B = 1/18 − 1/24 = 1/72: B को 72 दिन लगेंगे।","subtopic":"combined-work"},
  {"id":"quant-time-work-42","question":"A is 40% less efficient than B. If B can finish a work in 12 days, how long will A take?","options":["16 days","16.8 days","20 days","18 days"],"answer":2,"explanation":"A's efficiency = 0.6 of B's, so A takes 12/0.6 = 20 days. Adding 40% to 12 days (16.8) treats time as directly proportional to the efficiency gap.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A, B से 40% कम कुशल है। यदि B किसी कार्य को 12 दिन में पूरा कर सकता है, तो A कितना समय लेगा?","optionsHi":["16 दिन","16.8 दिन","20 दिन","18 दिन"],"explanationHi":"A की कार्यक्षमता B की 0.6 है, इसलिए A को 12/0.6 = 20 दिन लगेंगे। 12 दिन में 40% जोड़ना (16.8) समय को कार्यक्षमता के अंतर के समानुपाती मान लेना है।","subtopic":"efficiency"},
  {"id":"quant-time-work-43","question":"12 men working 8 hours a day complete one-third of a work in 10 days. How many men working 10 hours a day are needed to finish the rest of the work in 8 days?","options":["18","24","20","30"],"answer":1,"explanation":"M₁D₁H₁/W₁ = M₂D₂H₂/W₂: (12 × 10 × 8)/(1/3) = (M × 8 × 10)/(2/3), so 2,880 = 120M and M = 24. Forgetting that 2/3 of the work remains gives 12.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"प्रतिदिन 8 घंटे काम करने वाले 12 आदमी किसी कार्य का एक-तिहाई भाग 10 दिन में पूरा करते हैं। शेष कार्य को 8 दिन में पूरा करने के लिए प्रतिदिन 10 घंटे काम करने वाले कितने आदमी चाहिए?","optionsHi":["18","24","20","30"],"explanationHi":"M₁D₁H₁/W₁ = M₂D₂H₂/W₂: (12 × 10 × 8)/(1/3) = (M × 8 × 10)/(2/3), इसलिए 2,880 = 120M और M = 24। यह भूल जाने पर कि 2/3 कार्य शेष है, 12 आता है।","subtopic":"men-women-children"},
  {"id":"quant-time-work-44","question":"Pipes A and B fill a tank in 6 hours and 8 hours. When pipe C is also opened, the empty tank fills in 6 hours. In how many hours can C alone empty the full tank?","options":["6 hours","12 hours","24 hours","8 hours"],"answer":3,"explanation":"1/6 + 1/8 − 1/c = 1/6, so 1/c = 1/8 and C empties the tank in 8 hours: it exactly cancels pipe B.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"पाइप A और B एक टंकी को 6 घंटे और 8 घंटे में भरते हैं। जब पाइप C भी खोला जाता है, तो खाली टंकी 6 घंटे में भरती है। C अकेला भरी टंकी को कितने घंटे में खाली कर सकता है?","optionsHi":["6 घंटे","12 घंटे","24 घंटे","8 घंटे"],"explanationHi":"1/6 + 1/8 − 1/c = 1/6, इसलिए 1/c = 1/8 और C टंकी को 8 घंटे में खाली करता है: यह ठीक पाइप B को निरस्त कर देता है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-45","question":"A and B together can do a work in 10 days. They work together for 4 days, after which A leaves and B finishes the rest in 9 days. In how many days can A alone do the work?","options":["15 days","20 days","30 days","25 days"],"answer":2,"explanation":"In 4 days they do 4/10 = 2/5, so B does 3/5 in 9 days and alone takes 15 days. A = 1/10 − 1/15 = 1/30, i.e. 30 days. 15 days is B's time.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A और B मिलकर किसी कार्य को 10 दिन में कर सकते हैं। वे 4 दिन साथ काम करते हैं, उसके बाद A चला जाता है और B शेष कार्य 9 दिन में पूरा करता है। A अकेला कार्य कितने दिन में कर सकता है?","optionsHi":["15 दिन","20 दिन","30 दिन","25 दिन"],"explanationHi":"4 दिन में वे 4/10 = 2/5 कार्य करते हैं, इसलिए B 9 दिन में 3/5 कार्य करता है और अकेले उसे 15 दिन लगेंगे। A = 1/10 − 1/15 = 1/30, यानी 30 दिन। 15 दिन B का समय है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-46","question":"2 men can do as much work as 3 women or 4 children. If 6 men can do a work in 12 days, how long will 6 women and 8 children take to do it?","options":["8 days","10 days","12 days","9 days"],"answer":3,"explanation":"1 woman = 2/3 man and 1 child = 1/2 man, so 6 women + 8 children = 4 + 4 = 8 men. Time = 72 man-days ÷ 8 = 9 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"2 पुरुष उतना कार्य कर सकते हैं जितना 3 महिलाएँ या 4 बच्चे। यदि 6 पुरुष किसी कार्य को 12 दिन में कर सकते हैं, तो 6 महिलाएँ और 8 बच्चे उसे कितने दिन में करेंगे?","optionsHi":["8 दिन","10 दिन","12 दिन","9 दिन"],"explanationHi":"1 महिला = 2/3 पुरुष और 1 बच्चा = 1/2 पुरुष, इसलिए 6 महिलाएँ + 8 बच्चे = 4 + 4 = 8 पुरुष। समय = 72 आदमी-दिन ÷ 8 = 9 दिन।","subtopic":"men-women-children"},
  {"id":"quant-time-work-47","question":"A completes 60% of a work in 15 days and then asks B to join him. Together they finish the rest in 4 days. In how many days can B alone do the whole work?","options":["25 days","20 days","16 2/3 days","15 days"],"answer":2,"explanation":"A does 4% a day. The remaining 40% in 4 days means 10% a day together, so B does 6% a day and needs 100/6 = 16 2/3 days.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A किसी कार्य का 60% भाग 15 दिन में पूरा करता है और फिर B को अपने साथ जोड़ लेता है। साथ में वे शेष कार्य 4 दिन में पूरा करते हैं। B अकेला पूरा कार्य कितने दिन में कर सकता है?","optionsHi":["25 दिन","20 दिन","16 2/3 दिन","15 दिन"],"explanationHi":"A प्रतिदिन 4% करता है। शेष 40% कार्य 4 दिन में होने का अर्थ है साथ में 10% प्रतिदिन, इसलिए B प्रतिदिन 6% करता है और उसे 100/6 = 16 2/3 दिन चाहिए।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-48","question":"A job is started with 1 worker on day 1; on each later day one more worker joins (2 on day 2, 3 on day 3, and so on). One worker alone would take 55 days. In how many days is the job finished?","options":["10 days","9 days","11 days","28 days"],"answer":0,"explanation":"Worker-days after n days = 1 + 2 + … + n = n(n + 1)/2 = 55, so n = 10.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक कार्य पहले दिन 1 कर्मचारी से शुरू होता है; बाद के प्रत्येक दिन एक और कर्मचारी जुड़ता जाता है (दिन 2 में 2, दिन 3 में 3, और इसी प्रकार)। एक कर्मचारी अकेला उसे 55 दिन में करता। कार्य कितने दिन में पूरा होता है?","optionsHi":["10 दिन","9 दिन","11 दिन","28 दिन"],"explanationHi":"n दिन बाद कर्मचारी-दिन = 1 + 2 + … + n = n(n + 1)/2 = 55, इसलिए n = 10।","subtopic":"alternate-days"},
  {"id":"quant-time-work-49","question":"A and B undertake a work for ₹7,200. A alone could do it in 12 days and B alone in 18 days. They work together for 4 days, then A leaves and B finishes the work. What is A's share of the money?","options":["₹2,400","₹2,880","₹4,320","₹3,600"],"answer":0,"explanation":"A worked 4 days and did 4/12 = 1/3 of the work, so he gets 1/3 × 7,200 = ₹2,400. Splitting in the efficiency ratio 3 : 2 (₹4,320) ignores that B worked longer.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A और B ₹7,200 में एक कार्य का ठेका लेते हैं। A अकेला उसे 12 दिन में और B अकेला 18 दिन में कर सकता है। वे 4 दिन साथ काम करते हैं, फिर A चला जाता है और B कार्य पूरा करता है। A का धन में हिस्सा कितना है?","optionsHi":["₹2,400","₹2,880","₹4,320","₹3,600"],"explanationHi":"A ने 4 दिन काम किया और 4/12 = 1/3 कार्य किया, इसलिए उसे 1/3 × 7,200 = ₹2,400 मिलेंगे। कार्यक्षमता के अनुपात 3 : 2 में बाँटना (₹4,320) इस बात को अनदेखा करता है कि B ने अधिक समय काम किया।","subtopic":"work-wages"},
  {"id":"quant-time-work-50","question":"Pipes A and B fill a tank in 30 minutes and 45 minutes. Both are opened together. After how many minutes should B be closed so that the tank is full in exactly 24 minutes?","options":["15 minutes","9 minutes","12 minutes","6 minutes"],"answer":1,"explanation":"A runs all 24 minutes and fills 24/30 = 4/5. B must fill 1/5, which takes 45/5 = 9 minutes.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"पाइप A और B एक टंकी को 30 मिनट और 45 मिनट में भरते हैं। दोनों को साथ खोला जाता है। कितने मिनट बाद B को बंद कर देना चाहिए ताकि टंकी ठीक 24 मिनट में भर जाए?","optionsHi":["15 मिनट","9 मिनट","12 मिनट","6 मिनट"],"explanationHi":"A पूरे 24 मिनट चलता है और 24/30 = 4/5 भरता है। B को 1/5 भरना है, जिसमें 45/5 = 9 मिनट लगते हैं।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-51","question":"A can finish a work in 20 working days. He works every day except Sunday and starts on a Monday. On which calendar day from the start does he finish?","options":["22nd day","20th day","24th day","23rd day"],"answer":3,"explanation":"Each week gives 6 working days: after 3 weeks (21 calendar days) he has done 18 days' work. Day 22 (Monday) and day 23 (Tuesday) complete the 20 days.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"A किसी कार्य को 20 कार्य-दिवसों में पूरा कर सकता है। वह रविवार को छोड़कर प्रतिदिन काम करता है और सोमवार से शुरू करता है। शुरुआत से गिनने पर वह किस कैलेंडर दिन को कार्य पूरा करेगा?","optionsHi":["22वाँ दिन","20वाँ दिन","24वाँ दिन","23वाँ दिन"],"explanationHi":"प्रत्येक सप्ताह में 6 कार्य-दिवस होते हैं: 3 सप्ताह (21 कैलेंडर दिन) बाद उसने 18 दिन का कार्य किया होता है। दिन 22 (सोमवार) और दिन 23 (मंगलवार) से 20 दिन पूरे हो जाते हैं।","subtopic":"alternate-days"},
  {"id":"quant-time-work-52","question":"A takes 6 days more than B to do a work, and together they finish it in 4 days. How long does A alone take?","options":["12 days","8 days","10 days","6 days"],"answer":0,"explanation":"If B takes x days: 1/x + 1/(x + 6) = 1/4 gives x² − 2x − 24 = 0, so x = 6 and A takes 12 days. Check: 1/6 + 1/12 = 1/4.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A किसी कार्य को करने में B से 6 दिन अधिक लेता है, और दोनों मिलकर उसे 4 दिन में पूरा करते हैं। A अकेला कितना समय लेगा?","optionsHi":["12 दिन","8 दिन","10 दिन","6 दिन"],"explanationHi":"यदि B को x दिन लगें: 1/x + 1/(x + 6) = 1/4 से x² − 2x − 24 = 0, इसलिए x = 6 और A को 12 दिन लगेंगे। जाँच: 1/6 + 1/12 = 1/4।","subtopic":"combined-work"},
  {"id":"quant-time-work-53","question":"A can do a work in 30 days, B in 20 days and C in 12 days. A starts alone; after 5 days B joins him, and after another 3 days C joins them. In how many days in all is the work finished?","options":["12 days","11.5 days","10.5 days","11 days"],"answer":1,"explanation":"A's 5 days: 1/6. Next 3 days (A + B = 1/12 a day): 1/4. Done = 5/12. The rest, 7/12, at A + B + C = 1/6 a day takes 3.5 days. Total = 5 + 3 + 3.5 = 11.5 days.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A किसी कार्य को 30 दिन में, B 20 दिन में और C 12 दिन में कर सकता है। A अकेला शुरू करता है; 5 दिन बाद B उसके साथ जुड़ता है, और 3 दिन बाद C भी जुड़ जाता है। कार्य कुल कितने दिन में पूरा होता है?","optionsHi":["12 दिन","11.5 दिन","10.5 दिन","11 दिन"],"explanationHi":"A के 5 दिन: 1/6। अगले 3 दिन (A + B = 1/12 प्रतिदिन): 1/4। कुल हुआ = 5/12। शेष 7/12 भाग A + B + C = 1/6 प्रतिदिन की दर से 3.5 दिन में होता है। कुल = 5 + 3 + 3.5 = 11.5 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-54","question":"A certain number of men can finish a work in some days. With 4 fewer men it takes 6 days more, and with 6 more men it takes 6 days less. How many men are there?","options":["20","18","24","30"],"answer":2,"explanation":"md = (m − 4)(d + 6) gives 6m − 4d = 24, and md = (m + 6)(d − 6) gives d = m + 6. So 6m − 4m − 24 = 24 and m = 24 (d = 30). Check: 24 × 30 = 20 × 36 = 30 × 24 = 720.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"कुछ आदमी किसी कार्य को कुछ दिनों में पूरा कर सकते हैं। 4 आदमी कम होने पर उसमें 6 दिन अधिक लगते हैं, और 6 आदमी अधिक होने पर 6 दिन कम लगते हैं। आदमियों की संख्या कितनी है?","optionsHi":["20","18","24","30"],"explanationHi":"md = (m − 4)(d + 6) से 6m − 4d = 24, और md = (m + 6)(d − 6) से d = m + 6। इसलिए 6m − 4m − 24 = 24 और m = 24 (d = 30)। जाँच: 24 × 30 = 20 × 36 = 30 × 24 = 720।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-55","question":"A pipe fills 40% of a tank in 6 hours, and a drain empties 25% of it in 5 hours. If both are opened when the tank is half full, how long will it take to fill the tank?","options":["60 hours","20 hours","15 hours","30 hours"],"answer":3,"explanation":"Fill rate = 0.4/6 = 1/15 per hour; drain rate = 0.25/5 = 1/20. Net = 1/60 per hour, so the remaining half takes 30 hours. 60 hours is for an empty tank.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक पाइप 6 घंटे में टंकी का 40% भरता है, और एक निकास पाइप 5 घंटे में उसका 25% खाली करता है। यदि टंकी आधी भरी हो और दोनों खोल दिए जाएँ, तो टंकी भरने में कितना समय लगेगा?","optionsHi":["60 घंटे","20 घंटे","15 घंटे","30 घंटे"],"explanationHi":"भरने की दर = 0.4/6 = 1/15 प्रति घंटा; खाली करने की दर = 0.25/5 = 1/20। शुद्ध दर = 1/60 प्रति घंटा, इसलिए शेष आधा भाग 30 घंटे में भरेगा। 60 घंटे खाली टंकी के लिए है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-56","question":"How many of the following statements are correct?\n1. If A does a job in x days and B in y days, together they take xy/(x + y) days.\n2. If 10 men take 12 days for a job, 15 men take 8 days.\n3. If a pipe fills a tank in 4 hours and another empties it in 6 hours, together they fill the empty tank in 10 hours.\n4. If A is 50% more efficient than B, A takes 50% less time than B.","options":["Only one","Only three","Only two","All four"],"answer":2,"explanation":"1 and 2 are true (120 man-days ÷ 15 = 8). 3 is false: 1/4 − 1/6 = 1/12, so 12 hours. 4 is false: time ∝ 1/efficiency, so A takes 1/1.5 = 2/3 of B's time, i.e. 33 1/3% less, not 50%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. यदि A किसी कार्य को x दिन में और B y दिन में करता है, तो साथ में वे xy/(x + y) दिन लेते हैं।\n2. यदि 10 आदमी किसी कार्य में 12 दिन लेते हैं, तो 15 आदमी 8 दिन लेंगे।\n3. यदि एक पाइप टंकी को 4 घंटे में भरता है और दूसरा उसे 6 घंटे में खाली करता है, तो साथ में वे खाली टंकी को 10 घंटे में भरते हैं।\n4. यदि A, B से 50% अधिक कुशल है, तो A, B से 50% कम समय लेता है।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"1 और 2 सही हैं (120 आदमी-दिन ÷ 15 = 8)। 3 गलत है: 1/4 − 1/6 = 1/12, इसलिए 12 घंटे। 4 गलत है: समय ∝ 1/कार्यक्षमता, इसलिए A, B का 1/1.5 = 2/3 समय लेता है, यानी 33 1/3% कम, 50% नहीं।","subtopic":"combined-work"},
  {"id":"quant-time-work-57","question":"A can do a work in 30 days. He works alone for 10 days, after which B joins him and they finish the rest in 16 days. If instead B had worked alone for the first 10 days and A had then joined him, how many days in all would the work have taken?","options":["32 days","26 days","28 days","30 days"],"answer":0,"explanation":"A's 10 days = 1/3, so A + B do 2/3 in 16 days: A + B = 1/24 and B = 1/24 − 1/30 = 1/120. B's 10 days = 1/12; the remaining 11/12 at 1/24 a day takes 22 days. Total = 32 days.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A किसी कार्य को 30 दिन में कर सकता है। वह 10 दिन अकेला काम करता है, उसके बाद B उसके साथ जुड़ता है और वे शेष कार्य 16 दिन में पूरा करते हैं। यदि इसके बजाय B ने पहले 10 दिन अकेले काम किया होता और फिर A उसके साथ जुड़ता, तो कार्य में कुल कितने दिन लगते?","optionsHi":["32 दिन","26 दिन","28 दिन","30 दिन"],"explanationHi":"A के 10 दिन = 1/3, इसलिए A + B 16 दिन में 2/3 करते हैं: A + B = 1/24 और B = 1/24 − 1/30 = 1/120। B के 10 दिन = 1/12; शेष 11/12 भाग 1/24 प्रतिदिन की दर से 22 दिन में होता है। कुल = 32 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-58","question":"A, B and C can do a work in 10, 15 and 30 days respectively. A works every day, while B and C assist him on alternate days, B on the first day. In how many days is the work finished?","options":["7 days","6 days","6 1/2 days","6 3/5 days"],"answer":3,"explanation":"Day 1 (A + B) = 1/6; day 2 (A + C) = 2/15; two days = 3/10. After 6 days, 9/10 is done. On day 7, A + B do 1/6 a day, so the last 1/10 takes 3/5 of a day: 6 3/5 days.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A, B और C किसी कार्य को क्रमशः 10, 15 और 30 दिन में कर सकते हैं। A प्रतिदिन काम करता है, जबकि B और C एकांतर दिनों में उसकी सहायता करते हैं, पहले दिन B। कार्य कितने दिन में पूरा होता है?","optionsHi":["7 दिन","6 दिन","6 1/2 दिन","6 3/5 दिन"],"explanationHi":"दिन 1 (A + B) = 1/6; दिन 2 (A + C) = 2/15; दो दिन = 3/10। 6 दिन बाद 9/10 हो चुका होता है। दिन 7 में A + B प्रतिदिन 1/6 करते हैं, इसलिए अंतिम 1/10 में एक दिन का 3/5 भाग लगता है: 6 3/5 दिन।","subtopic":"alternate-days"},
  {"id":"quant-time-work-59","question":"3 men or 5 women can finish a work in 30 days. A man is paid ₹500 a day and a woman ₹280 a day. Is it cheaper to get the job done by men only or by women only, and by how much?","options":["Women only, by ₹3,000","Women only, by ₹6,000","Both cost the same","Men only, by ₹3,000"],"answer":0,"explanation":"Men: 90 man-days × ₹500 = ₹45,000. Women: 150 woman-days × ₹280 = ₹42,000. Women are cheaper by ₹3,000 whatever the number hired, since the total wage depends only on person-days.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"3 पुरुष या 5 महिलाएँ किसी कार्य को 30 दिन में पूरा कर सकते हैं। एक पुरुष को ₹500 प्रतिदिन और एक महिला को ₹280 प्रतिदिन मिलते हैं। कार्य केवल पुरुषों से कराना सस्ता है या केवल महिलाओं से, और कितना?","optionsHi":["केवल महिलाओं से, ₹3,000 सस्ता","केवल महिलाओं से, ₹6,000 सस्ता","दोनों का खर्च समान है","केवल पुरुषों से, ₹3,000 सस्ता"],"explanationHi":"पुरुष: 90 आदमी-दिन × ₹500 = ₹45,000। महिलाएँ: 150 महिला-दिन × ₹280 = ₹42,000। कितने भी लोग लगाएँ, महिलाएँ ₹3,000 सस्ती रहती हैं, क्योंकि कुल मजदूरी केवल व्यक्ति-दिनों पर निर्भर करती है।","subtopic":"work-wages"},
  {"id":"quant-time-work-60","question":"A can do a work in 8 days working 9 hours a day, and B can do it in 12 days working 6 hours a day. If they work together 8 hours a day, in how many days will they finish it?","options":["4 days","4.5 days","5 days","4.8 days"],"answer":1,"explanation":"A needs 72 hours and B needs 72 hours, so together they need 36 hours, i.e. 36/8 = 4.5 days. Combining day-rates (1/8 + 1/12 → 4.8 days) ignores the different working hours.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A प्रतिदिन 9 घंटे काम करके किसी कार्य को 8 दिन में कर सकता है, और B प्रतिदिन 6 घंटे काम करके उसे 12 दिन में कर सकता है। यदि वे साथ में प्रतिदिन 8 घंटे काम करें, तो कार्य कितने दिन में पूरा होगा?","optionsHi":["4 दिन","4.5 दिन","5 दिन","4.8 दिन"],"explanationHi":"A को 72 घंटे और B को 72 घंटे चाहिए, इसलिए साथ में 36 घंटे चाहिए, यानी 36/8 = 4.5 दिन। दिन की दरें जोड़ना (1/8 + 1/12 → 4.8 दिन) काम के अलग-अलग घंटों को अनदेखा करता है।","subtopic":"men-women-children"},
  {"id":"quant-time-work-61","question":"Pipe A fills a tank in 6 hours, pipe B in 8 hours, and pipe C empties it in 12 hours. They are opened one at a time for an hour each in the order A, B, C, A, B, C, … starting with an empty tank. When is the tank full?","options":["After 14 hours","After 13 hours","After 12 hours","After 13.5 hours"],"answer":1,"explanation":"Each 3-hour cycle adds 1/6 + 1/8 − 1/12 = 5/24. After 4 cycles (12 hours) the tank is 20/24 full (it never fills mid-cycle, since the most it reaches is 22/24). In the 13th hour A adds 4/24 and fills it exactly.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"पाइप A एक टंकी को 6 घंटे में, पाइप B 8 घंटे में भरता है, और पाइप C उसे 12 घंटे में खाली करता है। खाली टंकी से शुरू करके उन्हें एक-एक घंटे के लिए क्रम A, B, C, A, B, C, … में एक बार में एक खोला जाता है। टंकी कब भरेगी?","optionsHi":["14 घंटे बाद","13 घंटे बाद","12 घंटे बाद","13.5 घंटे बाद"],"explanationHi":"प्रत्येक 3 घंटे के चक्र में 1/6 + 1/8 − 1/12 = 5/24 भरता है। 4 चक्र (12 घंटे) बाद टंकी 20/24 भरी होती है (चक्र के बीच में टंकी नहीं भरती, क्योंकि अधिकतम 22/24 तक पहुँचती है)। 13वें घंटे में A 4/24 जोड़कर उसे ठीक भर देता है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-62","question":"Assertion (A): If 6 men can do a job in 10 days, 10 men can do it in 6 days.\nReason (R): For a fixed amount of work, the number of men and the number of days are inversely proportional.","options":["Both A and R are true, and R is the correct explanation of A","A is false but R is true","Both A and R are true, but R is not the correct explanation of A","A is true but R is false"],"answer":0,"explanation":"The job needs 60 man-days, so 10 men take 6 days (A); this follows from the inverse proportion in R.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): यदि 6 आदमी किसी कार्य को 10 दिन में कर सकते हैं, तो 10 आदमी उसे 6 दिन में कर सकते हैं।\nकारण (R): किसी निश्चित कार्य के लिए आदमियों की संख्या और दिनों की संख्या व्युत्क्रमानुपाती होती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A असत्य है लेकिन R सत्य है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है लेकिन R असत्य है"],"explanationHi":"कार्य में 60 आदमी-दिन लगते हैं, इसलिए 10 आदमी 6 दिन लेंगे (A); यह R में दिए व्युत्क्रम अनुपात से ही निकलता है।","subtopic":"men-women-children"},
  {"id":"quant-time-work-63","question":"A pipe fills a tank in 3 hours, but because of a leak at the bottom it takes 30 minutes longer. If the tank is full and the pipe is closed, how long will the leak take to empty half the tank?","options":["21 hours","3.5 hours","10.5 hours","7 hours"],"answer":2,"explanation":"Leak rate = 1/3 − 1/3.5 = 1/3 − 2/7 = 1/21 per hour, so it empties the full tank in 21 hours and half of it in 10.5 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक पाइप टंकी को 3 घंटे में भरता है, परंतु तली में रिसाव के कारण उसे 30 मिनट अधिक लगते हैं। यदि टंकी भरी हो और पाइप बंद हो, तो रिसाव टंकी को आधा खाली करने में कितना समय लेगा?","optionsHi":["21 घंटे","3.5 घंटे","10.5 घंटे","7 घंटे"],"explanationHi":"रिसाव की दर = 1/3 − 1/3.5 = 1/3 − 2/7 = 1/21 प्रति घंटा, इसलिए वह पूरी टंकी 21 घंटे में और आधी 10.5 घंटे में खाली करेगा।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-64","question":"A and B together can do a work in 30 days. They work together for 20 days, then B leaves and A finishes the rest in 15 days. If A had left instead of B after the 20 days, how long would B have taken to finish the rest?","options":["30 days","20 days","45 days","15 days"],"answer":0,"explanation":"In 20 days they do 2/3, so A does 1/3 in 15 days: A = 1/45. B = 1/30 − 1/45 = 1/90, so B needs 1/3 × 90 = 30 days for the rest.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A और B मिलकर किसी कार्य को 30 दिन में कर सकते हैं। वे 20 दिन साथ काम करते हैं, फिर B चला जाता है और A शेष कार्य 15 दिन में पूरा करता है। यदि 20 दिन बाद B के बजाय A चला गया होता, तो B को शेष कार्य पूरा करने में कितना समय लगता?","optionsHi":["30 दिन","20 दिन","45 दिन","15 दिन"],"explanationHi":"20 दिन में वे 2/3 कार्य करते हैं, इसलिए A 15 दिन में 1/3 करता है: A = 1/45। B = 1/30 − 1/45 = 1/90, इसलिए B को शेष के लिए 1/3 × 90 = 30 दिन चाहिए।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-65","question":"A, B and C can do a work in 8, 12 and 16 days respectively. They work one at a time on successive days in the order A, B, C, A, B, C, … In how many days is the work finished?","options":["10 3/4 days","11 1/4 days","10 1/2 days","11 days"],"answer":0,"explanation":"One 3-day cycle does 1/8 + 1/12 + 1/16 = 13/48. After 9 days: 39/48. Day 10 (A): 45/48. On day 11, B (4/48 a day) needs 3/48, i.e. 3/4 of a day: 10 3/4 days.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A, B और C किसी कार्य को क्रमशः 8, 12 और 16 दिन में कर सकते हैं। वे क्रमागत दिनों में एक-एक करके क्रम A, B, C, A, B, C, … में काम करते हैं। कार्य कितने दिन में पूरा होता है?","optionsHi":["10 3/4 दिन","11 1/4 दिन","10 1/2 दिन","11 दिन"],"explanationHi":"एक 3 दिन के चक्र में 1/8 + 1/12 + 1/16 = 13/48 कार्य होता है। 9 दिन बाद: 39/48। दिन 10 (A): 45/48। दिन 11 में B (4/48 प्रतिदिन) को 3/48 करना है, यानी एक दिन का 3/4 भाग: 10 3/4 दिन।","subtopic":"alternate-days"},
  {"id":"quant-time-work-66","question":"A, B and C are paid ₹6,800 in all for a job. A worked 6 days, B 8 days and C 10 days, and their daily rates of work are in the ratio 4 : 3 : 2. If pay is in proportion to the work done, what is C's share?","options":["₹1,600","₹2,000","₹2,267","₹2,833"],"answer":1,"explanation":"Work done ∝ 6 × 4 : 8 × 3 : 10 × 2 = 24 : 24 : 20, so C gets 20/68 × 6,800 = ₹2,000. Sharing by days alone (10/24) gives ₹2,833.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी कार्य के लिए A, B और C को कुल ₹6,800 दिए जाते हैं। A ने 6 दिन, B ने 8 दिन और C ने 10 दिन काम किया, और उनकी दैनिक कार्य-दरों का अनुपात 4 : 3 : 2 है। यदि भुगतान किए गए कार्य के अनुपात में हो, तो C का हिस्सा कितना है?","optionsHi":["₹1,600","₹2,000","₹2,267","₹2,833"],"explanationHi":"किया गया कार्य ∝ 6 × 4 : 8 × 3 : 10 × 2 = 24 : 24 : 20, इसलिए C को 20/68 × 6,800 = ₹2,000 मिलेंगे। केवल दिनों के आधार पर बाँटने (10/24) से ₹2,833 आता है।","subtopic":"work-wages"},
  {"id":"quant-time-work-67","question":"Pipes A and B can fill a tank in 20 hours and 30 hours. A is opened at 6:00 am and B at 8:00 am. At what time is the tank full?","options":["6:00 pm","7:00 pm","6:30 pm","6:48 pm"],"answer":3,"explanation":"By 8 am A fills 2/20 = 1/10. Together they fill 1/20 + 1/30 = 1/12 per hour, so 9/10 takes 10.8 hours = 10 h 48 min after 8 am, i.e. 6:48 pm.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"पाइप A और B एक टंकी को 20 घंटे और 30 घंटे में भर सकते हैं। A को सुबह 6:00 बजे और B को सुबह 8:00 बजे खोला जाता है। टंकी किस समय भर जाएगी?","optionsHi":["6:00 pm","7:00 pm","6:30 pm","6:48 pm"],"explanationHi":"सुबह 8 बजे तक A 2/20 = 1/10 भरता है। साथ में वे 1/20 + 1/30 = 1/12 प्रति घंटा भरते हैं, इसलिए 9/10 भरने में 10.8 घंटे = 10 घंटे 48 मिनट लगते हैं, यानी सुबह 8 बजे के बाद, अर्थात 6:48 pm।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-68","question":"A can finish a job in 24 days and B in 40 days. How long will they take working together?","options":["15 days","32 days","16 days","12 days"],"answer":0,"explanation":"Take the work as LCM 120 units: A does 5 a day and B 3, so 8 a day together. 120 ÷ 8 = 15 days.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"A किसी कार्य को 24 दिन में और B 40 दिन में पूरा कर सकता है। साथ काम करने पर उन्हें कितना समय लगेगा?","optionsHi":["15 दिन","32 दिन","16 दिन","12 दिन"],"explanationHi":"कार्य को LCM 120 इकाई मानें: A प्रतिदिन 5 और B 3 करता है, यानी साथ में प्रतिदिन 8। 120 ÷ 8 = 15 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-69","question":"8 identical taps fill a tank in 27 minutes. How long will 6 such taps take?","options":["20.25 minutes","32 minutes","30 minutes","36 minutes"],"answer":3,"explanation":"Tap-minutes are fixed: 8 × 27 = 216. With 6 taps, 216 ÷ 6 = 36 minutes.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"8 एक जैसे नल एक टंकी को 27 मिनट में भरते हैं। ऐसे 6 नल कितना समय लेंगे?","optionsHi":["20.25 मिनट","32 मिनट","30 मिनट","36 मिनट"],"explanationHi":"नल-मिनट स्थिर रहते हैं: 8 × 27 = 216। 6 नलों के साथ, 216 ÷ 6 = 36 मिनट।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-70","question":"A does 1/12 of a job in a day and B does 1/18. What fraction of the job do they finish together in 3 days?","options":["1/2","5/36","5/12","7/12"],"answer":2,"explanation":"Together per day: 1/12 + 1/18 = 5/36. In 3 days: 15/36 = 5/12.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"A एक दिन में कार्य का 1/12 भाग और B 1/18 भाग करता है। वे साथ मिलकर 3 दिन में कार्य का कितना भाग पूरा करते हैं?","optionsHi":["1/2","5/36","5/12","7/12"],"explanationHi":"साथ में प्रतिदिन: 1/12 + 1/18 = 5/36। 3 दिन में: 15/36 = 5/12।","subtopic":"combined-work"},
  {"id":"quant-time-work-71","question":"36 workers can finish a job in 15 days. How many workers are needed to finish it in 12 days?","options":["29","45","40","48"],"answer":1,"explanation":"Worker-days = 36 × 15 = 540. In 12 days: 540 ÷ 12 = 45 workers.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"36 कर्मचारी किसी कार्य को 15 दिन में पूरा कर सकते हैं। उसे 12 दिन में पूरा करने के लिए कितने कर्मचारी चाहिए?","optionsHi":["29","45","40","48"],"explanationHi":"कर्मचारी-दिन = 36 × 15 = 540। 12 दिन में: 540 ÷ 12 = 45 कर्मचारी।","subtopic":"men-women-children"},
  {"id":"quant-time-work-72","question":"One machine prints 1,200 pages in 8 minutes and another prints 1,200 pages in 12 minutes. How long will both take together to print 1,200 pages?","options":["10 minutes","4.8 minutes","5 minutes","4 minutes"],"answer":1,"explanation":"Together: 1,200/8 + 1,200/12 = 150 + 100 = 250 pages a minute. 1,200 ÷ 250 = 4.8 minutes.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"एक मशीन 8 मिनट में 1,200 पृष्ठ छापती है और दूसरी 12 मिनट में 1,200 पृष्ठ छापती है। दोनों साथ मिलकर 1,200 पृष्ठ छापने में कितना समय लेंगी?","optionsHi":["10 मिनट","4.8 मिनट","5 मिनट","4 मिनट"],"explanationHi":"साथ में: 1,200/8 + 1,200/12 = 150 + 100 = 250 पृष्ठ प्रति मिनट। 1,200 ÷ 250 = 4.8 मिनट।","subtopic":"combined-work"},
  {"id":"quant-time-work-73","question":"The efficiencies of A and B are in the ratio 3 : 2. If B takes 30 days to finish a job, how long will A take?","options":["20 days","45 days","25 days","18 days"],"answer":0,"explanation":"Time is inversely proportional to efficiency: A's time = 30 × 2/3 = 20 days.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"A और B की कार्यक्षमताओं का अनुपात 3 : 2 है। यदि B किसी कार्य को 30 दिन में पूरा करता है, तो A कितना समय लेगा?","optionsHi":["20 दिन","45 दिन","25 दिन","18 दिन"],"explanationHi":"समय कार्यक्षमता के व्युत्क्रमानुपाती होता है: A का समय = 30 × 2/3 = 20 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-74","question":"A completes 25% of a job in 5 days and B completes 20% of it in 6 days. How long will they take to finish the job together?","options":["11 days","25 days","15 days","12 days"],"answer":3,"explanation":"A alone = 20 days, B alone = 30 days. Together: 20 × 30/50 = 12 days.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"A किसी कार्य का 25% भाग 5 दिन में और B उसका 20% भाग 6 दिन में पूरा करता है। साथ मिलकर वे कार्य को कितने समय में पूरा करेंगे?","optionsHi":["11 दिन","25 दिन","15 दिन","12 दिन"],"explanationHi":"A अकेला = 20 दिन, B अकेला = 30 दिन। साथ में: 20 × 30/50 = 12 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-75","question":"A, B and C can do a job alone in 12, 16 and 24 days. How long will they take working together?","options":["6 days","52/3 days","16/3 days","5 days"],"answer":2,"explanation":"Work = 48 units: A 4, B 3, C 2 per day, total 9. Time = 48/9 = 16/3 days (5⅓ days).","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"A, B और C किसी कार्य को अकेले क्रमशः 12, 16 और 24 दिन में कर सकते हैं। साथ काम करने पर वे कितना समय लेंगे?","optionsHi":["6 दिन","52/3 दिन","16/3 दिन","5 दिन"],"explanationHi":"कार्य = 48 इकाई: A प्रतिदिन 4, B 3, C 2, कुल 9। समय = 48/9 = 16/3 दिन (5⅓ दिन)।","subtopic":"combined-work"},
  {"id":"quant-time-work-76","question":"A and B together can do a job in 8 days, and A alone in 12 days. B works alone for 3 days and then A finishes the rest. How many days does the job take in all?","options":["12 days","10.5 days","13.5 days","15 days"],"answer":2,"explanation":"B alone = 24 days. In 3 days B does 1/8; A needs 7/8 × 12 = 10.5 days. Total = 13.5 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A और B मिलकर किसी कार्य को 8 दिन में कर सकते हैं, और A अकेला 12 दिन में। B अकेला 3 दिन काम करता है और फिर A शेष कार्य पूरा करता है। कार्य में कुल कितने दिन लगते हैं?","optionsHi":["12 दिन","10.5 दिन","13.5 दिन","15 दिन"],"explanationHi":"B अकेला = 24 दिन। 3 दिन में B 1/8 कार्य करता है; A को 7/8 × 12 = 10.5 दिन चाहिए। कुल = 13.5 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-77","question":"4 men or 6 women can do a job in 15 days. How long will 2 men and 3 women take?","options":["7.5 days","15 days","30 days","12 days"],"answer":1,"explanation":"4 men = 6 women, so 2 men = 3 women. Then 2 men + 3 women = 6 women, who take 15 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"4 पुरुष या 6 महिलाएँ किसी कार्य को 15 दिन में कर सकते हैं। 2 पुरुष और 3 महिलाएँ कितना समय लेंगे?","optionsHi":["7.5 दिन","15 दिन","30 दिन","12 दिन"],"explanationHi":"4 पुरुष = 6 महिलाएँ, इसलिए 2 पुरुष = 3 महिलाएँ। तब 2 पुरुष + 3 महिलाएँ = 6 महिलाएँ, जो 15 दिन लेती हैं।","subtopic":"men-women-children"},
  {"id":"quant-time-work-78","question":"If 5 painters paint 5 rooms in 5 days, how many days will 10 painters take to paint 10 rooms?","options":["5 days","10 days","2.5 days","20 days"],"answer":0,"explanation":"One painter paints one room in 5 days. 10 painters paint 10 rooms in parallel, still 5 days.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"यदि 5 पेंटर 5 कमरों को 5 दिन में रंगते हैं, तो 10 पेंटर 10 कमरों को रंगने में कितने दिन लेंगे?","optionsHi":["5 दिन","10 दिन","2.5 दिन","20 दिन"],"explanationHi":"एक पेंटर एक कमरा 5 दिन में रंगता है। 10 पेंटर 10 कमरे साथ-साथ रंगते हैं, इसलिए फिर भी 5 दिन।","subtopic":"men-women-children"},
  {"id":"quant-time-work-79","question":"A does 40% of a job in 8 days, and B finishes the remaining work in 6 days. How long would they take to do the whole job together?","options":["7 days","14 days","6 days","20/3 days"],"answer":3,"explanation":"A alone = 20 days. B does 60% in 6 days, so B alone = 10 days. Together: 20 × 10/30 = 20/3 days (6⅔).","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य का 40% भाग 8 दिन में करता है, और B शेष कार्य 6 दिन में पूरा करता है। वे दोनों साथ मिलकर पूरा कार्य कितने समय में करेंगे?","optionsHi":["7 दिन","14 दिन","6 दिन","20/3 दिन"],"explanationHi":"A अकेला = 20 दिन। B 6 दिन में 60% करता है, इसलिए B अकेला = 10 दिन। साथ में: 20 × 10/30 = 20/3 दिन (6⅔)।","subtopic":"combined-work"},
  {"id":"quant-time-work-80","question":"Working 6 hours a day, a man finishes a job in 10 days. In how many days will he finish it working 7.5 hours a day?","options":["12.5 days","7.5 days","9 days","8 days"],"answer":3,"explanation":"Total = 60 man-hours. At 7.5 hours a day: 60 ÷ 7.5 = 8 days.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"प्रतिदिन 6 घंटे काम करके एक आदमी किसी कार्य को 10 दिन में पूरा करता है। प्रतिदिन 7.5 घंटे काम करने पर वह उसे कितने दिन में पूरा करेगा?","optionsHi":["12.5 दिन","7.5 दिन","9 दिन","8 दिन"],"explanationHi":"कुल = 60 आदमी-घंटे। प्रतिदिन 7.5 घंटे पर: 60 ÷ 7.5 = 8 दिन।","subtopic":"men-women-children"},
  {"id":"quant-time-work-81","question":"12 carpenters working 8 hours a day make 360 chairs in 15 days. How many days will 16 carpenters working 9 hours a day take to make 540 chairs?","options":["20 days","12 days","15 days","18 days"],"answer":2,"explanation":"Each chair takes 12 × 8 × 15/360 = 4 carpenter-hours. 540 chairs need 2,160 hours; at 16 × 9 = 144 hours a day, that is 15 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"प्रतिदिन 8 घंटे काम करने वाले 12 बढ़ई 15 दिन में 360 कुर्सियाँ बनाते हैं। प्रतिदिन 9 घंटे काम करने वाले 16 बढ़ई 540 कुर्सियाँ बनाने में कितने दिन लेंगे?","optionsHi":["20 दिन","12 दिन","15 दिन","18 दिन"],"explanationHi":"प्रत्येक कुर्सी में 12 × 8 × 15/360 = 4 बढ़ई-घंटे लगते हैं। 540 कुर्सियों के लिए 2,160 घंटे चाहिए; प्रतिदिन 16 × 9 = 144 घंटे के हिसाब से यह 15 दिन होता है।","subtopic":"men-women-children"},
  {"id":"quant-time-work-82","question":"A can finish a job in 10 days, and B is 25% more efficient than A. How long will B take alone?","options":["7.5 days","8 days","12.5 days","8.5 days"],"answer":1,"explanation":"Time ∝ 1/efficiency: 10 ÷ 1.25 = 8 days. Cutting 25% off 10 days (7.5) is the trap.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"A किसी कार्य को 10 दिन में पूरा कर सकता है, और B, A से 25% अधिक कुशल है। B अकेला कितना समय लेगा?","optionsHi":["7.5 दिन","8 दिन","12.5 दिन","8.5 दिन"],"explanationHi":"समय ∝ 1/कार्यक्षमता: 10 ÷ 1.25 = 8 दिन। 10 दिन में से 25% घटाना (7.5) एक जाल है।","subtopic":"efficiency"},
  {"id":"quant-time-work-83","question":"A tap fills 3/4 of a tank in 12 minutes. How much longer will it take to fill the rest?","options":["4 minutes","3 minutes","9 minutes","16 minutes"],"answer":0,"explanation":"3/4 takes 12 minutes, so each quarter takes 4 minutes and the remaining 1/4 takes 4 more. 16 minutes is the total time for the whole tank, not the extra time asked.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"एक नल टंकी का 3/4 भाग 12 मिनट में भरता है। शेष भाग भरने में कितना और समय लगेगा?","optionsHi":["4 मिनट","3 मिनट","9 मिनट","16 मिनट"],"explanationHi":"3/4 भरने में 12 मिनट लगते हैं, इसलिए प्रत्येक चौथाई में 4 मिनट लगते हैं और शेष 1/4 में 4 मिनट और लगेंगे। 16 मिनट पूरी टंकी का कुल समय है, पूछा गया अतिरिक्त समय नहीं।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-84","question":"Typist A types 36 pages in 3 hours and typist B types 45 pages in 5 hours. Working together, how long will they take to type 189 pages?","options":["9 hours","8 hours","10.5 hours","7 hours"],"answer":0,"explanation":"A types 12 pages an hour and B 9. Together 21 an hour: 189 ÷ 21 = 9 hours.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"टाइपिस्ट A 3 घंटे में 36 पृष्ठ और टाइपिस्ट B 5 घंटे में 45 पृष्ठ टाइप करता है। साथ काम करते हुए वे 189 पृष्ठ टाइप करने में कितना समय लेंगे?","optionsHi":["9 घंटे","8 घंटे","10.5 घंटे","7 घंटे"],"explanationHi":"A प्रति घंटा 12 पृष्ठ और B 9 पृष्ठ टाइप करता है। साथ में 21 प्रति घंटा: 189 ÷ 21 = 9 घंटे।","subtopic":"combined-work"},
  {"id":"quant-time-work-85","question":"A tailor stitches 8 shirts a day and his helper 5. For an order of 146 shirts, the tailor works alone for the first 2 days and then the helper joins him. In how many days is the order completed?","options":["11 days","13 days","10 days","12 days"],"answer":3,"explanation":"In 2 days the tailor makes 16 shirts. The remaining 130 at 13 a day take 10 days. Total = 12 days.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक दर्जी प्रतिदिन 8 कमीजें सिलता है और उसका सहायक 5। 146 कमीजों के ऑर्डर के लिए दर्जी पहले 2 दिन अकेला काम करता है और फिर सहायक भी जुड़ जाता है। ऑर्डर कितने दिन में पूरा होता है?","optionsHi":["11 दिन","13 दिन","10 दिन","12 दिन"],"explanationHi":"2 दिन में दर्जी 16 कमीजें बनाता है। शेष 130 कमीजें प्रतिदिन 13 की दर से 10 दिन में बनती हैं। कुल = 12 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-86","question":"A can do a job in 20 days and B in 30 days. They work together for 4 days. What fraction of the job is left?","options":["1/3","1/2","2/3","3/5"],"answer":2,"explanation":"Together they do 1/12 a day, so 4/12 = 1/3 in 4 days. Two-thirds is left.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"A किसी कार्य को 20 दिन में और B 30 दिन में कर सकता है। वे 4 दिन साथ काम करते हैं। कार्य का कितना भाग शेष रहता है?","optionsHi":["1/3","1/2","2/3","3/5"],"explanationHi":"साथ में वे प्रतिदिन 1/12 करते हैं, इसलिए 4 दिन में 4/12 = 1/3। दो-तिहाई शेष रहता है।","subtopic":"combined-work"},
  {"id":"quant-time-work-87","question":"A can lay 1 km of pipeline in 6 days and B in 9 days. Working together, how long will they take to lay 2.5 km?","options":["7.5 days","9 days","10 days","8 days"],"answer":1,"explanation":"Together they lay 1/6 + 1/9 = 5/18 km a day, so 2.5 km takes 2.5 × 18/5 = 9 days. 7.5 days averages 6 and 9 instead of adding rates; check: 9 × 5/18 = 2.5 km.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"A 6 दिन में 1 km पाइपलाइन बिछा सकता है और B 9 दिन में। साथ काम करते हुए वे 2.5 km बिछाने में कितना समय लेंगे?","optionsHi":["7.5 दिन","9 दिन","10 दिन","8 दिन"],"explanationHi":"साथ में वे प्रतिदिन 1/6 + 1/9 = 5/18 km बिछाते हैं, इसलिए 2.5 km में 2.5 × 18/5 = 9 दिन लगते हैं। 7.5 दिन दरें जोड़ने के बजाय 6 और 9 का औसत लेना है; जाँच: 9 × 5/18 = 2.5 km।","subtopic":"combined-work"},
  {"id":"quant-time-work-88","question":"6 robots pack 1,800 boxes in 5 hours. How many boxes will 8 robots pack in 7.5 hours?","options":["2,400","3,600","3,000","4,000"],"answer":1,"explanation":"Each robot packs 1,800/30 = 60 boxes an hour. 8 × 7.5 × 60 = 3,600 boxes.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"6 रोबोट 5 घंटे में 1,800 डिब्बे पैक करते हैं। 8 रोबोट 7.5 घंटे में कितने डिब्बे पैक करेंगे?","optionsHi":["2,400","3,600","3,000","4,000"],"explanationHi":"प्रत्येक रोबोट प्रति घंटा 1,800/30 = 60 डिब्बे पैक करता है। 8 × 7.5 × 60 = 3,600 डिब्बे।","subtopic":"men-women-children"},
  {"id":"quant-time-work-89","question":"3 pumps working 8 hours a day empty a tank in 2 days. How many hours a day must 4 pumps work to empty it in 1 day?","options":["12 hours","16 hours","10.67 hours","6 hours"],"answer":0,"explanation":"Pump-hours = 3 × 8 × 2 = 48. With 4 pumps in 1 day: 48 ÷ 4 = 12 hours.","difficulty":"moderate","source":"SSC CHSL · RRB Group D","questionHi":"प्रतिदिन 8 घंटे चलने वाले 3 पंप किसी टंकी को 2 दिन में खाली करते हैं। 4 पंपों को उसे 1 दिन में खाली करने के लिए प्रतिदिन कितने घंटे चलना होगा?","optionsHi":["12 घंटे","16 घंटे","10.67 घंटे","6 घंटे"],"explanationHi":"पंप-घंटे = 3 × 8 × 2 = 48। 1 दिन में 4 पंपों के साथ: 48 ÷ 4 = 12 घंटे।","subtopic":"men-women-children"},
  {"id":"quant-time-work-90","question":"30 men build a 120 m wall in 8 days. How many men are needed to build a 90 m wall in 5 days?","options":["30","45","32","36"],"answer":3,"explanation":"Each metre takes 30 × 8/120 = 2 man-days. 90 m need 180 man-days; in 5 days that is 36 men.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"30 आदमी 8 दिन में 120 m लंबी दीवार बनाते हैं। 5 दिन में 90 m लंबी दीवार बनाने के लिए कितने आदमी चाहिए?","optionsHi":["30","45","32","36"],"explanationHi":"प्रत्येक मीटर में 30 × 8/120 = 2 आदमी-दिन लगते हैं। 90 m के लिए 180 आदमी-दिन चाहिए; 5 दिन में यह 36 आदमी होते हैं।","subtopic":"men-women-children"},
  {"id":"quant-time-work-91","question":"The efficiencies of A and B are in the ratio 5 : 3, and together they finish a job in 15 days. How long would A take alone?","options":["40 days","25 days","24 days","20 days"],"answer":2,"explanation":"Total work = (5 + 3) × 15 = 120 units. A alone = 120 ÷ 5 = 24 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"A और B की कार्यक्षमताओं का अनुपात 5 : 3 है, और साथ मिलकर वे किसी कार्य को 15 दिन में पूरा करते हैं। A अकेला कितना समय लेगा?","optionsHi":["40 दिन","25 दिन","24 दिन","20 दिन"],"explanationHi":"कुल कार्य = (5 + 3) × 15 = 120 इकाई। A अकेला = 120 ÷ 5 = 24 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-92","question":"A finishes 7/10 of a job in 14 days, and B finishes the rest in 9 days. How long would they take to do the whole job together?","options":["11.5 days","23 days","12 days","10 days"],"answer":2,"explanation":"A alone = 14 × 10/7 = 20 days; B does 3/10 in 9 days, so B alone = 30 days. Together 12 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य का 7/10 भाग 14 दिन में पूरा करता है, और B शेष कार्य 9 दिन में पूरा करता है। वे दोनों साथ मिलकर पूरा कार्य कितने दिन में करेंगे?","optionsHi":["11.5 दिन","23 दिन","12 दिन","10 दिन"],"explanationHi":"A अकेला = 14 × 10/7 = 20 दिन; B 9 दिन में 3/10 करता है, इसलिए B अकेला = 30 दिन। साथ में 12 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-93","question":"12 typists type 360 pages in 5 hours. How many typists are needed to type 600 pages in 4 hours?","options":["20","25","24","30"],"answer":1,"explanation":"Each page takes 12 × 5/360 = 1/6 typist-hour. 600 pages need 100 typist-hours; in 4 hours that is 25 typists.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"12 टाइपिस्ट 5 घंटे में 360 पृष्ठ टाइप करते हैं। 4 घंटे में 600 पृष्ठ टाइप करने के लिए कितने टाइपिस्ट चाहिए?","optionsHi":["20","25","24","30"],"explanationHi":"प्रत्येक पृष्ठ में 12 × 5/360 = 1/6 टाइपिस्ट-घंटा लगता है। 600 पृष्ठों के लिए 100 टाइपिस्ट-घंटे चाहिए; 4 घंटे में यह 25 टाइपिस्ट होते हैं।","subtopic":"men-women-children"},
  {"id":"quant-time-work-94","question":"A is 40% more efficient than B, and C is 20% less efficient than B. If B alone takes 44 days to finish a job, how long will A and C take together?","options":["22 days","24 days","20 days","18 days"],"answer":2,"explanation":"Take B's rate as 1 unit: A = 1.4, C = 0.8, so A + C = 2.2 units. Time = 44 ÷ 2.2 = 20 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A, B से 40% अधिक कुशल है, और C, B से 20% कम कुशल है। यदि B अकेला किसी कार्य को 44 दिन में पूरा करता है, तो A और C साथ मिलकर कितना समय लेंगे?","optionsHi":["22 दिन","24 दिन","20 दिन","18 दिन"],"explanationHi":"B की दर 1 इकाई मानें: A = 1.4, C = 0.8, इसलिए A + C = 2.2 इकाई। समय = 44 ÷ 2.2 = 20 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-95","question":"Pipe A alone fills a tank in 12 hours. When the tank is half full, pipe B, which can fill it alone in 6 hours, is also opened. How long does it take to fill the tank in all?","options":["9 hours","8 hours","6 hours","10 hours"],"answer":1,"explanation":"A fills the first half in 6 hours. Together they fill 1/12 + 1/6 = 1/4 an hour, so the second half takes 2 hours. Total 8 hours.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"पाइप A अकेला एक टंकी को 12 घंटे में भरता है। जब टंकी आधी भर जाती है, तो पाइप B, जो उसे अकेला 6 घंटे में भर सकता है, भी खोल दिया जाता है। टंकी भरने में कुल कितना समय लगता है?","optionsHi":["9 घंटे","8 घंटे","6 घंटे","10 घंटे"],"explanationHi":"A पहला आधा भाग 6 घंटे में भरता है। साथ में वे 1/12 + 1/6 = 1/4 प्रति घंटा भरते हैं, इसलिए दूसरे आधे भाग में 2 घंटे लगते हैं। कुल 8 घंटे।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-96","question":"Pipes A and B fill a tank in 20 and 25 minutes. A is opened first. After how many minutes should B be opened so that the tank is full exactly 15 minutes after A was opened?","options":["8.75 minutes","6.25 minutes","7.5 minutes","10 minutes"],"answer":0,"explanation":"In 15 minutes A fills 3/4. B must fill 1/4, which takes 25/4 = 6.25 minutes, so B is opened after 15 − 6.25 = 8.75 minutes.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"पाइप A और B एक टंकी को 20 और 25 मिनट में भरते हैं। पहले A को खोला जाता है। B को कितने मिनट बाद खोलना चाहिए ताकि टंकी A खुलने के ठीक 15 मिनट बाद भर जाए?","optionsHi":["8.75 मिनट","6.25 मिनट","7.5 मिनट","10 मिनट"],"explanationHi":"15 मिनट में A 3/4 भरता है। B को 1/4 भरना है, जिसमें 25/4 = 6.25 मिनट लगते हैं, इसलिए B को 15 − 6.25 = 8.75 मिनट बाद खोला जाता है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-97","question":"40 workers can build a road in 60 days. After 15 days, 10 workers leave; after another 15 days, 20 new workers join. In how many days in all is the road finished?","options":["60 days","54 days","58 days","57 days"],"answer":3,"explanation":"Total = 2,400 worker-days. First 15 days: 600; next 15 days: 450. The remaining 1,350 at 50 workers take 27 days. Total = 57 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"40 कर्मचारी किसी सड़क को 60 दिन में बना सकते हैं। 15 दिन बाद 10 कर्मचारी चले जाते हैं; 15 दिन और बाद 20 नए कर्मचारी जुड़ जाते हैं। सड़क कुल कितने दिन में बनती है?","optionsHi":["60 दिन","54 दिन","58 दिन","57 दिन"],"explanationHi":"कुल = 2,400 कर्मचारी-दिन। पहले 15 दिन: 600; अगले 15 दिन: 450। शेष 1,350 कर्मचारी-दिन 50 कर्मचारियों से 27 दिन में पूरे होते हैं। कुल = 57 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-98","question":"A can do a job in 18 days. B is 50% more efficient than A, and C is only half as efficient as A. How long will all three take together?","options":["7.2 days","5 days","8 days","6 days"],"answer":3,"explanation":"A = 18 days, B = 12 days, C = 36 days. With 36 units: 2 + 3 + 1 = 6 a day, so 6 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य को 18 दिन में कर सकता है। B, A से 50% अधिक कुशल है, और C, A से केवल आधा कुशल है। तीनों साथ मिलकर कितना समय लेंगे?","optionsHi":["7.2 दिन","5 दिन","8 दिन","6 दिन"],"explanationHi":"A = 18 दिन, B = 12 दिन, C = 36 दिन। 36 इकाई कार्य मानने पर: 2 + 3 + 1 = प्रतिदिन 6, इसलिए 6 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-99","question":"A can do a job in 10 days and B in 15 days. They work together, but A takes a 2-day break in between. How many days does the job take?","options":["6 days","8 days","7.2 days","7 days"],"answer":2,"explanation":"If the job takes t days, A works t − 2 days: (t − 2)/10 + t/15 = 1 gives 3t − 6 + 2t = 30, so t = 7.2 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य को 10 दिन में और B 15 दिन में कर सकता है। वे साथ काम करते हैं, परंतु बीच में A 2 दिन का अवकाश लेता है। कार्य में कितने दिन लगते हैं?","optionsHi":["6 दिन","8 दिन","7.2 दिन","7 दिन"],"explanationHi":"यदि कार्य में t दिन लगते हैं, तो A t − 2 दिन काम करता है: (t − 2)/10 + t/15 = 1 से 3t − 6 + 2t = 30, इसलिए t = 7.2 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-100","question":"A job is done if A works 4 days and B works 6 days, or if A works 6 days and B works 3 days. How long would A take alone?","options":["12 days","8 days","10 days","9 days"],"answer":1,"explanation":"4a + 6b = 1 and 6a + 3b = 1. Doubling the second: 12a + 6b = 2. Subtracting the first: 8a = 1, so A takes 8 days (B takes 24).","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कार्य पूरा हो जाता है यदि A 4 दिन और B 6 दिन काम करे, या यदि A 6 दिन और B 3 दिन काम करे। A अकेला कितना समय लेगा?","optionsHi":["12 दिन","8 दिन","10 दिन","9 दिन"],"explanationHi":"4a + 6b = 1 और 6a + 3b = 1। दूसरे समीकरण को दोगुना करने पर: 12a + 6b = 2। पहले को घटाने पर: 8a = 1, इसलिए A को 8 दिन लगेंगे (B को 24)।","subtopic":"combined-work"},
  {"id":"quant-time-work-101","question":"A is 60% more efficient than B, and together they finish a job in 12 days. How long would B take alone?","options":["31.2 days","19.2 days","30 days","24 days"],"answer":0,"explanation":"Rates A : B = 1.6 : 1, so together = 2.6 B-units. B alone takes 12 × 2.6 = 31.2 days.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"A, B से 60% अधिक कुशल है, और साथ मिलकर वे किसी कार्य को 12 दिन में पूरा करते हैं। B अकेला कितना समय लेगा?","optionsHi":["31.2 दिन","19.2 दिन","30 दिन","24 दिन"],"explanationHi":"दरों का अनुपात A : B = 1.6 : 1, इसलिए साथ में = 2.6 B-इकाई। B अकेला 12 × 2.6 = 31.2 दिन लेता है।","subtopic":"efficiency"},
  {"id":"quant-time-work-102","question":"A is 25% faster than B, and together they finish a job in 20 days. A works alone for 9 days and B then finishes the job. How many days does B work?","options":["33.75 days","36 days","30 days","31.25 days"],"answer":0,"explanation":"Together = 2.25 B-units, so B alone = 45 days and A alone = 36 days. A's 9 days do 1/4; B does 3/4 × 45 = 33.75 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A, B से 25% तेज़ है, और साथ मिलकर वे किसी कार्य को 20 दिन में पूरा करते हैं। A अकेला 9 दिन काम करता है और फिर B कार्य पूरा करता है। B कितने दिन काम करता है?","optionsHi":["33.75 दिन","36 दिन","30 दिन","31.25 दिन"],"explanationHi":"साथ में = 2.25 B-इकाई, इसलिए B अकेला = 45 दिन और A अकेला = 36 दिन। A के 9 दिन 1/4 कार्य करते हैं; B को 3/4 × 45 = 33.75 दिन लगते हैं।","subtopic":"efficiency"},
  {"id":"quant-time-work-103","question":"A can do a job in 20 days and B in 30 days. Owing to a power cut, both work at only 80% of their usual efficiency. How long will they take together?","options":["12 days","14.4 days","9.6 days","15 days"],"answer":3,"explanation":"Normally they take 12 days together. At 80% efficiency the time becomes 12 ÷ 0.8 = 15 days (not 12 × 0.8).","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"A किसी कार्य को 20 दिन में और B 30 दिन में कर सकता है। बिजली कटौती के कारण दोनों अपनी सामान्य कार्यक्षमता के केवल 80% पर काम करते हैं। साथ में वे कितना समय लेंगे?","optionsHi":["12 दिन","14.4 दिन","9.6 दिन","15 दिन"],"explanationHi":"सामान्यतः साथ में वे 12 दिन लेते हैं। 80% कार्यक्षमता पर समय 12 ÷ 0.8 = 15 दिन हो जाता है (12 × 0.8 नहीं)।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-104","question":"A can do a job in 18 days and B is 50% more efficient than A. They start together; after some days A leaves and B finishes the rest in 4 days. After how many days did A leave?","options":["4 days","6 days","4.8 days","5.2 days"],"answer":2,"explanation":"B alone = 12 days, so his last 4 days do 1/3. The other 2/3 was done together at 5/36 a day: (2/3) ÷ (5/36) = 4.8 days.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"A किसी कार्य को 18 दिन में कर सकता है और B, A से 50% अधिक कुशल है। वे साथ शुरू करते हैं; कुछ दिन बाद A चला जाता है और B शेष कार्य 4 दिन में पूरा करता है। A कितने दिन बाद गया?","optionsHi":["4 दिन","6 दिन","4.8 दिन","5.2 दिन"],"explanationHi":"B अकेला = 12 दिन, इसलिए उसके अंतिम 4 दिन 1/3 कार्य करते हैं। शेष 2/3 कार्य साथ में 5/36 प्रतिदिन की दर से हुआ: (2/3) ÷ (5/36) = 4.8 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-105","question":"16 men working 9 hours a day dig a 72 m trench in 30 days. How many men working 12 hours a day can dig a 96 m trench in 24 days?","options":["24","20","18","16"],"answer":1,"explanation":"Each metre takes 16 × 9 × 30/72 = 60 man-hours. 96 m need 5,760 man-hours; 24 × 12 = 288 hours per man, so 20 men.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"प्रतिदिन 9 घंटे काम करने वाले 16 आदमी 30 दिन में 72 m लंबी खाई खोदते हैं। प्रतिदिन 12 घंटे काम करने वाले कितने आदमी 24 दिन में 96 m लंबी खाई खोद सकते हैं?","optionsHi":["24","20","18","16"],"explanationHi":"प्रत्येक मीटर में 16 × 9 × 30/72 = 60 आदमी-घंटे लगते हैं। 96 m के लिए 5,760 आदमी-घंटे चाहिए; प्रति आदमी 24 × 12 = 288 घंटे, इसलिए 20 आदमी।","subtopic":"men-women-children"},
  {"id":"quant-time-work-106","question":"A and B are paid ₹2,400 for a job that A alone can do in 8 days and B alone in 12 days. They work together, but A leaves 2 days before the job is finished. If the pay is shared by work done, what does A get?","options":["₹1,440","₹1,200","₹960","₹1,000"],"answer":1,"explanation":"(t − 2)/8 + t/12 = 1 gives t = 6 days. A works 4 days and does 1/2 of the job, so he gets ₹1,200.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक कार्य के लिए A और B को ₹2,400 मिलते हैं, जिसे A अकेला 8 दिन में और B अकेला 12 दिन में कर सकता है। वे साथ काम करते हैं, परंतु कार्य पूरा होने से 2 दिन पहले A चला जाता है। यदि भुगतान किए गए कार्य के अनुसार बँटे, तो A को कितना मिलेगा?","optionsHi":["₹1,440","₹1,200","₹960","₹1,000"],"explanationHi":"(t − 2)/8 + t/12 = 1 से t = 6 दिन। A 4 दिन काम करता है और कार्य का 1/2 भाग करता है, इसलिए उसे ₹1,200 मिलेंगे।","subtopic":"work-wages"},
  {"id":"quant-time-work-107","question":"A does one-third of a job in 4 days. Then his efficiency rises by 50%. How many days does he take for the whole job?","options":["28/3 days","12 days","8 days","10 days"],"answer":0,"explanation":"His rate is 1/12 a day, rising to 1.5/12 = 1/8. The remaining 2/3 takes 16/3 days. Total = 4 + 16/3 = 28/3 days (9⅓).","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य का एक-तिहाई भाग 4 दिन में करता है। फिर उसकी कार्यक्षमता 50% बढ़ जाती है। पूरे कार्य में उसे कितने दिन लगते हैं?","optionsHi":["28/3 दिन","12 दिन","8 दिन","10 दिन"],"explanationHi":"उसकी दर 1/12 प्रतिदिन है, जो बढ़कर 1.5/12 = 1/8 हो जाती है। शेष 2/3 में 16/3 दिन लगते हैं। कुल = 4 + 16/3 = 28/3 दिन (9⅓)।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-108","question":"A can do a job in 12 days. With B's help he can do it in 8 days, and with C's help in 6 days. How long will B and C take together, without A?","options":["7 days","9 days","4.8 days","8 days"],"answer":3,"explanation":"B = 1/8 − 1/12 = 1/24 and C = 1/6 − 1/12 = 1/12. B + C = 3/24 = 1/8, so 8 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य को 12 दिन में कर सकता है। B की सहायता से वह उसे 8 दिन में और C की सहायता से 6 दिन में कर सकता है। A के बिना B और C साथ मिलकर कितना समय लेंगे?","optionsHi":["7 दिन","9 दिन","4.8 दिन","8 दिन"],"explanationHi":"B = 1/8 − 1/12 = 1/24 और C = 1/6 − 1/12 = 1/12। B + C = 3/24 = 1/8, इसलिए 8 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-109","question":"The efficiencies of A and B are in the ratio 4 : 3, and A finishes a job 6 days sooner than B. How long will they take together?","options":["12 days","21 days","72/7 days","10 days"],"answer":2,"explanation":"Times are in the ratio 3 : 4, a difference of 1 part = 6 days. So A = 18 and B = 24 days. Together: 18 × 24/42 = 72/7 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A और B की कार्यक्षमताओं का अनुपात 4 : 3 है, और A किसी कार्य को B से 6 दिन पहले पूरा करता है। साथ मिलकर वे कितना समय लेंगे?","optionsHi":["12 दिन","21 दिन","72/7 दिन","10 दिन"],"explanationHi":"समयों का अनुपात 3 : 4 है, अंतर 1 भाग = 6 दिन। इसलिए A = 18 और B = 24 दिन। साथ में: 18 × 24/42 = 72/7 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-110","question":"A group of men can finish a job in a certain number of days. With 6 more men it would be done 5 days earlier, and with 4 fewer men it would take 5 days longer. How many men are there?","options":["20","30","24","25"],"answer":2,"explanation":"nd = (n + 6)(d − 5) gives 6d − 5n = 30; nd = (n − 4)(d + 5) gives 5n − 4d = 20. Adding: 2d = 50, d = 25 and n = 24.","difficulty":"very-hard","source":"SSC CGL Tier 2 · SSC CPO","questionHi":"आदमियों का एक समूह किसी कार्य को कुछ दिनों में पूरा कर सकता है। 6 आदमी अधिक होने पर वह 5 दिन पहले पूरा हो जाता, और 4 आदमी कम होने पर उसमें 5 दिन अधिक लगते। कुल कितने आदमी हैं?","optionsHi":["20","30","24","25"],"explanationHi":"nd = (n + 6)(d − 5) से 6d − 5n = 30; nd = (n − 4)(d + 5) से 5n − 4d = 20। जोड़ने पर: 2d = 50, d = 25 और n = 24।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-111","question":"Ram does 1/3 of a job in 5 days. Shyam then does 2/5 of the remaining work in 4 days, and Mohan finishes the rest in 6 days. How long would all three take working together?","options":["6 days","5 days","4 days","7.5 days"],"answer":1,"explanation":"Ram alone = 15 days. Shyam does 4/15 in 4 days, so 15 days alone. Mohan does 2/5 in 6 days, also 15 days. Three at 1/15 each finish in 5 days.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"राम किसी कार्य का 1/3 भाग 5 दिन में करता है। फिर श्याम शेष कार्य का 2/5 भाग 4 दिन में करता है, और मोहन शेष 6 दिन में पूरा करता है। तीनों साथ काम करें तो कितना समय लेंगे?","optionsHi":["6 दिन","5 दिन","4 दिन","7.5 दिन"],"explanationHi":"राम अकेला = 15 दिन। श्याम 4 दिन में 4/15 करता है, इसलिए अकेले 15 दिन। मोहन 6 दिन में 2/5 करता है, यानी वह भी 15 दिन। तीनों 1/15 प्रत्येक की दर से 5 दिन में पूरा करेंगे।","subtopic":"combined-work"},
  {"id":"quant-time-work-112","question":"A and B together can finish a job in 12 days. If A works for 3 days and B for 6 days, 7/20 of the job is done. How long would A take alone?","options":["20 days","30 days","15 days","24 days"],"answer":0,"explanation":"Working together for 6 days would do 6/12 = 1/2. A worked 3 of those days less, so 1/2 − 3a = 7/20, giving 3a = 3/20 and A alone = 20 days.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"A और B मिलकर किसी कार्य को 12 दिन में पूरा कर सकते हैं। यदि A 3 दिन और B 6 दिन काम करे, तो कार्य का 7/20 भाग होता है। A अकेला कितना समय लेगा?","optionsHi":["20 दिन","30 दिन","15 दिन","24 दिन"],"explanationHi":"साथ में 6 दिन काम करने पर 6/12 = 1/2 होता। A ने उनमें से 3 दिन कम काम किया, इसलिए 1/2 − 3a = 7/20, जिससे 3a = 3/20 और A अकेला = 20 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-113","question":"A contractor has 30 days to finish a project and employs 50 men working 8 hours a day. After 18 days only 2/5 of the work is done. How many more men must he hire, all working 10 hours a day from then on, to finish on time?","options":["30","50","25","40"],"answer":3,"explanation":"2/5 of the work = 50 × 8 × 18 = 7,200 man-hours, so 3/5 = 10,800. In 12 days × 10 hours = 120 hours per man, 90 men are needed: 40 more.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक ठेकेदार के पास परियोजना पूरी करने के लिए 30 दिन हैं और वह प्रतिदिन 8 घंटे काम करने वाले 50 आदमी लगाता है। 18 दिन बाद केवल 2/5 कार्य हुआ है। समय पर पूरा करने के लिए उसे और कितने आदमी लगाने होंगे, जो सभी आगे प्रतिदिन 10 घंटे काम करेंगे?","optionsHi":["30","50","25","40"],"explanationHi":"2/5 कार्य = 50 × 8 × 18 = 7,200 आदमी-घंटे, इसलिए 3/5 = 10,800। 12 दिन × 10 घंटे = प्रति आदमी 120 घंटे, इसलिए 90 आदमी चाहिए: 40 और।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-114","question":"A takes 5 days more than B and 9 days more than C to do a job alone. A and B together take as long as C alone. How long does A take alone?","options":["10 days","6 days","12 days","15 days"],"answer":3,"explanation":"Let C = c, so A = c + 9 and B = c + 4. 1/(c + 9) + 1/(c + 4) = 1/c simplifies to c² = 36, so c = 6 and A = 15 days.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"A किसी कार्य को अकेले करने में B से 5 दिन अधिक और C से 9 दिन अधिक लेता है। A और B साथ मिलकर उतना ही समय लेते हैं जितना C अकेला। A अकेला कितना समय लेता है?","optionsHi":["10 दिन","6 दिन","12 दिन","15 दिन"],"explanationHi":"मान लीजिए C = c, तो A = c + 9 और B = c + 4। 1/(c + 9) + 1/(c + 4) = 1/c को सरल करने पर c² = 36, इसलिए c = 6 और A = 15 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-115","question":"A is twice as efficient as B, and B is twice as efficient as C. A finishes a job 30 days sooner than C. How long will all three take together?","options":["7 days","10 days","40/7 days","20/3 days"],"answer":2,"explanation":"If A takes t days, C takes 4t: 3t = 30 gives t = 10. Rates 1/10 + 1/20 + 1/40 = 7/40, so 40/7 days (about 5.7).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"A, B से दोगुना कुशल है, और B, C से दोगुना कुशल है। A किसी कार्य को C से 30 दिन पहले पूरा करता है। तीनों साथ मिलकर कितना समय लेंगे?","optionsHi":["7 दिन","10 दिन","40/7 दिन","20/3 दिन"],"explanationHi":"यदि A को t दिन लगें, तो C को 4t दिन लगेंगे: 3t = 30 से t = 10। दरें 1/10 + 1/20 + 1/40 = 7/40, इसलिए 40/7 दिन (लगभग 5.7)।","subtopic":"efficiency"},
  {"id":"quant-time-work-116","question":"Pipe A fills a tank in 12 hours and pipe B empties it in 18 hours. Starting with an empty tank, they are opened alternately for one hour each, A first. After how many hours is the tank first full?","options":["67 hours","72 hours","36 hours","66 hours"],"answer":0,"explanation":"Each 2-hour cycle adds 1/12 − 1/18 = 1/36. After 33 cycles (66 hours) the tank is 33/36 full, and A's next hour adds the last 3/36. Total 67 hours, not 72.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"पाइप A एक टंकी को 12 घंटे में भरता है और पाइप B उसे 18 घंटे में खाली करता है। खाली टंकी से शुरू करके उन्हें एक-एक घंटे के लिए एकांतर रूप से खोला जाता है, पहले A। टंकी पहली बार कितने घंटे बाद भरती है?","optionsHi":["67 घंटे","72 घंटे","36 घंटे","66 घंटे"],"explanationHi":"प्रत्येक 2 घंटे के चक्र में 1/12 − 1/18 = 1/36 जुड़ता है। 33 चक्र (66 घंटे) बाद टंकी 33/36 भरी होती है, और A का अगला घंटा शेष 3/36 जोड़ देता है। कुल 67 घंटे, 72 नहीं।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-117","question":"A works alone on day 1, A and B on day 2, A, B and C on day 3, and the pattern repeats. A, B and C alone take 30, 40 and 60 days. In how many days is the job done?","options":["20 days","15 days","17 days","18 days"],"answer":3,"explanation":"With 120 units: A = 4, B = 3, C = 2 per day. One 3-day cycle = 4 + 7 + 9 = 20 units, so 6 cycles = 120 units in exactly 18 days.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"A दिन 1 में अकेला काम करता है, दिन 2 में A और B, दिन 3 में A, B और C, और यह क्रम दोहराया जाता है। A, B और C अकेले क्रमशः 30, 40 और 60 दिन लेते हैं। कार्य कितने दिन में पूरा होता है?","optionsHi":["20 दिन","15 दिन","17 दिन","18 दिन"],"explanationHi":"120 इकाई मानने पर: A = 4, B = 3, C = 2 प्रतिदिन। एक 3 दिन का चक्र = 4 + 7 + 9 = 20 इकाई, इसलिए 6 चक्र = 120 इकाई ठीक 18 दिन में।","subtopic":"alternate-days"},
  {"id":"quant-time-work-118","question":"Pipes A and B fill a tank in 10 and 15 hours, and pipe C drains it. With all three open, the empty tank fills in 9 hours. How long would it take to fill the empty tank with only B and C open?","options":["18 hours","45 hours","90 hours","30 hours"],"answer":2,"explanation":"A + B = 1/6, so C drains 1/6 − 1/9 = 1/18 an hour. B − C = 1/15 − 1/18 = 1/90, so 90 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"पाइप A और B एक टंकी को 10 और 15 घंटे में भरते हैं, और पाइप C उसे खाली करता है। तीनों खुले होने पर खाली टंकी 9 घंटे में भरती है। केवल B और C खुले होने पर खाली टंकी भरने में कितना समय लगेगा?","optionsHi":["18 घंटे","45 घंटे","90 घंटे","30 घंटे"],"explanationHi":"A + B = 1/6, इसलिए C प्रति घंटा 1/6 − 1/9 = 1/18 खाली करता है। B − C = 1/15 − 1/18 = 1/90, इसलिए 90 घंटे।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-119","question":"A and B together finish a job in t days. A alone would take 9 days more than t, and B alone 16 days more than t. What is t?","options":["12.5","12","25","10"],"answer":1,"explanation":"1/(t + 9) + 1/(t + 16) = 1/t simplifies to t² = 9 × 16 = 144, so t = 12. (The together-time is the geometric mean of the two extra times.)","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT-style","questionHi":"A और B साथ मिलकर किसी कार्य को t दिन में पूरा करते हैं। A अकेला t से 9 दिन अधिक और B अकेला t से 16 दिन अधिक लेता। t का मान क्या है?","optionsHi":["12.5","12","25","10"],"explanationHi":"1/(t + 9) + 1/(t + 16) = 1/t को सरल करने पर t² = 9 × 16 = 144, इसलिए t = 12। (साथ में लगा समय दोनों अतिरिक्त समयों का गुणोत्तर माध्य होता है।)","subtopic":"combined-work"},
  {"id":"quant-time-work-120","question":"A can do a job in 60 days, and A and B together in 30 days. They work together for 20 days, then B is replaced by C, who is 50% more efficient than B. How many days does the whole job take?","options":["30 days","28 days","26 days","28.5 days"],"answer":1,"explanation":"B = 1/30 − 1/60 = 1/60, so C = 1/40. After 20 days, 2/3 is done. A + C = 1/60 + 1/40 = 1/24, so the last 1/3 takes 8 days. Total 28 days.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"A किसी कार्य को 60 दिन में कर सकता है, और A तथा B साथ मिलकर 30 दिन में। वे 20 दिन साथ काम करते हैं, फिर B की जगह C आ जाता है, जो B से 50% अधिक कुशल है। पूरे कार्य में कितने दिन लगते हैं?","optionsHi":["30 दिन","28 दिन","26 दिन","28.5 दिन"],"explanationHi":"B = 1/30 − 1/60 = 1/60, इसलिए C = 1/40। 20 दिन बाद 2/3 हो चुका है। A + C = 1/60 + 1/40 = 1/24, इसलिए अंतिम 1/3 में 8 दिन लगते हैं। कुल 28 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-121","question":"Machine X does a job in 6 hours and costs ₹400 an hour to run; machine Y does it in 9 hours at ₹300 an hour. What does the job cost if both machines work on it together?","options":["₹2,520","₹2,400","₹2,700","₹2,550"],"answer":0,"explanation":"Together they take 6 × 9/15 = 3.6 hours. Cost = 3.6 × (400 + 300) = ₹2,520 — more than X alone (₹2,400).","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"मशीन X किसी कार्य को 6 घंटे में करती है और उसे चलाने का खर्च ₹400 प्रति घंटा है; मशीन Y उसे 9 घंटे में करती है और खर्च ₹300 प्रति घंटा है। यदि दोनों मशीनें साथ काम करें, तो कार्य का खर्च कितना होगा?","optionsHi":["₹2,520","₹2,400","₹2,700","₹2,550"],"explanationHi":"साथ में उन्हें 6 × 9/15 = 3.6 घंटे लगते हैं। खर्च = 3.6 × (400 + 300) = ₹2,520 — जो केवल X से (₹2,400) अधिक है।","subtopic":"work-wages"},
  {"id":"quant-time-work-122","question":"Ramesh can finish a job in 6 hours and Suresh in 12 hours. Ramesh starts at 9:00 am and Suresh joins him at 11:00 am. When is the job finished?","options":["1:20 pm","2:00 pm","12:40 pm","1:40 pm"],"answer":3,"explanation":"By 11 am Ramesh has done 1/3. Together they do 1/4 an hour, so 2/3 takes 8/3 hours = 2 h 40 min. Finish = 1:40 pm.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"रमेश किसी कार्य को 6 घंटे में और सुरेश 12 घंटे में पूरा कर सकता है। रमेश सुबह 9:00 बजे शुरू करता है और सुरेश सुबह 11:00 बजे उसके साथ जुड़ता है। कार्य कब पूरा होगा?","optionsHi":["1:20 pm","2:00 pm","12:40 pm","1:40 pm"],"explanationHi":"सुबह 11 बजे तक रमेश 1/3 कार्य कर चुका है। साथ में वे प्रति घंटा 1/4 करते हैं, इसलिए 2/3 में 8/3 घंटे = 2 घंटे 40 मिनट लगते हैं। समाप्ति = 1:40 pm।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-123","question":"A can paint a wall in 8 hours and B in 12 hours. A starts; B joins after 2 hours, and A stops 1 hour before the job is finished. How long does the job take in all?","options":["6 hours","5.8 hours","6.2 hours","7 hours"],"answer":2,"explanation":"If it takes t hours, A works t − 1 and B works t − 2: (t − 1)/8 + (t − 2)/12 = 1 gives 3t − 3 + 2t − 4 = 24, so t = 6.2 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"A एक दीवार को 8 घंटे में और B 12 घंटे में रंग सकता है। A शुरू करता है; 2 घंटे बाद B जुड़ता है, और कार्य पूरा होने से 1 घंटा पहले A रुक जाता है। कार्य में कुल कितना समय लगता है?","optionsHi":["6 घंटे","5.8 घंटे","6.2 घंटे","7 घंटे"],"explanationHi":"यदि कुल t घंटे लगें, तो A t − 1 घंटे और B t − 2 घंटे काम करता है: (t − 1)/8 + (t − 2)/12 = 1 से 3t − 3 + 2t − 4 = 24, इसलिए t = 6.2 घंटे।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-124","question":"18 workers complete 3/5 of a job in 12 days. How many additional workers are needed to finish the rest of the job in 4 days?","options":["36","12","18","24"],"answer":2,"explanation":"The whole job = 18 × 12 × 5/3 = 360 worker-days, so 2/5 = 144 worker-days. In 4 days that needs 36 workers: 18 more.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"18 कर्मचारी किसी कार्य का 3/5 भाग 12 दिन में पूरा करते हैं। शेष कार्य को 4 दिन में पूरा करने के लिए कितने और कर्मचारी चाहिए?","optionsHi":["36","12","18","24"],"explanationHi":"पूरा कार्य = 18 × 12 × 5/3 = 360 कर्मचारी-दिन, इसलिए 2/5 = 144 कर्मचारी-दिन। 4 दिन में इसके लिए 36 कर्मचारी चाहिए: 18 और।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-125","question":"A pipe fills a tank in 10 hours. When the tank is half full, a crack appears at the bottom that drains 1/30 of the tank every hour. How long does it take in all to fill the tank?","options":["15 hours","12.5 hours","10 hours","13 hours"],"answer":1,"explanation":"First half: 5 hours. Then the net rate is 1/10 − 1/30 = 1/15, so the second half takes 7.5 hours. Total 12.5 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक पाइप टंकी को 10 घंटे में भरता है। जब टंकी आधी भर जाती है, तो तली में एक दरार आ जाती है जिससे हर घंटे टंकी का 1/30 भाग निकल जाता है। टंकी भरने में कुल कितना समय लगता है?","optionsHi":["15 घंटे","12.5 घंटे","10 घंटे","13 घंटे"],"explanationHi":"पहला आधा भाग: 5 घंटे। फिर शुद्ध दर 1/10 − 1/30 = 1/15 है, इसलिए दूसरे आधे भाग में 7.5 घंटे लगते हैं। कुल 12.5 घंटे।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-126","question":"A machine working at full efficiency would finish a job in 10 hours. It runs at full efficiency for the first 4 hours, after which its efficiency drops to 80%. How long does the job take?","options":["11.5 hours","12.5 hours","11 hours","12 hours"],"answer":0,"explanation":"In 4 hours it does 40%. The remaining 60% at 8% an hour takes 7.5 hours. Total = 11.5 hours.","difficulty":"very-hard","source":"SSC CGL · RRB JE","questionHi":"पूर्ण कार्यक्षमता पर काम करने वाली एक मशीन किसी कार्य को 10 घंटे में पूरा करती। वह पहले 4 घंटे पूर्ण कार्यक्षमता पर चलती है, उसके बाद उसकी कार्यक्षमता घटकर 80% रह जाती है। कार्य में कितना समय लगता है?","optionsHi":["11.5 घंटे","12.5 घंटे","11 घंटे","12 घंटे"],"explanationHi":"4 घंटे में वह 40% कार्य करती है। शेष 60% कार्य 8% प्रति घंटा की दर से 7.5 घंटे में होता है। कुल = 11.5 घंटे।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-127","question":"A can do a job in 16 days and B in 12 days. With C's help they finish it in 4 days. If ₹4,800 is paid for the job and shared by work done, what is C's share?","options":["₹1,200","₹1,600","₹1,500","₹2,000"],"answer":3,"explanation":"In 4 days A does 1/4 and B does 1/3, so C does 1 − 1/4 − 1/3 = 5/12. C's share = 5/12 × 4,800 = ₹2,000.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"A किसी कार्य को 16 दिन में और B 12 दिन में कर सकता है। C की सहायता से वे उसे 4 दिन में पूरा कर लेते हैं। यदि कार्य के लिए ₹4,800 दिए जाते हैं और किए गए कार्य के अनुसार बँटते हैं, तो C का हिस्सा कितना है?","optionsHi":["₹1,200","₹1,600","₹1,500","₹2,000"],"explanationHi":"4 दिन में A 1/4 और B 1/3 कार्य करता है, इसलिए C ने 1 − 1/4 − 1/3 = 5/12 किया। C का हिस्सा = 5/12 × 4,800 = ₹2,000।","subtopic":"work-wages"},
  {"id":"quant-time-work-128","question":"A is paid ₹300 a day and finishes a job in 10 days; B is paid ₹200 a day and finishes it in 15 days. Which way of getting the job done costs least?","options":["A alone","B alone","A and B together","All three ways cost the same"],"answer":3,"explanation":"A alone: 10 × 300 = ₹3,000. B alone: 15 × 200 = ₹3,000. Together they take 6 days at ₹500 a day = ₹3,000. Each man's cost per job is the same, so every option costs ₹3,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"A को ₹300 प्रतिदिन मिलते हैं और वह कार्य 10 दिन में पूरा करता है; B को ₹200 प्रतिदिन मिलते हैं और वह उसे 15 दिन में पूरा करता है। कार्य कराने का कौन-सा तरीका सबसे सस्ता है?","optionsHi":["केवल A","केवल B","A और B साथ में","तीनों तरीकों का खर्च समान है"],"explanationHi":"केवल A: 10 × 300 = ₹3,000। केवल B: 15 × 200 = ₹3,000। साथ में उन्हें 6 दिन लगते हैं, ₹500 प्रतिदिन की दर से = ₹3,000। प्रत्येक व्यक्ति का प्रति कार्य खर्च समान है, इसलिए हर विकल्प में ₹3,000 लगते हैं।","subtopic":"work-wages"},
  {"id":"quant-time-work-129","question":"20 men can finish a project in 30 days. After training, every worker becomes 10% more efficient. What is the least number of trained men that can finish the project in 24 days?","options":["22","25","23","28"],"answer":2,"explanation":"Work = 600 man-days at the old rate; each trained man does 1.1 × 24 = 26.4 units in 24 days, so n ≥ 600/26.4 ≈ 22.7 and the least whole number is 23. 22 rounds down and falls short, 25 ignores the training, and 28 multiplies by 1.1 instead of dividing.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"20 आदमी किसी परियोजना को 30 दिन में पूरा कर सकते हैं। प्रशिक्षण के बाद प्रत्येक कर्मचारी 10% अधिक कुशल हो जाता है। परियोजना को 24 दिन में पूरा करने के लिए प्रशिक्षित आदमियों की न्यूनतम संख्या कितनी है?","optionsHi":["22","25","23","28"],"explanationHi":"कार्य = पुरानी दर पर 600 आदमी-दिन; प्रत्येक प्रशिक्षित आदमी 24 दिन में 1.1 × 24 = 26.4 इकाई करता है, इसलिए n ≥ 600/26.4 ≈ 22.7 और न्यूनतम पूर्णांक 23 है। 22 नीचे की ओर पूर्णांकित करने से कम पड़ता है, 25 प्रशिक्षण को अनदेखा करता है, और 28 में 1.1 से भाग देने के बजाय गुणा किया गया है।","subtopic":"efficiency"},
  {"id":"quant-time-work-130","question":"Pipe A fills a tank in 6 hours. Two hours after A is opened, an outlet pipe B is opened by mistake, and the tank becomes full 6 hours after that. How long would B alone take to empty the full tank?","options":["12 hours","18 hours","24 hours","9 hours"],"answer":1,"explanation":"A runs for 8 hours and supplies 8/6 = 4/3 of a tank. So B drained 1/3 of a tank in 6 hours, i.e. a full tank in 18 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"पाइप A एक टंकी को 6 घंटे में भरता है। A को खोलने के 2 घंटे बाद गलती से एक निकास पाइप B खोल दिया जाता है, और उसके 6 घंटे बाद टंकी भर जाती है। B अकेला भरी टंकी को कितने समय में खाली करेगा?","optionsHi":["12 घंटे","18 घंटे","24 घंटे","9 घंटे"],"explanationHi":"A 8 घंटे चलता है और 8/6 = 4/3 टंकी भरता है। इसलिए B ने 6 घंटे में 1/3 टंकी निकाली, यानी पूरी टंकी 18 घंटे में।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-131","question":"A completes 2/7 of a job in 8 days. How long will he take for the whole job?","options":["16 days","24 days","56 days","28 days"],"answer":3,"explanation":"1/7 of the job takes 4 days, so the whole job takes 28 days.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"A किसी कार्य का 2/7 भाग 8 दिन में पूरा करता है। पूरे कार्य में उसे कितने दिन लगेंगे?","optionsHi":["16 दिन","24 दिन","56 दिन","28 दिन"],"explanationHi":"कार्य के 1/7 भाग में 4 दिन लगते हैं, इसलिए पूरे कार्य में 28 दिन लगेंगे।","subtopic":"combined-work"},
  {"id":"quant-time-work-132","question":"A can do a job in 25 days and B in 20 days. A works for 5 days and leaves. How long does B take to finish the rest?","options":["15 days","20 days","16 days","12 days"],"answer":2,"explanation":"A does 1/5 in 5 days, leaving 4/5, which B does in 4/5 × 20 = 16 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"A किसी कार्य को 25 दिन में और B 20 दिन में कर सकता है। A 5 दिन काम करके चला जाता है। शेष कार्य पूरा करने में B को कितने दिन लगेंगे?","optionsHi":["15 दिन","20 दिन","16 दिन","12 दिन"],"explanationHi":"A 5 दिन में 1/5 करता है, जिससे 4/5 शेष रहता है, जिसे B 4/5 × 20 = 16 दिन में करता है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-133","question":"Pipe A fills 1/3 of a tank in 10 minutes and pipe B fills 1/4 of it in 15 minutes. How long will both together take to fill the tank?","options":["25 minutes","20 minutes","12.5 minutes","18 minutes"],"answer":1,"explanation":"A alone = 30 min, B alone = 60 min. Together 30 × 60/90 = 20 minutes.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"पाइप A 10 मिनट में टंकी का 1/3 भाग भरता है और पाइप B 15 मिनट में उसका 1/4 भाग भरता है। दोनों साथ मिलकर टंकी भरने में कितना समय लेंगे?","optionsHi":["25 मिनट","20 मिनट","12.5 मिनट","18 मिनट"],"explanationHi":"A अकेला = 30 मिनट, B अकेला = 60 मिनट। साथ में 30 × 60/90 = 20 मिनट।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-134","question":"Pipes A and B fill a tank in 24 and 32 minutes. Both are opened together. After how many minutes should A be closed so that the tank is full in 18 minutes?","options":["10.5 minutes","8 minutes","12 minutes","13.5 minutes"],"answer":0,"explanation":"B runs all 18 minutes and fills 9/16. A must fill 7/16, which takes 7/16 × 24 = 10.5 minutes.","difficulty":"hard","source":"SSC CGL · SSC CPO","questionHi":"पाइप A और B एक टंकी को 24 और 32 मिनट में भरते हैं। दोनों को साथ खोला जाता है। A को कितने मिनट बाद बंद कर देना चाहिए ताकि टंकी 18 मिनट में भर जाए?","optionsHi":["10.5 मिनट","8 मिनट","12 मिनट","13.5 मिनट"],"explanationHi":"B पूरे 18 मिनट चलता है और 9/16 भरता है। A को 7/16 भरना है, जिसमें 7/16 × 24 = 10.5 मिनट लगते हैं।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-135","question":"Pump A can empty a full pond in 12 hours and pump B in 15 hours. Rain inflow alone would fill the pond in 20 hours. With both pumps running in the rain, how long does it take to empty the full pond?","options":["10 hours","6.67 hours","15 hours","12 hours"],"answer":0,"explanation":"Net rate = 1/12 + 1/15 − 1/20 = (5 + 4 − 3)/60 = 1/10, so 10 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"पंप A भरे तालाब को 12 घंटे में खाली कर सकता है और पंप B 15 घंटे में। केवल वर्षा का पानी तालाब को 20 घंटे में भर देगा। वर्षा में दोनों पंप चलने पर भरा तालाब खाली होने में कितना समय लगता है?","optionsHi":["10 घंटे","6.67 घंटे","15 घंटे","12 घंटे"],"explanationHi":"शुद्ध दर = 1/12 + 1/15 − 1/20 = (5 + 4 − 3)/60 = 1/10, इसलिए 10 घंटे।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-136","question":"A does 20% less work than B each day. Together they finish a job in 16 days. How long would B take alone?","options":["36 days","32 days","25.6 days","28.8 days"],"answer":3,"explanation":"A = 0.8 of B's rate, so together = 1.8 B-units. B alone = 16 × 1.8 = 28.8 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A प्रतिदिन B से 20% कम कार्य करता है। साथ मिलकर वे किसी कार्य को 16 दिन में पूरा करते हैं। B अकेला कितना समय लेगा?","optionsHi":["36 दिन","32 दिन","25.6 दिन","28.8 दिन"],"explanationHi":"A = B की दर का 0.8, इसलिए साथ में = 1.8 B-इकाई। B अकेला = 16 × 1.8 = 28.8 दिन।","subtopic":"efficiency"},
  {"id":"quant-time-work-137","question":"A patch of water hyacinth doubles its area every day and covers a whole lake at the end of day 10. At the end of which day was half the lake covered?","options":["Day 5","Day 8","Day 9","Day 7"],"answer":2,"explanation":"The area doubles each day, so the day before the lake is full it is exactly half covered: day 9. Halving the time (day 5) treats the growth as steady.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"जलकुंभी का एक समूह अपना क्षेत्रफल प्रतिदिन दोगुना कर लेता है और दिन 10 के अंत में पूरी झील को ढक लेता है। दिन के अंत में किस दिन झील का आधा भाग ढका था?","optionsHi":["दिन 5","दिन 8","दिन 9","दिन 7"],"explanationHi":"क्षेत्रफल प्रतिदिन दोगुना होता है, इसलिए झील पूरी ढकने से एक दिन पहले वह ठीक आधी ढकी होती है: दिन 9। समय को आधा करना (दिन 5) वृद्धि को एकसमान मान लेना है।","subtopic":"combined-work"},
  {"id":"quant-time-work-138","question":"A, B and C can do a job alone in 10, 15 and 30 days. A and B work together throughout, and C joins them only for the last 2 days. How long does the job take?","options":["6 days","5.6 days","5 days","5.2 days"],"answer":1,"explanation":"A + B do 1/6 a day, and C adds 2/30 = 1/15 in total. So t/6 = 14/15 and t = 5.6 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A, B और C किसी कार्य को अकेले क्रमशः 10, 15 और 30 दिन में कर सकते हैं। A और B पूरे समय साथ काम करते हैं, और C केवल अंतिम 2 दिन उनके साथ जुड़ता है। कार्य में कितना समय लगता है?","optionsHi":["6 दिन","5.6 दिन","5 दिन","5.2 दिन"],"explanationHi":"A + B प्रतिदिन 1/6 करते हैं, और C कुल मिलाकर 2/30 = 1/15 जोड़ता है। इसलिए t/6 = 14/15 और t = 5.6 दिन।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-139","question":"A is paid ₹450 a day and can finish a job in 12 days; B is paid ₹300 a day and needs 20 days. Which of them is cheaper for the job, and by how much?","options":["B, by ₹600","A, by ₹600","A, by ₹150","Both cost the same"],"answer":1,"explanation":"A costs 12 × 450 = ₹5,400 and B costs 20 × 300 = ₹6,000. A is cheaper by ₹600 despite the higher daily wage.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk","questionHi":"A को ₹450 प्रतिदिन मिलते हैं और वह कार्य 12 दिन में पूरा कर सकता है; B को ₹300 प्रतिदिन मिलते हैं और उसे 20 दिन चाहिए। कार्य के लिए उनमें से कौन सस्ता है, और कितना?","optionsHi":["B, ₹600 से","A, ₹600 से","A, ₹150 से","दोनों का खर्च समान है"],"explanationHi":"A का खर्च 12 × 450 = ₹5,400 और B का खर्च 20 × 300 = ₹6,000 है। अधिक दैनिक मजदूरी के बावजूद A ₹600 सस्ता है।","subtopic":"work-wages"},
  {"id":"quant-time-work-140","question":"An inlet fills a tank in 2 hours and an outlet empties it in 3 hours. The inlet is opened alone, and the outlet is opened too after 1 hour. How long does the tank take to fill in all?","options":["4 hours","3 hours","6 hours","5 hours"],"answer":0,"explanation":"After 1 hour the tank is half full. The net rate is 1/2 − 1/3 = 1/6, so the other half takes 3 hours. Total 4 hours.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक अंतर्वाह पाइप टंकी को 2 घंटे में भरता है और एक निकास पाइप उसे 3 घंटे में खाली करता है। अंतर्वाह पाइप अकेला खोला जाता है, और 1 घंटे बाद निकास पाइप भी खोल दिया जाता है। टंकी भरने में कुल कितना समय लगता है?","optionsHi":["4 घंटे","3 घंटे","6 घंटे","5 घंटे"],"explanationHi":"1 घंटे बाद टंकी आधी भर जाती है। शुद्ध दर 1/2 − 1/3 = 1/6 है, इसलिए शेष आधे में 3 घंटे लगते हैं। कुल 4 घंटे।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-141","question":"One worker makes 12 toys in 3 hours and another makes 10 toys in 2 hours. Working together 6 hours a day, in how many days will they make 324 toys?","options":["9 days","5 days","7 days","6 days"],"answer":3,"explanation":"Rates: 4 and 5 toys an hour, 9 together, so 54 toys a day. 324 ÷ 54 = 6 days.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक कारीगर 3 घंटे में 12 खिलौने बनाता है और दूसरा 2 घंटे में 10 खिलौने। प्रतिदिन 6 घंटे साथ काम करते हुए वे 324 खिलौने कितने दिन में बनाएँगे?","optionsHi":["9 दिन","5 दिन","7 दिन","6 दिन"],"explanationHi":"दरें: प्रति घंटा 4 और 5 खिलौने, साथ में 9, इसलिए प्रतिदिन 54 खिलौने। 324 ÷ 54 = 6 दिन।","subtopic":"combined-work"},
  {"id":"quant-time-work-142","question":"3 men or 6 boys can do a job in 20 days. How long will 2 men and 4 boys take?","options":["20 days","10 days","15 days","12 days"],"answer":2,"explanation":"1 man = 2 boys, so 2 men + 4 boys = 8 boys. 6 boys take 20 days, so 8 boys take 20 × 6/8 = 15 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"3 पुरुष या 6 लड़के किसी कार्य को 20 दिन में कर सकते हैं। 2 पुरुष और 4 लड़के कितना समय लेंगे?","optionsHi":["20 दिन","10 दिन","15 दिन","12 दिन"],"explanationHi":"1 पुरुष = 2 लड़के, इसलिए 2 पुरुष + 4 लड़के = 8 लड़के। 6 लड़के 20 दिन लेते हैं, तो 8 लड़के 20 × 6/8 = 15 दिन लेंगे।","subtopic":"men-women-children"},
  {"id":"quant-time-work-143","question":"A can finish a job in 12 days and B in 18 days. They start together, but A leaves 3 days before the job is finished. In how many days is the job finished?","options":["7.2 days","8.4 days","10.2 days","9 days"],"answer":3,"explanation":"Take the job as 36 units: A does 3 a day, B 2. 3(t − 3) + 2t = 36 gives t = 9 days. Making B the one who leaves early gives 8.4; ignoring the departure gives 7.2.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A किसी कार्य को 12 दिन में और B 18 दिन में पूरा कर सकता है। वे साथ शुरू करते हैं, परंतु कार्य पूरा होने से 3 दिन पहले A चला जाता है। कार्य कितने दिन में पूरा होता है?","optionsHi":["7.2 दिन","8.4 दिन","10.2 दिन","9 दिन"],"explanationHi":"कार्य को 36 इकाई मानें: A प्रतिदिन 3 और B 2 करता है। 3(t − 3) + 2t = 36 से t = 9 दिन। यदि B को पहले जाने वाला मानें तो 8.4 आता है; यदि जाने को अनदेखा करें तो 7.2।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-144","question":"Pipes A and B can fill a tank in 20 and 30 minutes, and pipe C can empty it in 15 minutes. All three are opened together, and C is closed after 10 minutes. How long does it take to fill the tank in all?","options":["12 minutes","60 minutes","20 minutes","22 minutes"],"answer":2,"explanation":"Tank = 60 units; A + B − C = 3 + 2 − 4 = 1 unit/min, so 10 units in 10 minutes; the other 50 take 50/5 = 10 minutes: 20 in all. 22 forgets the 10 units already filled.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"पाइप A और B एक टंकी को 20 और 30 मिनट में भर सकते हैं, और पाइप C उसे 15 मिनट में खाली कर सकता है। तीनों को साथ खोला जाता है, और 10 मिनट बाद C बंद कर दिया जाता है। टंकी भरने में कुल कितना समय लगता है?","optionsHi":["12 मिनट","60 मिनट","20 मिनट","22 मिनट"],"explanationHi":"टंकी = 60 इकाई; A + B − C = 3 + 2 − 4 = 1 इकाई/मिनट, इसलिए 10 मिनट में 10 इकाई; शेष 50 इकाई में 50/5 = 10 मिनट लगते हैं: कुल 20। 22 पहले भरी जा चुकी 10 इकाई को भूल जाता है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-145","question":"A is 60% more efficient than B. Working together they finish a job in 12 days. How long would A alone take?","options":["31.2 days","19.5 days","7.5 days","24 days"],"answer":1,"explanation":"With B's rate 1, A's is 1.6; the job is 2.6 × 12 = 31.2 B-days, so A needs 31.2/1.6 = 19.5 days. 31.2 days is B's time.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A, B से 60% अधिक कुशल है। साथ काम करते हुए वे किसी कार्य को 12 दिन में पूरा करते हैं। A अकेला कितना समय लेगा?","optionsHi":["31.2 दिन","19.5 दिन","7.5 दिन","24 दिन"],"explanationHi":"B की दर 1 होने पर A की 1.6 है; कार्य = 2.6 × 12 = 31.2 B-दिन, इसलिए A को 31.2/1.6 = 19.5 दिन चाहिए। 31.2 दिन B का समय है।","subtopic":"efficiency"},
  {"id":"quant-time-work-146","question":"24 men working 8 hours a day complete 2/5 of a job in 10 days. How many more men must be employed to finish the rest in 9 days, working 10 hours a day?","options":["8","32","None","24"],"answer":0,"explanation":"2/5 of the job took 1,920 man-hours, so the remaining 3/5 needs 2,880; in 90 hours that is 32 men, i.e. 8 more. Treating the remainder as equal to the part done (1,920 man-hours) wrongly suggests no extra men are needed.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"प्रतिदिन 8 घंटे काम करने वाले 24 आदमी किसी कार्य का 2/5 भाग 10 दिन में पूरा करते हैं। शेष कार्य को प्रतिदिन 10 घंटे काम करके 9 दिन में पूरा करने के लिए कितने और आदमी लगाने होंगे?","optionsHi":["8","32","कोई नहीं","24"],"explanationHi":"2/5 कार्य में 1,920 आदमी-घंटे लगे, इसलिए शेष 3/5 के लिए 2,880 चाहिए; 90 घंटे में यह 32 आदमी होते हैं, यानी 8 और। शेष कार्य को किए गए भाग (1,920 आदमी-घंटे) के बराबर मानने पर गलत निष्कर्ष निकलता है कि और आदमियों की ज़रूरत नहीं है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-147","question":"A can finish a job in 16 days and B in 12 days. They work on alternate days, A on the first day. In how many days is the job finished?","options":["13 5/7 days","6 6/7 days","13 3/4 days","13 2/3 days"],"answer":2,"explanation":"48 units: A does 3, B 4, so each pair of days does 7. After 12 days 42 are done; A's day 13 makes 45 and B needs only 3/4 of day 14: 13 3/4 days. 13 2/3 is the answer if B starts; 13 5/7 treats the work as continuous.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"A किसी कार्य को 16 दिन में और B 12 दिन में कर सकता है। वे एकांतर दिनों में काम करते हैं, पहले दिन A। कार्य कितने दिन में पूरा होता है?","optionsHi":["13 5/7 दिन","6 6/7 दिन","13 3/4 दिन","13 2/3 दिन"],"explanationHi":"48 इकाई: A 3 और B 4 करता है, इसलिए प्रत्येक दो दिन में 7। 12 दिन बाद 42 हो जाते हैं; A का दिन 13 इसे 45 कर देता है और B को दिन 14 का केवल 3/4 भाग चाहिए: 13 3/4 दिन। 13 2/3 तब उत्तर होता जब B शुरू करता; 13 5/7 कार्य को सतत मान लेता है।","subtopic":"alternate-days"},
  {"id":"quant-time-work-148","question":"A can do a job in 10 days and B in 15 days. With C's help they finish it in 4 days and are paid ₹4,500. What is C's share?","options":["₹1,500","₹1,800","₹1,200","₹2,250"],"answer":0,"explanation":"Job = 30 units; in 4 days A does 12 and B 8, so C does 10 and earns 10/30 × 4,500 = ₹1,500. ₹1,800 and ₹1,200 are A’s and B’s shares.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A किसी कार्य को 10 दिन में और B 15 दिन में कर सकता है। C की सहायता से वे उसे 4 दिन में पूरा कर लेते हैं और उन्हें ₹4,500 मिलते हैं। C का हिस्सा कितना है?","optionsHi":["₹1,500","₹1,800","₹1,200","₹2,250"],"explanationHi":"कार्य = 30 इकाई; 4 दिन में A 12 और B 8 करता है, इसलिए C ने 10 किए और उसे 10/30 × 4,500 = ₹1,500 मिलते हैं। ₹1,800 और ₹1,200 क्रमशः A और B के हिस्से हैं।","subtopic":"work-wages"},
  {"id":"quant-time-work-149","question":"A and B together can finish a job in 12 days, B and C in 15 days, and C and A in 20 days. How long will A, B and C take working together?","options":["5 days","10 days","15.67 days","30 days"],"answer":1,"explanation":"Adding the pairs counts each person twice: 2(A + B + C) = 1/12 + 1/15 + 1/20 = 1/5, so A + B + C = 1/10: 10 days. Forgetting to halve gives 5 days; 30 days is A alone.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B साथ मिलकर किसी कार्य को 12 दिन में, B और C 15 दिन में, तथा C और A 20 दिन में पूरा कर सकते हैं। A, B और C साथ काम करने पर कितना समय लेंगे?","optionsHi":["5 दिन","10 दिन","15.67 दिन","30 दिन"],"explanationHi":"जोड़ियों को जोड़ने पर प्रत्येक व्यक्ति दो बार गिना जाता है: 2(A + B + C) = 1/12 + 1/15 + 1/20 = 1/5, इसलिए A + B + C = 1/10: 10 दिन। आधा करना भूलने पर 5 दिन आता है; 30 दिन A अकेले का समय है।","subtopic":"combined-work"},
  {"id":"quant-time-work-150","question":"6 men or 8 women or 12 children can do a job in 24 days. How long will 3 men, 4 women and 6 children take to do it together?","options":["11.08 days","16 days","8 days","12 days"],"answer":1,"explanation":"3 men, 4 women and 6 children are each half of a group that does it in 24 days, so each set does 1/48 a day: together 3/48 = 1/16, i.e. 16 days. Counting all 13 people as men gives 11.08.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"6 पुरुष या 8 महिलाएँ या 12 बच्चे किसी कार्य को 24 दिन में कर सकते हैं। 3 पुरुष, 4 महिलाएँ और 6 बच्चे साथ मिलकर उसे कितने दिन में करेंगे?","optionsHi":["11.08 दिन","16 दिन","8 दिन","12 दिन"],"explanationHi":"3 पुरुष, 4 महिलाएँ और 6 बच्चे प्रत्येक उस समूह का आधा हैं जो कार्य 24 दिन में करता है, इसलिए प्रत्येक समूह प्रतिदिन 1/48 करता है: साथ में 3/48 = 1/16, यानी 16 दिन। सभी 13 व्यक्तियों को पुरुष गिनने पर 11.08 आता है।","subtopic":"men-women-children"},
  {"id":"quant-time-work-151","question":"Pipes A and B fill a tank in 10 and 15 hours. Because of a leak, the two together take 7½ hours. How long would A alone take to fill the tank with the leak still there?","options":["30 hours","15 hours","12.5 hours","17.5 hours"],"answer":1,"explanation":"A + B = 1/6 per hour, but with the leak 1/7.5 = 2/15, so the leak empties 1/30 per hour. A with the leak: 1/10 − 1/30 = 1/15, i.e. 15 hours. 30 hours is the leak alone.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"पाइप A और B एक टंकी को 10 और 15 घंटे में भरते हैं। रिसाव के कारण दोनों मिलकर 7½ घंटे लेते हैं। रिसाव के रहते केवल A टंकी को भरने में कितना समय लेगा?","optionsHi":["30 घंटे","15 घंटे","12.5 घंटे","17.5 घंटे"],"explanationHi":"A + B = प्रति घंटा 1/6, पर रिसाव के साथ 1/7.5 = 2/15, इसलिए रिसाव प्रति घंटा 1/30 खाली करता है। रिसाव के साथ A: 1/10 − 1/30 = 1/15, यानी 15 घंटे। 30 घंटे अकेले रिसाव का समय है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-152","question":"A does 1/3 of a job in 5 days and B does 2/5 of it in 10 days. A works alone for 3 days, and then A and B finish the rest together. How long do they work together?","options":["9.375 days","10.5 days","6 days","7.5 days"],"answer":3,"explanation":"A takes 15 days and B 25. A's 3 days do 1/5; the remaining 4/5 at 1/15 + 1/25 = 8/75 a day takes 7.5 days. 9.375 is the time for the whole job together; 10.5 adds A's 3 days.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A किसी कार्य का 1/3 भाग 5 दिन में और B उसका 2/5 भाग 10 दिन में करता है। A पहले 3 दिन अकेला काम करता है, और फिर A और B मिलकर शेष कार्य पूरा करते हैं। वे साथ कितने दिन काम करते हैं?","optionsHi":["9.375 दिन","10.5 दिन","6 दिन","7.5 दिन"],"explanationHi":"A को 15 दिन और B को 25 दिन लगते हैं। A के 3 दिन 1/5 करते हैं; शेष 4/5 में 1/15 + 1/25 = 8/75 प्रतिदिन की दर से 7.5 दिन लगते हैं। 9.375 पूरे कार्य का साथ में समय है; 10.5 में A के 3 दिन जोड़ दिए गए हैं।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-153","question":"A and B together finish a job in 12 days. A alone would take 10 days less than B alone. How long would B alone take?","options":["20 days","22 days","24 days","30 days"],"answer":3,"explanation":"1/a + 1/(a + 10) = 1/12 gives a² − 14a − 120 = 0, so a = 20 and B takes 30 days. 20 is A's time; 24 is double the joint time, which holds only for equal workers.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B साथ मिलकर किसी कार्य को 12 दिन में पूरा करते हैं। A अकेला B अकेले से 10 दिन कम लेगा। B अकेला कितना समय लेगा?","optionsHi":["20 दिन","22 दिन","24 दिन","30 दिन"],"explanationHi":"1/a + 1/(a + 10) = 1/12 से a² − 14a − 120 = 0, इसलिए a = 20 और B को 30 दिन लगेंगे। 20 A का समय है; 24 संयुक्त समय का दोगुना है, जो केवल बराबर कार्यक्षमता वाले कार्यकर्ताओं के लिए सही होता है।","subtopic":"combined-work"},
  {"id":"quant-time-work-154","question":"16 men can finish a job in 30 days. After 10 days, 4 of them leave. How many more days will the rest take to finish it?","options":["20 days","36 2/3 days","26 2/3 days","15 days"],"answer":2,"explanation":"Left: 16 × 20 = 320 man-days; 12 men need 320/12 = 26 2/3 days. 36 2/3 days is the total time from the start.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"16 आदमी किसी कार्य को 30 दिन में पूरा कर सकते हैं। 10 दिन बाद उनमें से 4 चले जाते हैं। शेष आदमी उसे पूरा करने में और कितने दिन लेंगे?","optionsHi":["20 दिन","36 2/3 दिन","26 2/3 दिन","15 दिन"],"explanationHi":"शेष: 16 × 20 = 320 आदमी-दिन; 12 आदमियों को 320/12 = 26 2/3 दिन चाहिए। 36 2/3 दिन शुरुआत से कुल समय है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-155","question":"Pipe A fills a tank in 4 hours and pipe B empties it in 6 hours. Starting with A, they are opened alternately for one hour each. When is the empty tank first full?","options":["After 19 hours","After 24 hours","After 12 hours","After 18 hours"],"answer":0,"explanation":"Tank = 12 units: A adds 3, B removes 2, so each 2-hour cycle gains 1. After 18 hours the level is 9, and A's next hour fills it: 19 hours. 24 hours assumes the gain of 1 per cycle continues to the end.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"पाइप A एक टंकी को 4 घंटे में भरता है और पाइप B उसे 6 घंटे में खाली करता है। A से शुरू करके उन्हें एक-एक घंटे के लिए एकांतर रूप से खोला जाता है। खाली टंकी पहली बार कब भरती है?","optionsHi":["19 घंटे बाद","24 घंटे बाद","12 घंटे बाद","18 घंटे बाद"],"explanationHi":"टंकी = 12 इकाई: A 3 जोड़ता है, B 2 निकालता है, इसलिए प्रत्येक 2 घंटे के चक्र में 1 का लाभ होता है। 18 घंटे बाद स्तर 9 होता है, और A का अगला घंटा उसे भर देता है: 19 घंटे। 24 घंटे यह मानता है कि प्रति चक्र 1 का लाभ अंत तक चलता रहता है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-156","question":"A and B together can finish a job in 20 days. After they work together for 8 days, B leaves and A finishes the rest in 18 days. How long would A alone take for the whole job?","options":["60 days","18 days","45 days","30 days"],"answer":3,"explanation":"In 8 days they do 8/20 = 2/5, so A does the remaining 3/5 in 18 days and needs 30 days for all of it. Treating 2/5 as what A did gives 45; 60 days is B's time.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B साथ मिलकर किसी कार्य को 20 दिन में पूरा कर सकते हैं। 8 दिन साथ काम करने के बाद B चला जाता है और A शेष कार्य 18 दिन में पूरा करता है। A अकेला पूरे कार्य में कितना समय लेगा?","optionsHi":["60 दिन","18 दिन","45 दिन","30 दिन"],"explanationHi":"8 दिन में वे 8/20 = 2/5 करते हैं, इसलिए A शेष 3/5 को 18 दिन में करता है और पूरे के लिए उसे 30 दिन चाहिए। 2/5 को A का किया हुआ मानने पर 45 आता है; 60 दिन B का समय है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-157","question":"A completes 30% of a job in 6 days. B is 25% less efficient than A, and C is as efficient as A and B together. How long will B and C take together to finish the whole job?","options":["7.69 days","11.43 days","8 days","26.67 days"],"answer":2,"explanation":"A's rate is 1/20, B's 3/80 and C's 7/80, so B + C = 10/80 = 1/8: 8 days. Reading '25% less efficient' as '25% more time' (25 days) gives 7.69 days.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"A किसी कार्य का 30% भाग 6 दिन में पूरा करता है। B, A से 25% कम कुशल है, और C, A और B के संयुक्त जितना कुशल है। B और C साथ मिलकर पूरा कार्य कितने दिन में करेंगे?","optionsHi":["7.69 दिन","11.43 दिन","8 दिन","26.67 दिन"],"explanationHi":"A की दर 1/20, B की 3/80 और C की 7/80 है, इसलिए B + C = 10/80 = 1/8: 8 दिन। '25% कम कुशल' को '25% अधिक समय' (25 दिन) पढ़ने पर 7.69 दिन आता है।","subtopic":"efficiency"},
  {"id":"quant-time-work-158","question":"15 workers can build a wall in 48 hours. After 18 hours, 9 more workers join them. How long does the wall take in all?","options":["30 hours","18.75 hours","36.75 hours","48 hours"],"answer":2,"explanation":"Total 720 worker-hours; 270 are done in 18 hours, and the remaining 450 take 450/24 = 18.75 hours: 36.75 in all. 30 hours assumes all 24 worked from the start; 18.75 is only the second stretch.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"15 कर्मचारी एक दीवार 48 घंटे में बना सकते हैं। 18 घंटे बाद 9 और कर्मचारी उनके साथ जुड़ जाते हैं। दीवार बनने में कुल कितना समय लगता है?","optionsHi":["30 घंटे","18.75 घंटे","36.75 घंटे","48 घंटे"],"explanationHi":"कुल 720 कर्मचारी-घंटे; 18 घंटे में 270 हो चुके हैं, और शेष 450 में 450/24 = 18.75 घंटे लगते हैं: कुल 36.75। 30 घंटे मानता है कि सभी 24 शुरू से काम करते थे; 18.75 केवल दूसरा चरण है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-159","question":"Pipes A and B fill a cistern in 12 and 15 hours, and pipe C can empty it. With all three open, the cistern fills in 20 hours. How long would C alone take to empty the full cistern?","options":["5 hours","10 hours","20 hours","6.67 hours"],"answer":1,"explanation":"1/12 + 1/15 − 1/C = 1/20 gives 1/C = 9/60 − 3/60 = 1/10, so 10 hours. Adding all three rates gives 5 hours; 6.67 hours is A and B together.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"पाइप A और B एक हौज को 12 और 15 घंटे में भरते हैं, और पाइप C उसे खाली कर सकता है। तीनों खुले होने पर हौज 20 घंटे में भरता है। C अकेला भरे हौज को कितने समय में खाली करेगा?","optionsHi":["5 घंटे","10 घंटे","20 घंटे","6.67 घंटे"],"explanationHi":"1/12 + 1/15 − 1/C = 1/20 से 1/C = 9/60 − 3/60 = 1/10, इसलिए 10 घंटे। तीनों दरें जोड़ने पर 5 घंटे आता है; 6.67 घंटे A और B का संयुक्त समय है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-160","question":"A, B and C can do a job alone in 20, 30 and 60 days. A works every day, B joins him on every second day (days 2, 4, 6, …) and C on every third day (days 3, 6, 9, …). On which day is the job finished?","options":["Day 14","Day 15","Day 12","Day 13"],"answer":0,"explanation":"60 units: A 3, B 2, C 1 a day. A 6-day cycle gives 18 + 6 + 2 = 26, so 52 after 12 days; day 13 (A alone) makes 55 and day 14 (A + B) makes 60. Spreading the cycle evenly (60/26 × 6 ≈ 13.85) suggests day 13 wrongly.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A, B और C किसी कार्य को अकेले क्रमशः 20, 30 और 60 दिन में कर सकते हैं। A प्रतिदिन काम करता है, B हर दूसरे दिन (दिन 2, 4, 6, …) और C हर तीसरे दिन (दिन 3, 6, 9, …) उसके साथ जुड़ता है। कार्य किस दिन पूरा होता है?","optionsHi":["दिन 14","दिन 15","दिन 12","दिन 13"],"explanationHi":"60 इकाई: A 3, B 2, C 1 प्रतिदिन। 6 दिन के चक्र में 18 + 6 + 2 = 26, इसलिए 12 दिन बाद 52; दिन 13 (केवल A) से 55 और दिन 14 (A + B) से 60। चक्र को समान रूप से फैलाने (60/26 × 6 ≈ 13.85) से गलत ढंग से दिन 13 का सुझाव मिलता है।","subtopic":"alternate-days"},
  {"id":"quant-time-work-161","question":"A can do a job in 9 days, and B is 50% more efficient than A. B starts alone; after 2 days A joins and they finish together. Out of a wage of ₹1,800 paid for the work done, what is B's share?","options":["₹1,080","₹480","₹1,200","₹1,320"],"answer":3,"explanation":"Job = 18 units: A 2, B 3 a day. B's 2 days do 6; the other 12 take 12/5 = 2.4 days. B does 6 + 7.2 = 13.2 units and earns 13.2/18 × 1,800 = ₹1,320. ₹1,080 splits in the efficiency ratio 3 : 2, ignoring B's extra days.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A किसी कार्य को 9 दिन में कर सकता है, और B, A से 50% अधिक कुशल है। B अकेला शुरू करता है; 2 दिन बाद A जुड़ता है और वे साथ मिलकर कार्य पूरा करते हैं। किए गए कार्य के लिए दी गई ₹1,800 की मजदूरी में B का हिस्सा कितना है?","optionsHi":["₹1,080","₹480","₹1,200","₹1,320"],"explanationHi":"कार्य = 18 इकाई: A प्रतिदिन 2 और B 3 करता है। B के 2 दिन 6 करते हैं; शेष 12 में 12/5 = 2.4 दिन लगते हैं। B कुल 6 + 7.2 = 13.2 इकाई करता है और 13.2/18 × 1,800 = ₹1,320 पाता है। ₹1,080 कार्यक्षमता के अनुपात 3 : 2 में बाँटना है, जो B के अतिरिक्त दिनों को अनदेखा करता है।","subtopic":"work-wages"},
  {"id":"quant-time-work-162","question":"A contractor hires 40 men to finish a job in 60 days. After 20 days only one-fourth of the job is done. How many extra men must he hire to finish on time?","options":["60","80","40","20"],"answer":3,"explanation":"One-fourth took 800 man-days, so the job is 3,200; the remaining 2,400 in 40 days needs 60 men, i.e. 20 extra. 60 is the total required; 80 extra comes from tripling the workforce without allowing for the 40 remaining days.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक ठेकेदार किसी कार्य को 60 दिन में पूरा करने के लिए 40 आदमी लगाता है। 20 दिन बाद कार्य का केवल एक-चौथाई भाग हुआ है। समय पर पूरा करने के लिए उसे कितने अतिरिक्त आदमी लगाने होंगे?","optionsHi":["60","80","40","20"],"explanationHi":"एक-चौथाई में 800 आदमी-दिन लगे, इसलिए पूरा कार्य 3,200 है; शेष 2,400 को 40 दिन में पूरा करने के लिए 60 आदमी चाहिए, यानी 20 अतिरिक्त। 60 कुल आवश्यक संख्या है; 80 अतिरिक्त बचे 40 दिनों का ध्यान रखे बिना कार्यबल को तिगुना करने से आता है।","subtopic":"leaving-joining"},
  {"id":"quant-time-work-163","question":"A does one-fourth of a job in 5 days and B does one-fifth of it in 6 days. How long will they take to finish the whole job together?","options":["12 days","25 days","11 days","50 days"],"answer":0,"explanation":"A needs 20 days and B 30, so together 1/20 + 1/30 = 1/12: 12 days. 25 days is the average of 20 and 30; 50 days adds them.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A किसी कार्य का एक-चौथाई भाग 5 दिन में और B उसका एक-पाँचवाँ भाग 6 दिन में करता है। दोनों साथ मिलकर पूरा कार्य कितने दिन में करेंगे?","optionsHi":["12 दिन","25 दिन","11 दिन","50 दिन"],"explanationHi":"A को 20 दिन और B को 30 दिन चाहिए, इसलिए साथ में 1/20 + 1/30 = 1/12: 12 दिन। 25 दिन 20 और 30 का औसत है; 50 दिन उन्हें जोड़ना है।","subtopic":"combined-work"},
  {"id":"quant-time-work-164","question":"Pipe A fills water at 60 litres per minute. With both A and an outlet pipe B open, a 1,200-litre tank fills in 50 minutes. How long would B alone take to empty the full tank?","options":["33 1/3 minutes","20 minutes","50 minutes","14 2/7 minutes"],"answer":0,"explanation":"Net inflow = 1,200/50 = 24 L/min, so B removes 60 − 24 = 36 L/min and empties 1,200 L in 33 1/3 minutes. Adding 60 + 24 gives 14 2/7 minutes; 20 minutes is A alone filling.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"पाइप A 60 लीटर प्रति मिनट की दर से पानी भरता है। A और एक निकास पाइप B दोनों खुले होने पर 1,200 लीटर की टंकी 50 मिनट में भरती है। B अकेला भरी टंकी को कितने समय में खाली करेगा?","optionsHi":["33 1/3 मिनट","20 मिनट","50 मिनट","14 2/7 मिनट"],"explanationHi":"शुद्ध अंतर्वाह = 1,200/50 = 24 L/min, इसलिए B 60 − 24 = 36 L/min निकालता है और 1,200 L को 33 1/3 मिनट में खाली करता है। 60 + 24 जोड़ने पर 14 2/7 मिनट आता है; 20 मिनट अकेले A के भरने का समय है।","subtopic":"pipes-cisterns"},
  {"id":"quant-time-work-165","question":"If A works for 6 days and B for 4 days, 13/30 of a job is done; if A works for 4 days and B for 6 days, 2/5 of it is done. How long will A and B take together to do the whole job?","options":["20 days","12 days","30 days","25 days"],"answer":1,"explanation":"Solving 6x + 4y = 13/30 and 4x + 6y = 2/5 gives x = 1/20 and y = 1/30, so together 1/12: 12 days. 20 and 30 are A's and B's times alone; 25 averages them.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि A 6 दिन और B 4 दिन काम करे, तो कार्य का 13/30 भाग होता है; यदि A 4 दिन और B 6 दिन काम करे, तो उसका 2/5 भाग होता है। A और B साथ मिलकर पूरा कार्य कितने दिन में करेंगे?","optionsHi":["20 दिन","12 दिन","30 दिन","25 दिन"],"explanationHi":"6x + 4y = 13/30 और 4x + 6y = 2/5 हल करने पर x = 1/20 और y = 1/30, इसलिए साथ में 1/12: 12 दिन। 20 और 30 क्रमशः A और B के अकेले के समय हैं; 25 उनका औसत है।","subtopic":"combined-work"},
  {"id":"quant-time-work-166","question":"A, B and C together finish a job in 4 days. A is twice as efficient as B, and B is twice as efficient as C. How long would C alone take?","options":["12 days","16 days","28 days","7 days"],"answer":2,"explanation":"Efficiencies 4 : 2 : 1 sum to 7, so C does 1/7 of the job's daily progress: 4 × 7 = 28 days. 7 days is A alone; 12 days treats all three as equally efficient.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A, B और C साथ मिलकर किसी कार्य को 4 दिन में पूरा करते हैं। A, B से दोगुना कुशल है, और B, C से दोगुना कुशल है। C अकेला कितना समय लेगा?","optionsHi":["12 दिन","16 दिन","28 दिन","7 दिन"],"explanationHi":"कार्यक्षमताएँ 4 : 2 : 1 का योग 7 है, इसलिए C प्रतिदिन की प्रगति का 1/7 करता है: 4 × 7 = 28 दिन। 7 दिन A अकेले का समय है; 12 दिन तीनों को समान कुशल मानना है।","subtopic":"efficiency"},
  {"id":"quant-time-work-167","question":"A can complete a job in 12 days and B in 18 days. They work on alternate days, A working on the first day. In how many days is the job finished?","options":["14 days","15 days","14⅔ days","14⅓ days"],"answer":3,"explanation":"In 2 days they do 1/12 + 1/18 = 5/36, so 7 pairs (14 days) finish 35/36. On day 15 A needs only 1/36 ÷ 1/12 = 1/3 of a day, so the total is 14⅓ days.","difficulty":"hard","questionHi":"A किसी कार्य को 12 दिन में और B 18 दिन में पूरा कर सकता है। वे एक-एक दिन छोड़कर बारी-बारी से कार्य करते हैं और पहले दिन A कार्य करता है। कार्य कितने दिन में पूरा होगा?","optionsHi":["14 दिन","15 दिन","14⅔ दिन","14⅓ दिन"],"explanationHi":"2 दिन में वे 1/12 + 1/18 = 5/36 कार्य करते हैं, अतः 7 जोड़ी (14 दिन) में 35/36 कार्य पूरा होता है। 15वें दिन A को शेष 1/36 ÷ 1/12 = 1/3 दिन ही लगेगा, इसलिए कुल समय 14⅓ दिन है।","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-168","question":"A can do a piece of work in 15 days and B in 20 days. They work on alternate days, A starting. How many days does the work take?","options":["17 days","16 days","18 days","17½ days"],"answer":0,"explanation":"A pair of days gives 1/15 + 1/20 = 7/60, so 8 pairs (16 days) give 56/60. The remaining 4/60 = 1/15 is exactly A's day-17 work, so the job ends on day 17.","difficulty":"hard","questionHi":"A किसी कार्य को 15 दिन में और B 20 दिन में कर सकता है। वे एक-एक दिन छोड़कर बारी-बारी से कार्य करते हैं और A शुरू करता है। कार्य में कितने दिन लगेंगे?","optionsHi":["17 दिन","16 दिन","18 दिन","17½ दिन"],"explanationHi":"दो दिन की जोड़ी में 1/15 + 1/20 = 7/60 कार्य होता है, अतः 8 जोड़ी (16 दिन) में 56/60। शेष 4/60 = 1/15 ठीक A के 17वें दिन का कार्य है, इसलिए कार्य 17वें दिन पूरा होता है।","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-169","question":"A, B and C can finish a job alone in 12, 16 and 24 days respectively. They work in turn, one day each, in the order A, B, C, A, B, C, … How many days does the job take?","options":["16 days","15½ days","15¾ days","15⅔ days"],"answer":2,"explanation":"In 3 days they do (4 + 3 + 2)/48 = 9/48, so 5 rounds (15 days) finish 45/48. The last 3/48 is done by A on day 16 in (3/48) ÷ (4/48) = 3/4 day, so the total is 15¾ days.","difficulty":"very-hard","questionHi":"A, B और C अकेले किसी कार्य को क्रमशः 12, 16 और 24 दिन में पूरा कर सकते हैं। वे एक-एक दिन बारी-बारी से, A, B, C, A, B, C, … के क्रम में कार्य करते हैं। कार्य में कितने दिन लगेंगे?","optionsHi":["16 दिन","15½ दिन","15¾ दिन","15⅔ दिन"],"explanationHi":"3 दिन में वे (4 + 3 + 2)/48 = 9/48 कार्य करते हैं, अतः 5 चक्र (15 दिन) में 45/48 पूरा होता है। शेष 3/48 कार्य A 16वें दिन (3/48) ÷ (4/48) = 3/4 दिन में कर देता है, इसलिए कुल समय 15¾ दिन है।","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-170","question":"A alone can finish a job in 20 days. A and B working on alternate days, A starting, finish it in 19 days. In how many days can B alone finish the job?","options":["15 days","24 days","18 days","16 days"],"answer":2,"explanation":"In 19 days A works 10 days and B works 9. So 10/20 + 9/x = 1 gives 9/x = 1/2 and x = 18 days.","difficulty":"very-hard","questionHi":"A अकेला किसी कार्य को 20 दिन में पूरा कर सकता है। A और B एक-एक दिन छोड़कर कार्य करते हैं, A शुरू करता है, और कार्य 19 दिन में पूरा कर लेते हैं। B अकेला उसे कितने दिन में पूरा करेगा?","optionsHi":["15 दिन","24 दिन","18 दिन","16 दिन"],"explanationHi":"19 दिन में A ने 10 दिन और B ने 9 दिन कार्य किया। अतः 10/20 + 9/x = 1 से 9/x = 1/2 और x = 18 दिन।","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-171","question":"A job is equal to the work of 8 men in 15 days. One man starts the job, and every following day one more man joins (2 men on day 2, 3 men on day 3, and so on). How many days does the job take?","options":["15 days","8 days","16 days","14 days"],"answer":0,"explanation":"Total work = 8 × 15 = 120 man-days. After n days the work done is n(n + 1)/2, and 15 × 16/2 = 120, so n = 15 days.","difficulty":"moderate","questionHi":"एक कार्य 8 आदमियों द्वारा 15 दिन में किए जाने वाले कार्य के बराबर है। एक आदमी कार्य शुरू करता है और अगले प्रत्येक दिन एक आदमी और जुड़ता जाता है (दूसरे दिन 2 आदमी, तीसरे दिन 3 आदमी, इत्यादि)। कार्य में कितने दिन लगेंगे?","optionsHi":["15 दिन","8 दिन","16 दिन","14 दिन"],"explanationHi":"कुल कार्य = 8 × 15 = 120 आदमी-दिन। n दिन में किया गया कार्य n(n + 1)/2 है, और 15 × 16/2 = 120, अतः n = 15 दिन।","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-172","question":"A can do a job in 8 days and B in 12 days. They work on alternate days, A on the first day. How many days does the job take?","options":["9⅔ days","10 days","9 days","9½ days"],"answer":3,"explanation":"Two days give 1/8 + 1/12 = 5/24, so 4 pairs (8 days) give 20/24. Day 9 (A) adds 3/24, leaving 1/24, which B does on day 10 in (1/24) ÷ (2/24) = 1/2 day, so the total is 9½ days. (If B had started it would be 9⅔.)","difficulty":"hard","questionHi":"A किसी कार्य को 8 दिन में और B 12 दिन में कर सकता है। वे एक-एक दिन छोड़कर कार्य करते हैं और पहले दिन A कार्य करता है। कार्य में कितने दिन लगेंगे?","optionsHi":["9⅔ दिन","10 दिन","9 दिन","9½ दिन"],"explanationHi":"दो दिन में 1/8 + 1/12 = 5/24 कार्य होता है, अतः 4 जोड़ी (8 दिन) में 20/24। 9वें दिन (A) 3/24 और होता है, शेष 1/24 कार्य B 10वें दिन (1/24) ÷ (2/24) = 1/2 दिन में करता है, इसलिए कुल 9½ दिन। (यदि B शुरू करता तो 9⅔ दिन लगते।)","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-173","question":"A can finish a job in 28 days and B in 42 days. They work in turns of 3 days each, A first, then B, then A, and so on. In how many days is the job finished?","options":["36 days","33 days","30 days","34 days"],"answer":1,"explanation":"One round of 6 days gives 3/28 + 3/42 = 5/28, so 5 rounds (30 days) give 25/28. The remaining 3/28 is exactly A's next 3 days of work, so the job ends on day 33.","difficulty":"very-hard","questionHi":"A किसी कार्य को 28 दिन में और B 42 दिन में पूरा कर सकता है। वे 3-3 दिन की बारी में कार्य करते हैं, पहले A, फिर B, फिर A, और इसी क्रम में। कार्य कितने दिन में पूरा होगा?","optionsHi":["36 दिन","33 दिन","30 दिन","34 दिन"],"explanationHi":"6 दिन के एक चक्र में 3/28 + 3/42 = 5/28 कार्य होता है, अतः 5 चक्र (30 दिन) में 25/28। शेष 3/28 कार्य ठीक A के अगले 3 दिनों का है, इसलिए कार्य 33वें दिन पूरा होता है।","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-174","question":"X can finish a job in 10 days and Y in 15 days. They work on alternate days, starting with Y. In how many days is the job finished?","options":["11 days","12 days","12½ days","13 days"],"answer":1,"explanation":"Two days give 1/10 + 1/15 = 1/6, so exactly 6 pairs finish the job in 12 days. Because the work ends at the end of a full pair, who starts does not matter.","difficulty":"hard","questionHi":"X किसी कार्य को 10 दिन में और Y 15 दिन में पूरा कर सकता है। वे एक-एक दिन छोड़कर कार्य करते हैं और Y से शुरुआत होती है। कार्य कितने दिन में पूरा होगा?","optionsHi":["11 दिन","12 दिन","12½ दिन","13 दिन"],"explanationHi":"दो दिन में 1/10 + 1/15 = 1/6 कार्य होता है, अतः ठीक 6 जोड़ी में 12 दिन में कार्य पूरा हो जाता है। कार्य पूरी जोड़ी के अंत में समाप्त होता है, इसलिए कौन शुरू करता है इसका कोई प्रभाव नहीं पड़ता।","subtopic":"alternate-days","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-175","question":"A, B and C can do a job in 12, 15 and 20 days. They start together, but C leaves 2 days before the work is finished. The wages are shared in proportion to work done. What does C get out of a total of ₹6,000?","options":["₹1,200","₹900","₹1,250","₹1,050"],"answer":3,"explanation":"Let the job take T days: T/12 + T/15 + (T − 2)/20 = 1 gives T = 5.5. Work shares are A 55/120, B 44/120 and C 3.5/20 = 21/120, so C gets 21/120 × 6,000 = ₹1,050. ₹1,200 assumes C stayed to the end.","difficulty":"very-hard","questionHi":"A, B और C किसी कार्य को क्रमशः 12, 15 और 20 दिन में कर सकते हैं। वे साथ-साथ शुरू करते हैं, किंतु कार्य पूरा होने से 2 दिन पहले C चला जाता है। मजदूरी किए गए कार्य के अनुपात में बाँटी जाती है। कुल ₹6,000 में से C को कितना मिलेगा?","optionsHi":["₹1,200","₹900","₹1,250","₹1,050"],"explanationHi":"कार्य में T दिन लगें: T/12 + T/15 + (T − 2)/20 = 1 से T = 5.5। कार्य के भाग A का 55/120, B का 44/120 और C का 3.5/20 = 21/120 है, अतः C को 21/120 × 6,000 = ₹1,050 मिलेंगे। ₹1,200 तब आता जब C अंत तक रुकता।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-176","question":"A and B can do a job in 12 and 18 days. With C's help the three finish it in 4 days. If they are paid ₹2,700 for the job, how much does C get?","options":["₹1,200","₹900","₹1,350","₹1,000"],"answer":0,"explanation":"Together the rate is 1/4 = 9/36. A and B give 3/36 + 2/36, so C gives 4/36. Wages go by work done, 3 : 2 : 4, so C gets 4/9 × 2,700 = ₹1,200.","difficulty":"hard","questionHi":"A और B किसी कार्य को 12 और 18 दिन में कर सकते हैं। C की सहायता से तीनों उसे 4 दिन में पूरा कर लेते हैं। यदि कार्य के लिए उन्हें ₹2,700 मिलते हैं, तो C को कितना मिलेगा?","optionsHi":["₹1,200","₹900","₹1,350","₹1,000"],"explanationHi":"तीनों की संयुक्त दर 1/4 = 9/36 है। A और B की दर 3/36 + 2/36 है, अतः C की दर 4/36। मजदूरी किए गए कार्य के अनुपात 3 : 2 : 4 में बँटेगी, इसलिए C को 4/9 × 2,700 = ₹1,200 मिलेंगे।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-177","question":"A skilled worker is 50% more efficient than an unskilled worker and is paid 50% more per day. For the same job, how does the labour cost using only skilled workers compare with that using only unskilled workers?","options":["Skilled workers cost 12.5% more","Skilled workers cost 25% more","The two costs are equal","Skilled workers cost 25% less"],"answer":2,"explanation":"Let unskilled efficiency be 2 and pay 2; skilled efficiency 3 and pay 3. For a job of 6 units, skilled need 2 days × pay 3 = 6, unskilled need 3 days × pay 2 = 6. The costs are equal.","difficulty":"hard","questionHi":"एक कुशल मजदूर, अकुशल मजदूर से 50% अधिक कार्यकुशल है और उसे प्रतिदिन 50% अधिक मजदूरी मिलती है। एक ही कार्य के लिए केवल कुशल मजदूरों को लगाने की श्रम लागत केवल अकुशल मजदूरों की लागत से कैसी है?","optionsHi":["कुशल मजदूरों की लागत 12.5% अधिक है","कुशल मजदूरों की लागत 25% अधिक है","दोनों लागतें बराबर हैं","कुशल मजदूरों की लागत 25% कम है"],"explanationHi":"अकुशल की कार्यकुशलता 2 और मजदूरी 2 लें; कुशल की कार्यकुशलता 3 और मजदूरी 3। 6 इकाई के कार्य के लिए कुशल को 2 दिन × 3 = 6 और अकुशल को 3 दिन × 2 = 6 लगते हैं। दोनों लागतें बराबर हैं।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-178","question":"A job is done by three persons for ₹7,200. A does 1/3 of the work, B does 1/4 of what then remains, and C does the rest. Wages go by work done. What is the difference between the largest and the smallest share?","options":["₹1,200","₹2,000","₹2,400","₹3,600"],"answer":2,"explanation":"A does 1/3; B does 1/4 × 2/3 = 1/6; C does 1 − 1/3 − 1/6 = 1/2. Shares are 2400 : 1200 : 3600, so the difference between the largest (C) and the smallest (B) is 3,600 − 1,200 = ₹2,400.","difficulty":"hard","questionHi":"तीन व्यक्ति एक कार्य ₹7,200 में करते हैं। A कार्य का 1/3 भाग करता है, B उसके बाद बचे कार्य का 1/4 भाग करता है और C शेष कार्य करता है। मजदूरी किए गए कार्य के अनुपात में बँटती है। सबसे बड़े और सबसे छोटे हिस्से का अंतर कितना है?","optionsHi":["₹1,200","₹2,000","₹2,400","₹3,600"],"explanationHi":"A, 1/3 कार्य करता है; B, 1/4 × 2/3 = 1/6 करता है; C, 1 − 1/3 − 1/6 = 1/2 करता है। हिस्से 2,400 : 1,200 : 3,600 हैं, अतः सबसे बड़े (C) और सबसे छोटे (B) हिस्से का अंतर 3,600 − 1,200 = ₹2,400 है।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-179","question":"A and B can do a job alone in 20 and 30 days. They start together, but A leaves 5 days before the job is finished. If the total wage is ₹5,000 and is shared by work done, how much does A get?","options":["₹2,500","₹2,000","₹3,000","₹2,250"],"answer":0,"explanation":"If the job takes T days, T/30 + (T − 5)/20 = 1 gives T = 15. A works 10 days = 10/20 = 1/2 of the job and B works 15 days = 15/30 = 1/2, so the wages are equal: ₹2,500 each.","difficulty":"hard","questionHi":"A और B किसी कार्य को अकेले क्रमशः 20 और 30 दिन में कर सकते हैं। वे साथ-साथ शुरू करते हैं, किंतु कार्य पूरा होने से 5 दिन पहले A चला जाता है। यदि कुल मजदूरी ₹5,000 है और किए गए कार्य के अनुपात में बँटती है, तो A को कितना मिलेगा?","optionsHi":["₹2,500","₹2,000","₹3,000","₹2,250"],"explanationHi":"यदि कार्य में T दिन लगें, तो T/30 + (T − 5)/20 = 1 से T = 15। A ने 10 दिन यानी 10/20 = 1/2 कार्य किया और B ने 15 दिन यानी 15/30 = 1/2 कार्य किया, इसलिए मजदूरी बराबर है: प्रत्येक को ₹2,500।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-180","question":"A man's daily wage is 25% more than a woman's. A contractor pays ₹35,200 in all for 8 men working 10 days and 10 women working 12 days. What is a man's daily wage?","options":["₹160","₹175","₹250","₹200"],"answer":3,"explanation":"Let a woman's wage be w, so a man's is 1.25w. Total = 8 × 10 × 1.25w + 10 × 12 × w = 100w + 120w = 220w = 35,200, so w = 160 and a man earns 1.25 × 160 = ₹200.","difficulty":"hard","questionHi":"एक पुरुष की दैनिक मजदूरी एक महिला की दैनिक मजदूरी से 25% अधिक है। एक ठेकेदार 10 दिन कार्य करने वाले 8 पुरुषों और 12 दिन कार्य करने वाली 10 महिलाओं को कुल ₹35,200 देता है। एक पुरुष की दैनिक मजदूरी कितनी है?","optionsHi":["₹160","₹175","₹250","₹200"],"explanationHi":"महिला की मजदूरी w लें, तो पुरुष की 1.25w होगी। कुल = 8 × 10 × 1.25w + 10 × 12 × w = 100w + 120w = 220w = 35,200, अतः w = 160 और पुरुष की मजदूरी 1.25 × 160 = ₹200।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-181","question":"A and B together finish a job in 5 days and are paid ₹9,000. A alone could finish it in 8 days. How much should B get?","options":["₹5,625","₹3,375","₹3,600","₹4,500"],"answer":1,"explanation":"B's rate = 1/5 − 1/8 = 3/40 and A's = 5/40, so work and wages split 5 : 3. B gets 3/8 × 9,000 = ₹3,375; ₹5,625 is A's share.","difficulty":"moderate","questionHi":"A और B मिलकर एक कार्य 5 दिन में पूरा करते हैं और उन्हें ₹9,000 मिलते हैं। A अकेला उसे 8 दिन में पूरा कर सकता है। B को कितना मिलना चाहिए?","optionsHi":["₹5,625","₹3,375","₹3,600","₹4,500"],"explanationHi":"B की दर = 1/5 − 1/8 = 3/40 और A की = 5/40, अतः कार्य और मजदूरी 5 : 3 में बँटते हैं। B को 3/8 × 9,000 = ₹3,375 मिलेंगे; ₹5,625 A का हिस्सा है।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-182","question":"A, B and C can do a job alone in 10, 15 and 30 days. All start together; A leaves after 3 days and B leaves 2 days after that, and C finishes the rest. If the wages of ₹9,000 are shared by work done, how much does C get?","options":["₹3,000","₹3,300","₹3,600","₹2,700"],"answer":1,"explanation":"First 3 days: 3 × (1/5) = 3/5; next 2 days (B, C): 2 × 1/10 = 1/5, so 4/5 is done and C alone finishes 1/5 in 6 days. C works 3 + 2 + 6 = 11 days = 11/30 of the job (A did 9/30, B 10/30), so C gets 11/30 × 9,000 = ₹3,300.","difficulty":"very-hard","questionHi":"A, B और C किसी कार्य को अकेले क्रमशः 10, 15 और 30 दिन में कर सकते हैं। तीनों साथ शुरू करते हैं; 3 दिन बाद A चला जाता है और उसके 2 दिन बाद B चला जाता है तथा शेष कार्य C पूरा करता है। यदि ₹9,000 की मजदूरी किए गए कार्य के अनुपात में बँटती है, तो C को कितना मिलेगा?","optionsHi":["₹3,000","₹3,300","₹3,600","₹2,700"],"explanationHi":"पहले 3 दिन: 3 × (1/5) = 3/5; अगले 2 दिन (B, C): 2 × 1/10 = 1/5, अतः 4/5 पूरा हुआ और शेष 1/5 C अकेला 6 दिन में करता है। C ने 3 + 2 + 6 = 11 दिन यानी कार्य का 11/30 भाग किया (A ने 9/30, B ने 10/30), इसलिए C को 11/30 × 9,000 = ₹3,300 मिलेंगे।","subtopic":"work-wages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-183","question":"A is 25% more efficient than B. If B alone can finish a job in 45 days, in how many days can A and B together finish it?","options":["18 days","22½ days","24 days","20 days"],"answer":3,"explanation":"A takes 45 ÷ 1.25 = 36 days. Together, 1/45 + 1/36 = 9/180 = 1/20, so the job takes 20 days.","difficulty":"moderate","questionHi":"A, B से 25% अधिक कार्यकुशल है। यदि B अकेला किसी कार्य को 45 दिन में पूरा कर सकता है, तो A और B मिलकर उसे कितने दिन में पूरा करेंगे?","optionsHi":["18 दिन","22½ दिन","24 दिन","20 दिन"],"explanationHi":"A को 45 ÷ 1.25 = 36 दिन लगते हैं। साथ मिलकर 1/45 + 1/36 = 9/180 = 1/20, अतः कार्य में 20 दिन लगेंगे।","subtopic":"efficiency","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-184","question":"The efficiencies of A, B and C are in the ratio 5 : 4 : 3, and together they finish a job in 14 days. In how many days can B and C together finish it?","options":["24 days","21 days","18 days","28 days"],"answer":0,"explanation":"Together they do 12 units a day, so the job is 12 × 14 = 168 units. B and C do 4 + 3 = 7 units a day, so they need 168/7 = 24 days.","difficulty":"moderate","questionHi":"A, B और C की कार्यकुशलता का अनुपात 5 : 4 : 3 है और वे तीनों मिलकर किसी कार्य को 14 दिन में पूरा करते हैं। B और C मिलकर उसे कितने दिन में पूरा करेंगे?","optionsHi":["24 दिन","21 दिन","18 दिन","28 दिन"],"explanationHi":"तीनों मिलकर प्रतिदिन 12 इकाई करते हैं, अतः कार्य 12 × 14 = 168 इकाई का है। B और C प्रतिदिन 4 + 3 = 7 इकाई करते हैं, इसलिए उन्हें 168/7 = 24 दिन लगेंगे।","subtopic":"efficiency","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-185","question":"A is three times as efficient as B, and A takes 18 days less than B to finish a job alone. In how many days can they finish it working together?","options":["6 days","7½ days","6¾ days","9 days"],"answer":2,"explanation":"A takes one-third of B's time: B = x, A = x/3, and x − x/3 = 18 gives x = 27, so A = 9 days. Together, 1/9 + 1/27 = 4/27, so the time is 27/4 = 6¾ days.","difficulty":"hard","questionHi":"A, B से तीन गुना कार्यकुशल है और अकेले कार्य पूरा करने में A को B से 18 दिन कम लगते हैं। साथ मिलकर कार्य करने पर वे उसे कितने दिन में पूरा करेंगे?","optionsHi":["6 दिन","7½ दिन","6¾ दिन","9 दिन"],"explanationHi":"A को B का एक-तिहाई समय लगता है: B = x, A = x/3 और x − x/3 = 18 से x = 27, अतः A = 9 दिन। साथ में 1/9 + 1/27 = 4/27, इसलिए समय 27/4 = 6¾ दिन।","subtopic":"efficiency","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-186","question":"A is 50% more efficient than B, and B is twice as efficient as C. If C alone takes 36 days to finish a job, in how many days can A and B together finish it?","options":["6 days","8 days","7.2 days","7.5 days"],"answer":2,"explanation":"Take C = 1 unit/day, so B = 2 and A = 3 units/day, and the job is 36 units. A and B do 5 units a day, so they need 36/5 = 7.2 days. Six days is the time for all three together.","difficulty":"hard","questionHi":"A, B से 50% अधिक कार्यकुशल है और B, C से दो गुना कार्यकुशल है। यदि अकेले C को कार्य पूरा करने में 36 दिन लगते हैं, तो A और B मिलकर उसे कितने दिन में पूरा करेंगे?","optionsHi":["6 दिन","8 दिन","7.2 दिन","7.5 दिन"],"explanationHi":"C = 1 इकाई/दिन लें, तो B = 2 और A = 3 इकाई/दिन, तथा कार्य 36 इकाई का है। A और B प्रतिदिन 5 इकाई करते हैं, अतः 36/5 = 7.2 दिन लगेंगे। 6 दिन तीनों के साथ मिलकर कार्य करने का समय है।","subtopic":"efficiency","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-187","question":"A and B together can finish a job in 10 days, and A is 1.5 times as efficient as B. A works alone for 2 days and then leaves, and B finishes the rest. In how many days in all is the job finished?","options":["24 days","22 days","20 days","26 days"],"answer":0,"explanation":"Together 1/10 per day, split 3 : 2, so A = 0.06 and B = 0.04 per day. A's 2 days do 0.12, leaving 0.88, which B does in 0.88/0.04 = 22 days. Total = 2 + 22 = 24 days.","difficulty":"hard","questionHi":"A और B मिलकर किसी कार्य को 10 दिन में पूरा कर सकते हैं और A, B से 1.5 गुना कार्यकुशल है। A अकेला 2 दिन कार्य करके चला जाता है और शेष कार्य B पूरा करता है। कार्य कुल कितने दिन में पूरा होता है?","optionsHi":["24 दिन","22 दिन","20 दिन","26 दिन"],"explanationHi":"साथ मिलकर प्रतिदिन 1/10 कार्य, जो 3 : 2 में बँटता है, अतः A = 0.06 और B = 0.04 प्रतिदिन। A के 2 दिन में 0.12 कार्य होता है, शेष 0.88 कार्य B 0.88/0.04 = 22 दिन में करता है। कुल = 2 + 22 = 24 दिन।","subtopic":"efficiency","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-188","question":"A takes 6 days less than B to finish a job alone, and together they finish it in 4 days. In how many days can B alone finish it?","options":["6 days","10 days","18 days","12 days"],"answer":3,"explanation":"If B takes x days, 1/x + 1/(x − 6) = 1/4 gives x² − 14x + 24 = 0, so x = 12 or 2. x = 2 is impossible (A would take −4 days), so B takes 12 days and A takes 6.","difficulty":"very-hard","questionHi":"अकेले कार्य पूरा करने में A को B से 6 दिन कम लगते हैं और साथ मिलकर वे उसे 4 दिन में पूरा करते हैं। B अकेला उसे कितने दिन में पूरा करेगा?","optionsHi":["6 दिन","10 दिन","18 दिन","12 दिन"],"explanationHi":"यदि B को x दिन लगें, तो 1/x + 1/(x − 6) = 1/4 से x² − 14x + 24 = 0, अतः x = 12 या 2। x = 2 असंभव है (A को −4 दिन लगते), इसलिए B को 12 दिन और A को 6 दिन लगते हैं।","subtopic":"efficiency","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-189","question":"15 men working 8 hours a day complete 3/5 of a job in 12 days. How many more men, working 10 hours a day, are needed to finish the rest in 4 more days (the 15 men also continue, now at 10 hours a day)?","options":["6","9","12","24"],"answer":1,"explanation":"3/5 of the job = 15 × 8 × 12 = 1,440 man-hours, so the whole is 2,400 and the rest is 960 man-hours. Each man gives 10 × 4 = 40 hours, so 960/40 = 24 men are needed in all, which is 24 − 15 = 9 more.","difficulty":"hard","questionHi":"8 घंटे प्रतिदिन कार्य करते हुए 15 आदमी किसी कार्य का 3/5 भाग 12 दिन में पूरा करते हैं। शेष कार्य को अगले 4 दिन में पूरा करने के लिए 10 घंटे प्रतिदिन कार्य करते हुए कितने और आदमी चाहिए (15 आदमी भी अब 10 घंटे प्रतिदिन कार्य करते रहेंगे)?","optionsHi":["6","9","12","24"],"explanationHi":"कार्य का 3/5 भाग = 15 × 8 × 12 = 1,440 आदमी-घंटे, अतः पूरा कार्य 2,400 और शेष 960 आदमी-घंटे है। प्रत्येक आदमी 10 × 4 = 40 घंटे देता है, इसलिए कुल 960/40 = 24 आदमी चाहिए, यानी 24 − 15 = 9 और।","subtopic":"men-women-children","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-190","question":"8 men and 12 women can finish a job in 10 days, and 6 men and 8 women can finish it in 14 days. In how many days can 10 women alone finish it?","options":["24 days","28 days","32 days","20 days"],"answer":1,"explanation":"10(8m + 12w) = 14(6m + 8w) gives 4m = 8w, so m = 2w. The job is 10 × (16w + 12w) = 280 woman-days, so 10 women need 28 days.","difficulty":"very-hard","questionHi":"8 पुरुष और 12 महिलाएँ किसी कार्य को 10 दिन में और 6 पुरुष और 8 महिलाएँ उसे 14 दिन में पूरा कर सकते हैं। 10 महिलाएँ अकेली उसे कितने दिन में पूरा करेंगी?","optionsHi":["24 दिन","28 दिन","32 दिन","20 दिन"],"explanationHi":"10(8m + 12w) = 14(6m + 8w) से 4m = 8w, अतः m = 2w। कार्य 10 × (16w + 12w) = 280 महिला-दिन का है, इसलिए 10 महिलाओं को 28 दिन लगेंगे।","subtopic":"men-women-children","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-191","question":"4 men and 3 women can finish a job in 10 days, while 5 men alone can finish it in 12 days. In how many days can one woman alone finish it?","options":["60 days","75 days","120 days","90 days"],"answer":3,"explanation":"One man does 1/60 per day. 4 men do 4/60 = 1/15, so 3 women do 1/10 − 1/15 = 1/30, and one woman does 1/90 a day. She needs 90 days.","difficulty":"hard","questionHi":"4 पुरुष और 3 महिलाएँ किसी कार्य को 10 दिन में पूरा कर सकते हैं, जबकि 5 पुरुष अकेले उसे 12 दिन में पूरा कर सकते हैं। एक महिला अकेली उसे कितने दिन में पूरा करेगी?","optionsHi":["60 दिन","75 दिन","120 दिन","90 दिन"],"explanationHi":"एक पुरुष प्रतिदिन 1/60 कार्य करता है। 4 पुरुष 4/60 = 1/15 करते हैं, अतः 3 महिलाएँ 1/10 − 1/15 = 1/30 करती हैं और एक महिला प्रतिदिन 1/90 करती है। उसे 90 दिन लगेंगे।","subtopic":"men-women-children","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-192","question":"24 men can finish a job in 20 days. After 5 days 8 men leave, and after 5 more days 4 new men join the remaining workers. In all, how many days does the job take?","options":["24 days","25 days","22 days","26 days"],"answer":0,"explanation":"Total = 24 × 20 = 480 man-days. First 5 days use 120, the next 5 days use 16 × 5 = 80, leaving 280. With 20 men that takes 14 days, so the total is 5 + 5 + 14 = 24 days.","difficulty":"hard","questionHi":"24 आदमी किसी कार्य को 20 दिन में पूरा कर सकते हैं। 5 दिन बाद 8 आदमी चले जाते हैं और 5 दिन और बाद 4 नए आदमी शेष कर्मचारियों के साथ जुड़ जाते हैं। कार्य में कुल कितने दिन लगते हैं?","optionsHi":["24 दिन","25 दिन","22 दिन","26 दिन"],"explanationHi":"कुल कार्य = 24 × 20 = 480 आदमी-दिन। पहले 5 दिन में 120, अगले 5 दिन में 16 × 5 = 80 खर्च होते हैं, शेष 280 बचता है। 20 आदमियों को इसमें 14 दिन लगते हैं, इसलिए कुल 5 + 5 + 14 = 24 दिन।","subtopic":"men-women-children","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-193","question":"12 men working 6 hours a day can reap 40 acres in 15 days. In how many days can 18 men working 9 hours a day reap 60 acres?","options":["12 days","9 days","10 days","8 days"],"answer":2,"explanation":"One acre needs 12 × 15 × 6/40 = 27 man-hours, so 60 acres need 1,620 man-hours. Per day the 18 men give 18 × 9 = 162, so they take 1,620/162 = 10 days.","difficulty":"moderate","questionHi":"6 घंटे प्रतिदिन कार्य करते हुए 12 आदमी 40 एकड़ की फसल 15 दिन में काट सकते हैं। 9 घंटे प्रतिदिन कार्य करते हुए 18 आदमी 60 एकड़ की फसल कितने दिन में काटेंगे?","optionsHi":["12 दिन","9 दिन","10 दिन","8 दिन"],"explanationHi":"एक एकड़ के लिए 12 × 15 × 6/40 = 27 आदमी-घंटे चाहिए, अतः 60 एकड़ के लिए 1,620 आदमी-घंटे। प्रतिदिन 18 आदमी 18 × 9 = 162 घंटे देते हैं, इसलिए उन्हें 1,620/162 = 10 दिन लगेंगे।","subtopic":"men-women-children","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-194","question":"A contractor agrees to build a 3 km road in 120 days with 100 men. After 40 days only 0.75 km is built. How many extra men must he hire to finish on time?","options":["25","75","50","100"],"answer":2,"explanation":"100 men build 0.75 km in 40 days, so one man builds 0.75/4,000 km a day. The remaining 2.25 km in 80 days needs 2.25 ÷ 80 = 0.028125 km a day, which takes 150 men, i.e. 50 more.","difficulty":"hard","questionHi":"एक ठेकेदार 100 आदमियों के साथ 120 दिन में 3 km सड़क बनाने का ठेका लेता है। 40 दिन बाद केवल 0.75 km सड़क बन पाती है। समय पर कार्य पूरा करने के लिए उसे कितने और आदमी लगाने होंगे?","optionsHi":["25","75","50","100"],"explanationHi":"100 आदमी 40 दिन में 0.75 km बनाते हैं, अतः एक आदमी प्रतिदिन 0.75/4,000 km बनाता है। शेष 2.25 km को 80 दिन में बनाने के लिए प्रतिदिन 2.25 ÷ 80 = 0.028125 km चाहिए, जिसके लिए 150 आदमी लगेंगे, यानी 50 और।","subtopic":"men-women-children","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-195","question":"Pipes A and B can fill a tank in 20 and 30 minutes, and pipe C can empty a full tank in 15 minutes. If the tank is half full and all three pipes are opened together, how long will it take to fill?","options":["30 minutes","60 minutes","20 minutes","25 minutes"],"answer":0,"explanation":"Net rate = 1/20 + 1/30 − 1/15 = (3 + 2 − 4)/60 = 1/60 of the tank per minute. Half the tank needs (1/2) ÷ (1/60) = 30 minutes; 60 minutes is for an empty tank.","difficulty":"hard","questionHi":"नल A और B एक टंकी को क्रमशः 20 और 30 मिनट में भर सकते हैं और नल C पूरी भरी टंकी को 15 मिनट में खाली कर सकता है। यदि टंकी आधी भरी है और तीनों नल एक साथ खोल दिए जाएँ, तो टंकी भरने में कितना समय लगेगा?","optionsHi":["30 मिनट","60 मिनट","20 मिनट","25 मिनट"],"explanationHi":"शुद्ध दर = 1/20 + 1/30 − 1/15 = (3 + 2 − 4)/60 = टंकी का 1/60 प्रति मिनट। आधी टंकी भरने में (1/2) ÷ (1/60) = 30 मिनट लगते हैं; 60 मिनट खाली टंकी के लिए है।","subtopic":"pipes-cisterns","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-196","question":"Pipe A can fill an empty tank in 20 minutes and pipe B can empty a full tank in 30 minutes. They are opened alternately for one minute each, A first. How long does the tank take to fill?","options":["120 minutes","116⅔ minutes","114 minutes","115 minutes"],"answer":3,"explanation":"In 2 minutes the net gain is 1/20 − 1/30 = 1/60, so after 57 pairs (114 min) the tank is 57/60 full. In the next minute A adds 3/60 and fills it exactly, so the tank is full at 115 minutes, before B can drain anything. Dividing 60 by the net rate gives the trap 120.","difficulty":"very-hard","questionHi":"नल A एक खाली टंकी को 20 मिनट में भर सकता है और नल B एक पूरी भरी टंकी को 30 मिनट में खाली कर सकता है। उन्हें एक-एक मिनट के लिए बारी-बारी से खोला जाता है, पहले A। टंकी भरने में कितना समय लगेगा?","optionsHi":["120 मिनट","116⅔ मिनट","114 मिनट","115 मिनट"],"explanationHi":"2 मिनट में शुद्ध वृद्धि 1/20 − 1/30 = 1/60 होती है, अतः 57 जोड़ी (114 मिनट) बाद टंकी 57/60 भरी होती है। अगले मिनट में A 3/60 भरकर उसे ठीक पूरा भर देता है, इसलिए B के कुछ निकालने से पहले ही 115 मिनट पर टंकी भर जाती है। 60 को शुद्ध दर से भाग देने पर गलत 120 आता है।","subtopic":"pipes-cisterns","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-197","question":"A pipe fills a tank in 8 hours, but because of a leak it takes 2 hours more. If the tank is full and the pipe is shut, in how many hours will the leak empty half of the tank?","options":["40 hours","20 hours","10 hours","25 hours"],"answer":1,"explanation":"Leak rate = 1/8 − 1/10 = 1/40 per hour, so it empties a full tank in 40 hours and half of it in 20 hours.","difficulty":"hard","questionHi":"एक नल एक टंकी को 8 घंटे में भरता है, किंतु एक रिसाव के कारण उसे 2 घंटे अधिक लगते हैं। यदि टंकी भरी हुई है और नल बंद कर दिया जाए, तो रिसाव टंकी को आधा खाली करने में कितने घंटे लेगा?","optionsHi":["40 घंटे","20 घंटे","10 घंटे","25 घंटे"],"explanationHi":"रिसाव की दर = 1/8 − 1/10 = 1/40 प्रति घंटा, अतः वह पूरी टंकी 40 घंटे में और आधी टंकी 20 घंटे में खाली करता है।","subtopic":"pipes-cisterns","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-198","question":"Pipes A, B and C can fill a tank in 10, 12 and 15 minutes. All three are opened together. After 2 minutes C is closed, and after 2 more minutes B is closed, and A fills the rest. How long does the tank take to fill in all?","options":["5 minutes","5⅓ minutes","5½ minutes","6 minutes"],"answer":1,"explanation":"Take the tank as 60 units; the rates are A = 6, B = 5, C = 4 per minute. First 2 minutes: 15 × 2 = 30; next 2 minutes (A, B): 11 × 2 = 22; 8 units remain for A, taking 8/6 = 4/3 minutes. Total = 2 + 2 + 4/3 = 5⅓ minutes.","difficulty":"hard","questionHi":"नल A, B और C एक टंकी को क्रमशः 10, 12 और 15 मिनट में भर सकते हैं। तीनों को एक साथ खोला जाता है। 2 मिनट बाद C बंद कर दिया जाता है और 2 मिनट और बाद B बंद कर दिया जाता है तथा शेष टंकी A भरता है। टंकी भरने में कुल कितना समय लगता है?","optionsHi":["5 मिनट","5⅓ मिनट","5½ मिनट","6 मिनट"],"explanationHi":"टंकी को 60 इकाई मानें; दरें A = 6, B = 5, C = 4 प्रति मिनट हैं। पहले 2 मिनट: 15 × 2 = 30; अगले 2 मिनट (A, B): 11 × 2 = 22; शेष 8 इकाई A भरता है, जिसमें 8/6 = 4/3 मिनट लगते हैं। कुल = 2 + 2 + 4/3 = 5⅓ मिनट।","subtopic":"pipes-cisterns","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-199","question":"Two pipes together can fill a tank in 20 minutes. The faster pipe alone takes 9 minutes less than the slower one. How long does the faster pipe alone take?","options":["30 minutes","45 minutes","40 minutes","36 minutes"],"answer":3,"explanation":"If the faster takes x minutes, 1/x + 1/(x + 9) = 1/20 gives x² − 31x − 180 = 0, so x = 36 (the other root is negative). The slower takes 45; check 1/36 + 1/45 = 1/20.","difficulty":"very-hard","questionHi":"दो नल मिलकर एक टंकी को 20 मिनट में भर सकते हैं। तेज नल अकेला धीमे नल से 9 मिनट कम लेता है। तेज नल अकेला टंकी को कितने समय में भरेगा?","optionsHi":["30 मिनट","45 मिनट","40 मिनट","36 मिनट"],"explanationHi":"यदि तेज नल x मिनट लेता है, तो 1/x + 1/(x + 9) = 1/20 से x² − 31x − 180 = 0, अतः x = 36 (दूसरा मूल ऋणात्मक है)। धीमा नल 45 मिनट लेता है; जाँच: 1/36 + 1/45 = 1/20।","subtopic":"pipes-cisterns","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-200","question":"Five identical taps can fill a tank in 36 minutes. If 3 of these taps are open and a leak that alone can empty the full tank in 90 minutes is also present, how long will the tank take to fill?","options":["180 minutes","60 minutes","120 minutes","90 minutes"],"answer":0,"explanation":"One tap = 1/180 per minute, so 3 taps = 3/180 = 1/60. Net rate = 1/60 − 1/90 = 1/180, so the tank takes 180 minutes (3 hours). Ignoring the leak gives 60.","difficulty":"hard","questionHi":"पाँच एक जैसे नल एक टंकी को 36 मिनट में भर सकते हैं। यदि इनमें से 3 नल खुले हों और एक रिसाव भी हो जो अकेले पूरी टंकी को 90 मिनट में खाली कर सकता है, तो टंकी भरने में कितना समय लगेगा?","optionsHi":["180 मिनट","60 मिनट","120 मिनट","90 मिनट"],"explanationHi":"एक नल = 1/180 प्रति मिनट, अतः 3 नल = 3/180 = 1/60। शुद्ध दर = 1/60 − 1/90 = 1/180, इसलिए टंकी भरने में 180 मिनट (3 घंटे) लगते हैं। रिसाव को छोड़ देने पर 60 आता है।","subtopic":"pipes-cisterns","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-201","question":"A and B can do a job alone in 20 and 30 days. They start together, but A leaves after some days and B finishes the job, so that the whole work lasts 18 days. After how many days did A leave?","options":["6 days","10 days","8 days","12 days"],"answer":2,"explanation":"B works all 18 days, doing 18/30 = 3/5. The other 2/5 is A's, so A worked (2/5) × 20 = 8 days.","difficulty":"hard","questionHi":"A और B किसी कार्य को अकेले क्रमशः 20 और 30 दिन में कर सकते हैं। वे साथ शुरू करते हैं, किंतु कुछ दिन बाद A चला जाता है और B कार्य पूरा करता है, जिससे पूरा कार्य 18 दिन चलता है। A कितने दिन बाद गया?","optionsHi":["6 दिन","10 दिन","8 दिन","12 दिन"],"explanationHi":"B पूरे 18 दिन कार्य करता है और 18/30 = 3/5 कार्य करता है। शेष 2/5 कार्य A का है, अतः A ने (2/5) × 20 = 8 दिन कार्य किया।","subtopic":"leaving-joining","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-202","question":"10 men can finish a job in 18 days. After 6 days 4 men leave. In all, how many days does the job take?","options":["24 days","28 days","26 days","30 days"],"answer":2,"explanation":"Total work = 180 man-days; 6 days use 60, leaving 120. With 6 men that takes 120/6 = 20 more days, so the total is 6 + 20 = 26 days.","difficulty":"moderate","questionHi":"10 आदमी किसी कार्य को 18 दिन में पूरा कर सकते हैं। 6 दिन बाद 4 आदमी चले जाते हैं। कार्य में कुल कितने दिन लगते हैं?","optionsHi":["24 दिन","28 दिन","26 दिन","30 दिन"],"explanationHi":"कुल कार्य = 180 आदमी-दिन; 6 दिन में 60 खर्च होते हैं, शेष 120 बचता है। 6 आदमियों को इसमें 120/6 = 20 दिन और लगते हैं, अतः कुल 6 + 20 = 26 दिन।","subtopic":"leaving-joining","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-203","question":"A, B and C can do a job alone in 15, 20 and 30 days. A and B start the job. C joins them after 3 days, and A leaves 2 days after C joins. In all, how many days does the job take?","options":["9.2 days","9 days","9½ days","10 days"],"answer":0,"explanation":"With the job as 60 units the rates are A = 4, B = 3, C = 2. First 3 days: 7 × 3 = 21. Next 2 days (A, B, C): 9 × 2 = 18, total 39. The remaining 21 units are done by B and C at 5 a day in 4.2 days. Total = 3 + 2 + 4.2 = 9.2 days.","difficulty":"very-hard","questionHi":"A, B और C किसी कार्य को अकेले क्रमशः 15, 20 और 30 दिन में कर सकते हैं। A और B कार्य शुरू करते हैं। 3 दिन बाद C उनके साथ जुड़ जाता है और C के जुड़ने के 2 दिन बाद A चला जाता है। कार्य में कुल कितने दिन लगते हैं?","optionsHi":["9.2 दिन","9 दिन","9½ दिन","10 दिन"],"explanationHi":"कार्य को 60 इकाई मानें तो दरें A = 4, B = 3, C = 2 हैं। पहले 3 दिन: 7 × 3 = 21। अगले 2 दिन (A, B, C): 9 × 2 = 18, कुल 39। शेष 21 इकाई B और C 5 प्रतिदिन की दर से 4.2 दिन में करते हैं। कुल = 3 + 2 + 4.2 = 9.2 दिन।","subtopic":"leaving-joining","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-204","question":"A can finish a job alone in 12 days and B in 8 days. A starts the job, and B joins him after 4 days. In all, how many days does the job take?","options":["7 days","8 days","7½ days","7.2 days"],"answer":3,"explanation":"A does 4/12 = 1/3 in 4 days, leaving 2/3. Together they do 1/12 + 1/8 = 5/24 a day, so the rest takes (2/3) ÷ (5/24) = 3.2 days. Total = 4 + 3.2 = 7.2 days.","difficulty":"hard","questionHi":"A किसी कार्य को अकेले 12 दिन में और B 8 दिन में पूरा कर सकता है। A कार्य शुरू करता है और 4 दिन बाद B उसके साथ जुड़ जाता है। कार्य में कुल कितने दिन लगते हैं?","optionsHi":["7 दिन","8 दिन","7½ दिन","7.2 दिन"],"explanationHi":"A 4 दिन में 4/12 = 1/3 कार्य करता है, शेष 2/3 रहता है। साथ में वे प्रतिदिन 1/12 + 1/8 = 5/24 कार्य करते हैं, अतः शेष कार्य में (2/3) ÷ (5/24) = 3.2 दिन लगते हैं। कुल = 4 + 3.2 = 7.2 दिन।","subtopic":"leaving-joining","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-205","question":"A and B can do a job in 12 days, B and C in 15 days, and C and A in 20 days. In how many days can C alone do it?","options":["30 days","60 days","20 days","40 days"],"answer":1,"explanation":"Adding, 2(A + B + C) = 1/12 + 1/15 + 1/20 = 1/5, so A + B + C = 1/10. Then C = 1/10 − 1/12 = 1/60, so C alone takes 60 days.","difficulty":"hard","questionHi":"A और B किसी कार्य को 12 दिन में, B और C 15 दिन में तथा C और A 20 दिन में कर सकते हैं। C अकेला उसे कितने दिन में करेगा?","optionsHi":["30 दिन","60 दिन","20 दिन","40 दिन"],"explanationHi":"तीनों को जोड़ने पर 2(A + B + C) = 1/12 + 1/15 + 1/20 = 1/5, अतः A + B + C = 1/10। तब C = 1/10 − 1/12 = 1/60, इसलिए C अकेला 60 दिन लेगा।","subtopic":"combined-work","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-206","question":"A can do 1/3 of a job in 5 days and B can do 2/5 of the same job in 10 days. In how many days can they do the whole job together?","options":["9¼ days","9⅜ days","9½ days","10 days"],"answer":1,"explanation":"A takes 5 × 3 = 15 days and B takes 10 × 5/2 = 25 days for the whole job. Together 1/15 + 1/25 = 8/75, so the time is 75/8 = 9⅜ days.","difficulty":"hard","questionHi":"A किसी कार्य का 1/3 भाग 5 दिन में और B उसी कार्य का 2/5 भाग 10 दिन में कर सकता है। दोनों मिलकर पूरा कार्य कितने दिन में करेंगे?","optionsHi":["9¼ दिन","9⅜ दिन","9½ दिन","10 दिन"],"explanationHi":"A को पूरा कार्य करने में 5 × 3 = 15 दिन और B को 10 × 5/2 = 25 दिन लगते हैं। साथ में 1/15 + 1/25 = 8/75, अतः समय 75/8 = 9⅜ दिन।","subtopic":"combined-work","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-207","question":"A is twice as fast as B, and B is three times as fast as C. All three working together finish a job in 11 days. In how many days can C alone finish it?","options":["66 days","99 days","121 days","110 days"],"answer":3,"explanation":"Take C = 1 unit a day, so B = 3 and A = 6. Together 10 units a day, so the job is 110 units, and C alone needs 110 days.","difficulty":"hard","questionHi":"A, B से दो गुना तेज है और B, C से तीन गुना तेज है। तीनों मिलकर किसी कार्य को 11 दिन में पूरा करते हैं। C अकेला उसे कितने दिन में पूरा करेगा?","optionsHi":["66 दिन","99 दिन","121 दिन","110 दिन"],"explanationHi":"C = 1 इकाई प्रतिदिन लें, तो B = 3 और A = 6। साथ में 10 इकाई प्रतिदिन, अतः कार्य 110 इकाई का है और C अकेले को 110 दिन लगेंगे।","subtopic":"combined-work","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-time-work-208","question":"A and B together can finish a job in 10 days, and A alone can finish it in 15 days. A works alone for 6 days and then leaves. How many more days does B alone need to finish the job?","options":["18 days","12 days","15 days","24 days"],"answer":0,"explanation":"B's rate = 1/10 − 1/15 = 1/30. A's 6 days do 6/15 = 2/5, leaving 3/5, which B does in (3/5) × 30 = 18 days.","difficulty":"hard","questionHi":"A और B मिलकर किसी कार्य को 10 दिन में पूरा कर सकते हैं और A अकेला उसे 15 दिन में पूरा कर सकता है। A अकेला 6 दिन कार्य करके चला जाता है। कार्य पूरा करने के लिए B अकेले को और कितने दिन चाहिए?","optionsHi":["18 दिन","12 दिन","15 दिन","24 दिन"],"explanationHi":"B की दर = 1/10 − 1/15 = 1/30। A के 6 दिन में 6/15 = 2/5 कार्य होता है, शेष 3/5 कार्य B (3/5) × 30 = 18 दिन में करता है।","subtopic":"combined-work","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

